quests[27644] = { id = 27644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eoin Dunwald", description = "Eoin ist einer der Zwillinge. Er trinkt gerne mal einen über den Durst. Wahrscheinlich findet Ihr ihn beim alten Brunnen. Dort haben wir nämlich in einem Gebäude unser Bier gelagert.\n\nKönntet Ihr ihn vielleicht überreden, seiner besorgten Schwester einen Besuch abzustatten? Wenn Ihr zuerst an das Bier gelangt, sollte er sich bestimmt nicht lange bitten lassen.", sourceObjective = "Findet Eoin Dunwald.", completion = "Warum musste von allen Gebäuden dieser Stadt ausgerechnet dieses hier einstürzen?!", sourceObjectiveStatus = "unverified-source-field" }
quests[27645] = { id = 27645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cayden Dunwald", description = "Cayden ist der andere Zwilling. Auch ihn dürstet es, aber nicht nach Bier. Er amüsiert sich sicher köstlich, seit der Schattenhammer an unsere Tür geklopft hat. Vielleicht kann er so ein paar Aggressionen loswerden.\n\nIch schätze, Ihr sucht am besten in der Marktgasse bei der alten Schmiede nach ihm. Er hat sich schon früher immer gerne dort aufgehalten, aber da sich an diesem Ort die meisten Anhänger des Schattenhammers tummeln, hat er wahrscheinlich jetzt noch mehr Grund, ihn sein Zuhause zu nennen.\n\nBringt ihn zu mir zurück. Unversehrt, falls möglich.", sourceObjective = "Findet Cayden Dunwald.", completion = "Schaut Euch nur an mit all der Ausrüstung und dem Schnickschnack. Keely hat Euch also geschickt, damit Ihr auf den alten Cayden aufpasst, ja? Nicht nötig! Ich habe diese Flegel im Griff.\n\nHaha! Sie haben heute dem falschen {race} aufgelauert! Ahahahahaha!", sourceObjectiveStatus = "unverified-source-field" }
quests[27646] = { id = 27646, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach Schnäbelchen", description = "Ich hab' meinen Greifen verloren. Schnäbelchen! Wo bist du, Schnäbelchen?!\n\nHelft Ihr mir, ihn zu finden? Ich weiß, dass er irgendwo in den Hütten ist. Muss er einfach sein!\n\nSchnäbelchen?! Wo tust du denn stecken?\n\nIch hoffe, ihm fehlt nichts.", sourceObjective = "Helft Donnelly dabei, Schnäbelchen in den Hütten von Dunwald zu finden.", progress = "Habt Ihr ihn gefund'n?! Bitte?", completion = "Ihr habt ihn gefund'n! Ihr habt Schnäbelchen gefund'n! Ich mag Euch, mein neuer Freund!\n\nIch werde ihn gleich Keely zeigen. Keely tut Schnäbelchen auch mögen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27647] = { id = 27647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles außer Wasser", description = "Schaut, Kumpel. Entweder helft Ihr mir, etwas zu trinken zu finden, oder Ihr geht mir aus dem Weg.\n\nWarum schaut Ihr nicht unten im alten Lagerhaus nach? Ich hatte den alten Buchhalter da nämlich schon immer im Verdacht, dass er sich heimlich das ein oder andere Gläschen zwischen den Zeilen gönnt. Ich wette, er hat ein Fass im Keller versteckt.\n\nWenn Ihr etwas findet, dann kommt sofort zu mir zurück. Nicht trödeln! Das hier ist brandeilig.", sourceObjective = "Durchsucht den Keller, von dem Eoin Dunwald gesprochen hat, nach einem Fass.", progress = "Ihr stinkt nach Nüchternheit! Sucht mir etwas zu trinken!", completion = "Bei Donnellys Dickbauch! Das sieht schon besser aus. Wie schön, dass ich jetzt nicht mehr verdursten muss.\n\nHier, nehmt einen Schluck. Der gute alte Eoin ist nie so unhöflich, nicht zu teilen!", sourceObjectiveStatus = "unverified-source-field" }
quests[27648] = { id = 27648, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durch diese hohle Gasse muss er kommen", description = "In Ordnung, in Ordnung. Ihr wollt also auch etwas von dem Spaß haben? Fein, Ihr könnt mitmachen.\n\nLasst mich wissen, wenn Ihr bereit seid.", sourceObjective = "Begleitet Cayden Dunwald durch den etwas offensichtlichen Hinterhalt.", progress = "Sie kommen immer wieder, und ich hau weiter drauf.", completion = "Wundervoll, oder? Und sie können nicht genug davon bekommen. Ich liebe es!\n\nIch werde zu Keely gehen und sie ein wenig beruhigen. Nur noch ein Durchgang!", sourceObjectiveStatus = "unverified-source-field" }
quests[27649] = { id = 27649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stete Versorgung", description = "He, Kumpel. Da Ihr ja so freundlich und toll und so seid, könntet Ihr einem Zwerg vielleicht einen Gefallen tun?\n\nDies sind die Ruinen der Dunwalds… Es MUSS einfach mehr Vorräte in einem dieser Gebäude geben. Wenn Ihr noch etwas Bier findet, würdet Ihr es mir dann bringen? Ja? Ein guter Zwerg kann nie genug bekommen!\n\nIch werde mich auf den Weg zu Keely machen, also werdet Ihr mich vielleicht suchen müssen. Aber keine Sorge, es wird Eure Mühe wert sein.", sourceObjective = "Sammelt 6 Fässer Wildhammerbier.", progress = "Wo ist mein gutes Gesöff?", completion = "Whoohooo! Genau das verlangt mein Magen!\n\nIhr bringt mir wirklich lauter nette Sachen!", sourceObjectiveStatus = "unverified-source-field" }
quests[27650] = { id = 27650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wieder zuhause", description = "Ihr solltet Keely aufsuchen. Sie ist bestimmt auf Eure Neuigkeiten gespannt.", sourceObjective = "Sprecht mit Keely Dunwald in der Bastion der Dunwalds.", completion = "Vielen Dank, dass Ihr meine Brüder wieder zusammengetrommelt habt. Ich weiß, sie sind harte Brocken, aber Seite an Seite sind sie noch härter, und da draußen sind ganz schön viele Kultisten des Schattenhammers.\n\nIhr habt einem armen Mädchen eine schwere Last von der Seele genommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27651] = { id = 27651, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Dunwälder Art", description = "Sie sind schon auf dem Weg, um den Ettin zu jagen, der den Angriff auf den Besitz der Dunwalds angeführt hat. Ich habe sie gebeten, Euch wenigstens eine Chance zu lassen, sie einzuholen, aber ich bin mir nicht sicher, ob das Warten ihnen liegt.\n\nSie sind in Richtung Ratsplatz gegangen, in die Mitte der Ruinen. Ihr solltet zu ihnen aufschließen, wenn Ihr auch mit von der Partie sein wollt.", sourceObjective = "Sprecht mit Flynn Dunwald und helft den Dunwaldbrüdern dabei, Darunga zu töten.", completion = "Vielen Dank für Eure Hilfe. Ihr habt das Herz eines Kriegers. Fast hätt' ich Euch für einen Wildhammer gehalten, wenn Ihr nicht… nun ja… Ihr wisst schon.\n\nIch weiß, dass Feuerbart Euch geschickt hat, um uns zu vereinen. Meine Sympathie für diesen {race} ist alles andere als groß, aber Ihr wisst ja jetzt, dass wir genügend Gründe haben, um den Schattenhammer als Feind zu betrachten. Sagt ihm, dass er auf die Familie Dunwald zählen kann, wenn die Schlacht beginnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27652] = { id = 27652, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkle Auftragsmörder", description = "Sogar ich werde gejagt. Das hat man eben davon, wenn man sich unter Schafen versteckt.\n\n<Mathias mustert Euch einen Augenblick lang.>\n\nDer Schattenhammer hat einen Zahn zugelegt und seine dunklen Auftragsmörder nach mir geschickt. Nette Kerle, doch leider alle tot. Sie bestehen aus den Seelen der fähigsten Attentäter.\n\nMöchtet Ihr mir einen Gefallen tun? Dann bringt sie zur Strecke und beschafft mir ihre Seelenanhänger.", sourceObjective = "Sammelt 5 Anhänger eines dunklen Auftragsmörders.", progress = "Wie viele Anhänger habt Ihr?", completion = "Ich bin mir nicht sicher, was ich mit all diesen Dingern tun soll. Wahrscheinlich werde ich sie verhökern und den Ertrag dem Waisenhaus in Sturmwind stiften.\n\nJetzt muss ich nur noch jemanden finden, der geisteskrank genug ist, so etwas zu kaufen. Wahrscheinlich ein Goblin. Oder ein gnomischer Hexenmeister.", sourceObjectiveStatus = "unverified-source-field" }
quests[27653] = { id = 27653, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkle Auftragsmörder", description = "Sogar ich werde gejagt. Das hat man eben davon, wenn man sich unter Schafen versteckt.\n\n<Garona mustert Euch einen Augenblick lang.>\n\nDer Schattenhammer hat einen Zahn zugelegt und seine dunklen Auftragsmörder nach mir geschickt. Nicht schlecht für einen haufen toter Kerle. Sie bestehen aus den Seelen der fähigsten Attentäter.\n\nMöchtet Ihr mir einen Gefallen tun? Dann bringt sie zur Strecke.\n\nSie tragen ihre Seelen in Anhängern um den Hals. Bringt sie mir. Die Seelen sind optional.", sourceObjective = "Sammelt 5 Anhänger eines dunklen Auftragsmörders.", progress = "Wie viele Anhänger habt Ihr?", completion = "Was soll ich nur mit all diesen Dingern tun? Vielleicht lasse ich sie einschmelzen und mache mir aus dem Metall einen neuen Dolch, den ich Cho'gall ins Herz stoßen kann.\n\nMeint Ihr, dafür haben wir genug Zeit?", sourceObjectiveStatus = "unverified-source-field" }
quests[27654] = { id = 27654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nieder mit dem Hammer", description = "Ein Vorstoß auf das Schlachtfeld wäre nicht vollständig, wenn es keine altmodische \"Macht den bösen Jungs den Garaus\"-Mission gäbe.\n\nIch bin mir sicher, dass Ihr bei all den Veteranen der Zitadelle, den korrumpierten Elementaristen und den Zwielichtverteidigern genügend Ziele findet.\n\nWie Ihr sie zur Strecke bringt, bleibt ganz Euch überlassen.", sourceObjective = "Tötet 10 Veteranen der Zitadelle, korrumpierte Elementaristen und/oder Zwielichtverteidiger.", completion = "Keiner von uns ist zu schade, um sich die Hände dreckig zu machen. Oder in diesem Fall blutig.", sourceObjectiveStatus = "unverified-source-field" }
quests[27655] = { id = 27655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nieder mit dem Hammer", description = "Es gibt nicht Schlimmeres als diese von Selbsthass zerfressenen Kultisten des Schattenhammers. Nichts! Diese Idioten wollen tatsächlich das Ende der Welt herbeiführen.\n\nDas bringt sie ganz oben auf meine Abschussliste.\n\nBei all den Veteranen der Zitadelle, den korrumpierten Elementaristen und den Zwielichtverteidigern gehen Euch die Ziele sicher nicht aus.\n\nWie Ihr sie zur Strecke bringt, ist mir herzlich egal.", sourceObjective = "Tötet 10 Veteranen der Zitadelle, korrumpierte Elementaristen und/oder Zwielichtverteidiger.", completion = "Fühlt sich gut an, so ein bisschen Blut an den Händen, was? Besonders, wenn es das Blut solcher verblendeten Narren ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[27656] = { id = 27656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krokischwemme", description = "Im Stagalsumpf östlich der Stadt wimmelt es von Krokilisken. Wimmelt, hört Ihr? Ich habe jeden vorstellbaren Teil der Krokilisken verkauft.\n\nKrokiliskenhäute, ihre Zähne, Schwänze, Zungen, Augen und so weiter. Was ich damit sagen will: Das verkauft sich nicht mehr. Es gibt zu viele Krokis! Wir haben ein Überangebot und eine Unternachfrage.\n\nDa sie mir also nichts mehr nützen und gelegentlich meine Gäste fressen, möchte ich, dass Ihr die Drecksviecher umbringt. Tut mir den Gefallen, ja? Ich verhandle währenddessen über irgendwas mit Euren Leuten.", sourceObjective = "Tötet 8 Sägezahnkrokilisken.", completion = "Alles erledigt? Freut mich. Eine Sorge weniger.\n\nJetzt kann ich mich auf ordentliche Geschäfte mit den freundlichen Bewohnern von Sumpftidenwacht und Steinard konzentrieren, die vom Krieg gezeichnet sind... und all der Blödsinn.", sourceObjectiveStatus = "unverified-source-field" }
quests[27657] = { id = 27657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hilfe der Erdenruferin", description = "Meine Untersuchungen zu Cho'galls Artefakt sind in einer Sackgasse angelangt. Der Schattenhammer hat eine Gruppe von Schmieden der Wildhämmer versklavt und im See ertränkt, als sie ihre Aufgabe erledigt hatten.\n\n<Mathias spuckt aus.>\n\nWir brauchen Hilfe. Es gibt da eine Erdenruferin des Irdenen Rings mit Namen Yevaa.\n\nSie und ihr goblinischer Initiand halten sich an der Elementiummine im Südwesten auf und brauchen Hilfe dabei, die Elementarportale in der Gegend zu schließen. Im Gegenzug können sie uns sicher bei unserem Problem helfen.", sourceObjective = "Sprecht mit Erdenruferin Yevaa vor den Elementiumtiefen im Schattenhochland.", completion = "{name}! Ich bin froh, dass Ihr hier seid.\n\nNatürlich helfe ich Euch gerne, wo ich kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[27658] = { id = 27658, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hilfe der Erdenruferin", description = "Meine Untersuchungen zu Cho'galls Artefakt sind in einer Sackgasse angelangt. Der Schattenhammer hat eine Gruppe von Schmieden der Wildhämmer versklavt und im See ertränkt, als sie ihre Aufgabe erledigt hatten.\n\n<Garona spuckt aus.>\n\nIch sage es nicht gerne, aber wir brauchen Hilfe. Es gibt da eine Dame des Irdenen Rings, eine Draenei namens Erdenruferin Yevaa. Sie und ihr Goblinschoßhund halten sich in der Elementiummine im Südwesten auf.\n\nSie brauchen Hilfe dabei, die Elementarportale in der Gegend auszuschalten. Im Gegenzug können sie uns bei unserem Problem helfen.", sourceObjective = "Sprecht mit Erdenruferin Yevaa vor den Elementiumtiefen im Schattenhochland.", completion = "{name}! Ich bin froh, dass Ihr hier seid.\n\nNatürlich helfe ich Euch gerne, wo ich kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[27659] = { id = 27659, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überlastung der Portale", description = "Ich war früher die Hüterin der Portale des Irdenen Rings, doch als Ihr in Tiefenheim wart, um zu helfen, ist der Schattenhammer hier eingefallen und hat das Gebiet verderbt.\n\nSie lassen unsere Portale von mächtigen Aszendenten bewachen. Und genau darin liegt ihr Fehler.\n\nIch möchte, dass Ihr zu den Portalen geht und die Steuerungen verwendet, um sie zu überlasten. Dadurch werden die gesamten Energien des Portals freigesetzt und die Aszendenten geschwächt. Tötet sie.", sourceObjective = "Tötet den entkräfteten Apexar, den entkräfteten Aetharon und den entkräfteten Edemantus.", completion = "Das letzte Portal liegt tief in der Mine hier, aber darum kümmern wir uns gleich.", sourceObjectiveStatus = "unverified-source-field" }
quests[27660] = { id = 27660, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geist des Lochs", description = "Ich weiß nichts von einem Artefakt, das Cho'gall herstellt, aber ich glaube, ich kenne jemanden, der Euch helfen kann.\n\nGräfin Verrall ist ein alter Geist, der sich im Loch Verrall im Norden aufhält. Sie hegt keine Sympathie für den Schattenhammer, der ihre Wasser verschmutzt hat.\n\nBittet sie um die Weisheit, die Ihr sucht.", sourceObjective = "Sprecht mit Gräfin Verrall im Loch Verrall im Schattenhochland.", completion = "Ich weiß, warum Ihr hier seid, {name}. Eure Gründe singen im Rauschen Eures Blutes.\n\nIch weiß von dem toten Zwergenschmied, der meine Wasser verschmutzt. Wenn Ihr herausfinden wollt, an was sein Leichnam sich erinnert, dann müsst Ihr es Euch verdienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27661] = { id = 27661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artilleriefeuer", description = "Mein Erzfeind, Lord Artillerius, war so dumm, sich dem Schattenhammer anzuschließen.\n\nIn der Vergangenheit hatten wir einen brüchigen Waffenstillstand geschlossen, aber nach dieser Entscheidung habe ich keine andere Wahl, als ihm ein Ende zu setzen. Oder lasst es mich so ausdrücken: Wenn Ihr Informationen von einem toten Zwerg wollt, müsst Ihr Lord Artillerius für mich töten.\n\nSucht ihn bei Artillerius' Inferno im Südosten auf.", sourceObjective = "Tötet Lord Artillerius.", completion = "Ich bin sehr zufrieden. Lord Artillerius war mir immer ein unwürdiger Gegner.\n\nNun gut, {race}. Ich werde Euch dabei helfen, an die Informationen zu gelangen, die Ihr sucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[27662] = { id = 27662, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pflichtentbindung", description = "Wenn ich mich mit einer Sache auskenne, dann sind es Elementare. Ich habe wirklich gelernt zu verstehen, wie sie empfinden. Und lasst mich Euch sagen: Es gefällt ihnen gar nicht, versklavt zu werden!\n\nIch will damit sagen, dass die Elementare Euch sicher nicht nur dankbar sind, wenn Ihr sie aus der Sklaverei befreit, sondern sich wahrscheinlich auch gegen ihre Meister wenden.\n\nIch finde, das klingt für beide Seiten nach einem Gewinn.", sourceObjective = "Befreit 10 versklavte Elementare in der Schattenzitadelle, indem Ihr sie tötet.", completion = "Was habe ich Euch gesagt? Elementare sind gar nicht so übel, was?", sourceObjectiveStatus = "unverified-source-field" }
quests[27663] = { id = 27663, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmeckt wie Schreiter", description = "Ihr da! Ja, Ihr! Ihr wollt ein gutes Wort beim Handelsbaron eingelegt bekommen? Dann geht mir mal zur Hand!\n\nIch habe gehört, dass Ihr derjenige seid, der die ganzen Makruraschwänze besorgt hat. Die sind zwar toll, aber nicht ausreichend für ein anständiges Sumpfessen. Ich brauche Keulen für mein Gumbo!\n\nEs gibt eine Menge Sumpfschreiter außerhalb der Stadt, im Sorgendunkel. Ich will die größten Keulen, die Ihr finden könnt!", sourceObjective = "Sammelt 9 riesige Sumpfschreiterschenkel von Sumpfschreitern.", progress = "Habt ihr die Keulen?", completion = "Ah, gut, gut! Das war genau, was ich brauchte.", sourceObjectiveStatus = "unverified-source-field" }
quests[27664] = { id = 27664, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vulkankartenset des Dunkelmond-Jahrmarkts", description = "Jetzt, da Ihr alle Karten des Vulkankartensets in einem Set gesammelt habt, erscheint auf geheimnisvolle Weise eine neunte Karte, die dieselbe Rückseite hat, wie die ersten acht. Auf dieser Karte steht: \"Bringt diese Karten zum Dunkelmond-Jahrmarkt und Ihr werdet belohnt werden.\" Ihr habt gehört, dass der Zugang zu diesem Jahrmarkt jeden Monat in der Nähe von Mulgore oder Goldhain erscheint.", sourceObjective = "Gebt das Vulkankartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[27665] = { id = 27665, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hurrikankartenset des Dunkelmond-Jahrmarkts", description = "Jetzt, da Ihr alle Karten des Hurrikankartensets in einem Set gesammelt habt, erscheint auf geheimnisvolle Weise eine neunte Karte, die dieselbe Rückseite hat, wie die ersten acht. Auf dieser Karte steht: \"Bringt diese Karten zum Dunkelmond-Jahrmarkt und Ihr werdet belohnt werden.\" Ihr habt gehört, dass der Zugang zu diesem Jahrmarkt jeden Monat in der Nähe von Mulgore oder Goldhain erscheint.", sourceObjective = "Gebt das Hurrikankartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[27666] = { id = 27666, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tsunamikartenset des Dunkelmond-Jahrmarkts", description = "Jetzt, da Ihr alle Karten des Tsunamikartensets in einem Set gesammelt habt, erscheint auf geheimnisvolle Weise eine neunte Karte, die dieselbe Rückseite hat, wie die ersten acht. Auf dieser Karte steht: \"Bringt diese Karten zum Dunkelmond-Jahrmarkt und Ihr werdet belohnt werden.\" Ihr habt gehört, dass der Zugang zu diesem Jahrmarkt jeden Monat in der Nähe von Mulgore oder Goldhain erscheint.", sourceObjective = "Gebt das Tsunamikartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[27667] = { id = 27667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erdbebenkartenset des Dunkelmond-Jahrmarkts", description = "Jetzt, da Ihr alle Karten des Erdbebenkartensets in einem Set gesammelt habt, erscheint auf geheimnisvolle Weise eine neunte Karte, die dieselbe Rückseite hat, wie die ersten acht. Auf dieser Karte steht: \"Bringt diese Karten zum Dunkelmond-Jahrmarkt und Ihr werdet belohnt werden.\" Ihr habt gehört, dass der Zugang zu diesem Jahrmarkt jeden Monat in der Nähe von Mulgore oder Goldhain erscheint.", sourceObjective = "Gebt das Erdbebenkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[27668] = { id = 27668, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Passt auf!", description = "Hört zu, {race}. Nicht, dass ich die Rettung nicht zu schätzen wüsste, aber wir sind in einer schlimmen Lage.\n\nIhr müsst da draußen besser achtgeben!\n\nIch habe Euch beobachtet. Ihr seid direkt über einer zerbrochenen Kiste der Allianz vorbeigeschwommen.\n\nDa ist sicher etwas drin, das mir und meinen Jungs helfen könnte.\n\nWarum geht Ihr nicht dorthin und schaut einfach mal hinein, hm?", sourceObjective = "Nazgrim möchte, dass Ihr nachschaut, was in der zerbrochenen Kiste der Allianz nördlich der \"Ewiger Kreislauf\" liegt.", completion = "Ja…\n\nDas sieht aus wie etwas, an dem Nazgrim sehr interessiert sein wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[27669] = { id = 27669, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr habt die Ehre", description = "Anscheinend müssen jetzt nur noch die Kugeln auf die Sockel in jeder Ecke dieses Mechanismus gelegt werden.\n\nWir sind offenbar über den wichtigsten Fund der modernen Geschichte gestolpert.\n\n<Harrison schaut Euch eine Weile an und gibt Euch dann die Kugeln.>\n\nNur zu, {name}.\n\nOhne Euch hätten wir diese Entdeckung nie gemacht.", sourceObjective = "Benutzt die Kugeln der Sterne in der Nähe des Mechanismus in der Kammer der Sterne.", completion = "Jetzt schaut Euch das an!\n\nSo erstaunlich dies auch sein mag, ich bin sicher, dass hinter unserer Entdeckung noch mehr steckt.\n\nWesentlich mehr.", sourceObjectiveStatus = "unverified-source-field" }
quests[27670] = { id = 27670, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eingekesselt", description = "Mein Name ist Nevin Drallzang und ich bin der Kommandant von S.I.C.H.E.R.\n\nIch weiß nicht, wie Ihr die Strahlung hier unten überlebt habt, {name}, aber die meisten anderen hatten nicht so viel Glück. Mein Team sammelt zwar die Überlebenden, aber es gibt so viele strahlungsverwirrte Lepragnome, dass wir sie nicht mehr lange zurückdrängen können. Sie haben den Verstand verloren!\n\nSolltet Ihr noch stark genug sein, um eine Waffe zu heben oder einen Zauber zu wirken, könntet Ihr uns helfen, ein paar dieser Lepragnome auszuschalten.", sourceObjective = "Tötet 6 wahnsinnige Lepragnome.", progress = "Helft meinen Männern, eine Schneise zu schlagen, damit wir die anderen Überlebenden rausbringen können!", completion = "Gut gemacht, {name}. Meine Männer werden jetzt übernehmen. Konzentrieren wir uns darauf, die anderen Überlebenden herauszubringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27671] = { id = 27671, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kümmert Euch um die Überlebenden", description = "Wenn wir nicht bald handeln, werden weder Nevin noch die Überlebenden hier heil herauskommen. Ich werde Euch das Notfallteleportersignal meiner Einheit geben. Wir haben noch genügend Kraft und Munition, um uns nach oben zu kämpfen, aber diese Überlebenden können nicht mithalten.\n\nSetzt das Signal bei den Überlebenden ein, damit sie in die sichere Zone, die meine Männer errichtet haben, teleportiert werden können. Erstattet mir Bericht, sobald das erledigt ist und wir werden dafür sorgen, dass Ihr hier wegkommt.", sourceObjective = "Benutzt das Teleportersignal, um 6 Überlebende in Sicherheit zu teleportieren.", completion = "Es wird Nevin freuen, dass Ihr so vielen Überlebenden helfen konntet. Ich kann immer noch nicht fassen, dass Ihr trotz der Strahlung hier unten noch so stark seid. Ihr habt ja den Zustand der anderen Überlebenden gesehen.\n\nAb mit Euch zum Laderaum zur Dekontamination.", sourceObjectiveStatus = "unverified-source-field" }
quests[27672] = { id = 27672, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kammer von Khaz'mul", description = "In der Kartenkammer gibt es eine Tür, die zur legendären Kammer von Khaz'mul führt. Wer kann schon sagen, welche Geheimnisse darin verborgen sein mögen!\n\nWas wir wissen, ist, dass sie von Ironaya, einer Titanenwächterin von immenser Größe und Macht, bewacht wird. Ihr müsst sie besiegen, wenn Ihr die Geheimnisse von Uldaman entdecken wollt.", sourceObjective = "Besiegt Ironaya.", completion = "Kümmert Euch nicht um die Kammer, meine Jungs werden sie in Augenschein nehmen! Ihr habt Wichtigeres zu tun!", sourceObjectiveStatus = "unverified-source-field" }
quests[27673] = { id = 27673, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es kommt auf die inneren Werte an", description = "Die Schöpfer haben zwei uralte Steinbewahrer gebaut, um Uldaman vor möglichen Eindringlingen zu schützen und die Tagesgeschäfte zu überwachen, während Ironaya und Archaedas schlummern. Einer ist immer noch voll funktionsfähig und befindet sich in der Halle des Tempels, aber der andere in der Echomokhöhle wurde von etwas beschädigt.\n\nIch fürchte, dass einer der Alten Götter dafür verantwortlich ist. Ihr müsst mir helfen herauszufinden, ob das der Fall ist. Überwältigt beide Wächter und bringt mir ihre Kraftkerne. Sie werden uns enthüllen, was wir wissen müssen.", sourceObjective = "Beschafft Euch den Obsidiankraftkern und den Titankraftkern.", progress = "Wo sind die Kerne, mein Junge? Bei Muradins Bart, wo sind die verflixten Kerne?\n\n<Kand atmet tief durch.>\n\nTut mir leid. Konntet Ihr die Kerne an Euch bringen?", completion = "Das ist unglaublich, {name}. Die Kraft, die durch jeden dieser Kerne fließt... Die gegensätzlichen Kräfte so nah beieinander.\n\nIch bringe das sofort zu den richtigen Zwergen. Diese Kerne sind immens wichtig!", sourceObjectiveStatus = "unverified-source-field" }
quests[27674] = { id = 27674, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zur Oberfläche", description = "Nevin hat gerade gemeldet, dass er und seine Leute auf dem Weg zur Oberfläche sind. Er erwartet Euch in dem Gebäude, das S.I.C.H.E.R. zum Hauptquartier erkoren hat.\n\nSeht Ihr Torben Knallschock da hinten? Sprecht mit ihm, wenn Ihr zur Oberfläche aufbrechen wollt und er wird für den Transport sorgen. Es war mir ein Vergnügen, Euch kennenzulernen, {name}. Ich fühle mich geehrt, eine kleine Rolle bei Eurer Flucht aus Gnomeregan und dem Beginn Eures neues Lebens an der Oberfläche gespielt zu haben.", sourceObjective = "Sprecht mit Torben Knallschock, lasst Euch an die Oberfläche teleportieren und meldet Euch bei Nevin Drallzang.", progress = "Schön, Euch wiederzusehen, {name}.", completion = "Schön, Euch wiederzusehen, {name}. Ohne Eure Hilfe wäre es uns dieses Mal nicht gelungen, so viele Überlebende aus Gnomeregan zu retten. Alle wollen Euch treffen und Eure Geschichte hören.", sourceObjectiveStatus = "unverified-source-field" }
quests[27675] = { id = 27675, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefälschte Dokumente", description = "Findet einen Bewohner in Sturmwind, der Eure gefälschten Dokumente annimmt.", progress = "Habt Ihr etwas für mich?", completion = "<Ihr überreicht die gefälschten Dokumente und wechselt dabei nur wenige Worte. Euer meisterhaftes Können spricht für sich selbst.>" }
quests[27676] = { id = 27676, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinter verschlossenen Türen", description = "Galgann Feuerhammer und seine Gruppe Dunkeleisenzwerge halten sich in Grabstelle Drei auf und bewachen dort eine Tür, von der wir nichts wissen! Es reicht! Ständig stören seine Leute unsere Arbeit. Die Forscherliga besitzt als einzige Gruppe die Erlaubnis, die Artefakte in Uldaman zu begutachten!\n\nGeht zur Grabstelle und werdet ihn los, damit wir unsere Arbeit ungestört fortsetzen können. Ich will wissen, was hinter dieser Tür ist!", sourceObjective = "Tötet Galgann Feuerhammer.", completion = "Großartig! Hervorragende Arbeit! Wir werden schon bald wissen, was sich in Grabstelle Drei verbirgt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27677] = { id = 27677, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archaedas, der alte Steinbehüter", description = "Das wahre Ziel in Uldaman ist es, die Scheiben von Norgannon zu erlangen. Die Geheimnisse auf diesen Scheiben könnte die Art, wie wir unsere Welt sehen, völlig verändern. Zahllose Geheimnisse der Schöpfer sind darauf aufgeschrieben... ihr Wert liegt über allem Materiellen, das Ihr Euch nur vorstellen könnt.\n\nDas Problem ist, das Archaedas, eine uralte und mächtige Konstruktion der Schöpfer, die Scheiben mit einer beachtlichen Armee zu seiner Verfügung beschützt. Ihr müsst ihn besiegen und die Scheiben für die Forscherliga sichern!", sourceObjective = "Besiegt Archaedas.", completion = "Gut gemacht, Junge! Geht jetzt zu den Scheiben und erfahrt von ihnen so viel es geht!", sourceObjectiveStatus = "unverified-source-field" }
quests[27678] = { id = 27678, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Platinscheiben", description = "Die Kernstücke dieser Schatzkammer sind vier riesige Platinscheiben, von denen jede mit zahlreichen Siegelzeichen unbekannter Herkunft bedeckt ist. Als Ihr sie berührt, beginnt Eure Hand zu kribbeln. Unmittelbar, nachdem Ihr die Scheiben berührt habt, erscheint das Gesicht eines großen Steinbeobachters.\n\n\"Willkommen. Ich bin ein Hüter des Wissens. Die Schöpfungssynthese der Irdenen wurde hier in den Scheiben von Norgannon für diese Welt aufgezeichnet und aufbewahrt.\"\n\nIhr habt eine Fülle an bislang unbekanntem Wissen über die Welt entdeckt!", sourceObjective = "Sprecht mit dem Steinbehüter und findet heraus, welche uralten Lehren er aufbewahrt. Sobald Ihr alles erfahren habt, was er weiß, aktiviert die Scheiben von Norgannon.", sourceObjectiveStatus = "unverified-source-field" }
quests[27679] = { id = 27679, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kammer von Khaz'mul", description = "In der Kartenkammer befindet sich eine verschlossene Tür, die zur legendären Kammer von Khaz'mul führen muss. Wir wissen noch nicht, was für Artefakte sich darin befinden.\n\nWas wir wissen, ist, dass sie von Ironaya, einer Titanenwächterin von immenser Größe und Macht, bewacht wird. Ihr müsst sie bezwingen, wenn Ihr vorhabt, weiter in diesen Ort vorzudringen.", sourceObjective = "Besiegt Ironaya.", completion = "Agenten der Akademie sind unterwegs, um die Kammer zu untersuchen. Ihr habt Wichtigeres zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[27680] = { id = 27680, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archaedas, der alte Steinbehüter", description = "Das wahre Ziel in Uldaman ist es, die Scheiben von Norgannon zu erlangen. Diese Platinscheiben könnten uns unfassbare Macht verleihen. Zahllose Geheimnisse der Schöpfer sind darauf aufgeschrieben... ihr Wert liegt über allem Materiellen, das Ihr Euch nur vorstellen könnt.\n\nDas Problem ist, das Archaedas, eine uralte und mächtige Konstruktion der Schöpfer, die Scheiben mit einer beachtlichen Armee zu seiner Verfügung beschützt. Ihr müsst ihn besiegen und die Scheiben für die Archäologische Akademie sichern!", sourceObjective = "Besiegt Archaedas.", sourceObjectiveStatus = "unverified-source-field" }
quests[27681] = { id = 27681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinter verschlossenen Türen", description = "Galgann Feuerhammer und seine Gruppe Dunkeleisenzwerge halten sich in Grabstelle Drei auf und bewachen dort eine Tür, von der wir nichts wissen! Es reicht! Ständig stören seine Leute unsere Arbeit. Die Archäologische Akademie besitzt als einzige Gruppe die Erlaubnis, die Artefakte in Uldaman zu begutachten!\n\nGeht zur Grabstelle und werdet ihn los, damit wir unsere Arbeit ungestört fortsetzen können. Ich will wissen, was hinter dieser Tür ist!", sourceObjective = "Tötet Galgann Feuerhammer.", completion = "Gut gemacht! Grabstelle Drei und die Geheimnisse hinter dieser Tür werden bald uns und nur uns gehören.", sourceObjectiveStatus = "unverified-source-field" }
quests[27682] = { id = 27682, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir brauchen mehr Mineralien", description = "Die Titanen haben zwei uralte Steinbewahrer erbaut, um Uldaman vor möglichen Eindringlingen zu schützen und den täglichen Betrieb zu überwachen, während Ironaya und Archaedas schlafen. Einer davon ist noch voll funktionstüchtig und steht in der Tempelhalle. Der andere in der Echomokhöhle wurde jedoch von etwas verderbt.\n\nIch vermute, dass einer der Alten Götter dahinter steckt, und Ihr werdet mir dabei helfen, dieser Vermutung nachzugehen. Überwältigt beide Wächter und bringt mir ihre Kraftkerne. Sie werden uns alles sagen, was wir wissen müssen.", sourceObjective = "Besorgt den Obsidiankraftkern und den Titankraftkern.", progress = "Habt Ihr die Kerne bei Euch, oder wollt Ihr nur plaudern? Vielleicht sollten wir mit dem ganzen Quatsch hier aufhören und uns lieber ein paar Leckereien und ein feines Gläschen Wein gönnen?", completion = "Diese Kerne sind viel mächtiger als die meisten herkömmlichen Kerne, die wir benutzen, um unsere Beschützer mit Energie zu versorgen. Und diese Geräte sind uralt!\n\nVielen Dank. Sie werden sich sicher als besonders wertvoll für unsere Gesellschaft herausstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27683] = { id = 27683, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Wälder", description = "Letztens konnte ich ein seltsames Treiben in der Stadt beobachten. Es handelte sich um einen Pferdewagen voller Kisten und Truhen, mit einer Worgen auf dem Kutschbock, einem Blutelfen an ihrer Seite und einem Zwergenpaladin, der hinter dem Wagen her lief und die kreativsten Obszönitäten rief, die ich seit Langem gehört habe.\n\nSie schienen auf dem Weg in die Östlichen Pestländer zu sein, allerdings dürften sie bis jetzt kaum weiter als bis zum Fluss Thondroril gekommen sein. Ich frage mich, was sie vorhaben.", sourceObjective = "Sucht nach einer Worgen am Fluss Thondroril in den Östlichen Pestländern.", completion = "Ja?", sourceObjectiveStatus = "unverified-source-field" }
quests[27684] = { id = 27684, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besucher", description = "Meine Quellen an der Stätte der Heiler haben mir verraten, dass wir bald einige Besucher erwarten dürfen. Eine Gruppe Paladine - die bizarrerweise von einer Worgenhändlerin angeführt wird - müsste bald hier eintreffen. Ich freue mich, sie kennenzulernen. Vor allem einen.\n\nWärt Ihr so nett, kurz nach ihnen zu sehen? Ich bin mir zwar nicht sicher, aber wenn Ihr dort eintrefft, sollten sie gerade den Fluss Thondroril weit im Westen überqueren.", sourceObjective = "Sucht nach einer Worgen am Fluss Thondroril in den Östlichen Pestländern.", completion = "Ja?", sourceObjectiveStatus = "unverified-source-field" }
quests[27685] = { id = 27685, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine gute Tat bleibt unvollständig", description = "'n Tag, <Kumpel/Mädel>.\n\nIch bin Rendel.\n\nSieht aus, als wär'n die gute alte Moanah und ich gerade rechtzeitig hier eingetroffen, was?\n\nErunak hat nicht gescherzt, als er sagte, es ginge um Leben oder Tod!\n\nDa wir uns so beeilt ha'm, hierher zu kommen, ha'm wir ein Stück im Osten ein paar unerledigte Aufgaben zurückgelassen.\n\nDa war eine kleine Lady, die nur knapp dem Tode entronnen is'. Wir hatten keine andere Wahl, als sie bei einem kleinen Luftstrom zurückzulassen, nachdem wir sie gerettet ha'm.\n\nWarum geht Ihr nicht dorthin und helft ihr, solange die Zeit es zulässt?", sourceObjective = "Sprecht mit Adarrah im Tang'tharwald.", completion = "Oh, endlich!\n\nIch weiß nicht, wie lange ich noch durchhalte!", sourceObjectiveStatus = "unverified-source-field" }
quests[27686] = { id = 27686, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefälschte Dokumente", description = "Findet einen Bewohner in Orgrimmar, der Eure gefälschten Dokumente annimmt.", progress = "Habt Ihr etwas für mich?", completion = "<Ihr überreicht die gefälschten Dokumente und wechselt dabei nur wenige Worte. Euer meisterhaftes Können spricht für sich selbst.>" }
quests[27687] = { id = 27687, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ganz ohne Zähneknirschen", description = "Was für eine Leistung, einen solch mächtigen Meerriesen zu erlegen!\n\nDie neuen Bewohner des Schmugglerschmisses werden sich bestimmt sehr viel sicherer fühlen, wenn dieses Monster nicht mehr vor ihrer Zuflucht herumlungert.", sourceObjective = "Bringt Knirschers Kopf zu Samir im Schmugglerschmiss.", progress = "Ihr habt diesen Meeresriesen erlegt, {class}?", completion = "Es ist nicht viel, aber es ist alles, was ich hier unten habe.\n\nIch gebe es Euch von Herzen gerne, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27688] = { id = 27688, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lenkt sie für mich ab", description = "Es gibt drei Anwärter auf die Aszendenz, die wir beseitigen müssen: Freifrau Alys Finnsson, Meister Klem und Mia die Rose.\n\nIch möchte, dass Ihr als Ablenkung dient. Wenn der rechte Moment gekommen ist, werde ich hinzukommen und sie von hinten erledigen.\n\nEgal was Ihr tut, Ihr dürft sie auf keinen Fall unterschätzen, {name}. Jeder von ihnen hat sich seine Position durch Skrupellosigkeit erkämpft, und sie sind gut in dem, was sie tun.", sourceObjective = "Tötet Freifrau Alys Finnsson, Meister Klem und Mia die Rose.", completion = "Damit hätten wir einen Großteil ihrer Anführer außerhalb der Bastion erledigt.\n\nWir sind ein gutes Team, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27689] = { id = 27689, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lenkt sie für mich ab", description = "Es gibt drei Anwärter auf die Aszendenz, die wir beseitigen müssen: Freifrau Alys Finnsson, Meister Klem und Mia die Rose.\n\nIch möchte, dass Ihr als Ablenkung dient. Wenn der rechte Moment gekommen ist, werde ich hinzukommen und sie von hinten erledigen.\n\nEgal was Ihr tut, Ihr dürft sie auf keinen Fall unterschätzen, {name}. Jeder dieser Wahnsinnigen hat sich seine Position durch Skrupellosigkeit erkämpft, und sie sind gut in dem, was sie tun.", sourceObjective = "Tötet Freifrau Alys Finnsson, Meister Klem und Mia die Rose.", completion = "Damit hätten wir einen Großteil ihrer Anführer außerhalb der Bastion des Zwielichts erledigt. Keine schlechte Arbeit, {name}. Ganz und gar nicht schlecht.", sourceObjectiveStatus = "unverified-source-field" }
quests[27690] = { id = 27690, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Narkrall, der Drachenzähmer", description = "{name}, die Feste in der Blutschlucht bildet das Herz des Drachenmalreiches im Schattenhochland. Sie befindet sich direkt den Fluss entlang. Narkrall Harkenklaue nutzt seine beträchtliche Macht, um dort einen Drachenreitergeschwader zu versammeln.\n\nDamit das Drachenmal Erfolg hat, muss die Blutschlucht Erfolg haben. Geht zu Narkrall und stellt sicher, dass dies der Fall ist.", sourceObjective = "Meldet Euch bei Narkrall Harkenklaue in der Blutschlucht im Schattenhochland.", completion = "<Narkrall mustert Euch.>\n\nNoch so ein weinerlicher Welpe der Horde? Zaela raubt uns unsere Stärke, indem sie unsere Truppen mit dem Blut der Schwachen verwässert. Nun gut, {class}. Beweist Euch und zeigt mir, aus welchem Holz Eure Horde geschnitzt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[27691] = { id = 27691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marschflossenwahnsinn", description = "Ich fürchte, der Rest des Dampfdruckkartells ist tot. Alle jungen in dem Lager im Osten waren verloren, als die Murlocs kamen.\n\nJa, an diesen Ufern sind immer Murlocs... aber nicht so viele. Sie kamen in Scharen nachts aus dem Meer, heulten und schäumten und schwärmten an Land, um anzugreifen!\n\nWir können nicht zulassen, dass sie weiter hier herumrennen, nicht wahr? Würdet Ihr einem alten Goblin seinen Seelenfrieden zurückgeben und einige von ihnen wieder ins Wasser zurücktreiben?", sourceObjective = "Tötet 12 Murlocs der Marschflossen.", completion = "Man muss sich doch fragen, was da draußen ist. Dies ist die Küste des Verbotenen Meers. Dahinter befindet sich nichts... doch dieses ganze Fischgesindel kam direkt dort heraus.\n\nSchlimmer noch, ich sah, wo sie hingingen...", sourceObjectiveStatus = "unverified-source-field" }
quests[27692] = { id = 27692, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prinzessin Theradras", description = "Fürchtet Euch nicht, <junger/junge:r> {race}. Ich bin Zaetar, Sohn des Cenarius, und ich komme, um Euch um Hilfe zu bitten.\n\nVor langer Zeit machte ich den Fehler, mich mit Prinzessin Theradras einzulassen, einem mächtigen Erdelementar, der den Alten Göttern unterstand. Unsere Kinder, die Khans der Zentauren, wandten sich schon bei ihrer Geburt gegen mich und töteten mich ohne Gnade. Nun ist Theradras' Verderbnis weit fortgeschritten und bedroht weit mehr als nur Maraudon.\n\nKommt und tötet sie, und befreit meinen Geist, sodass wir Desolace in einen Ort des blühenden Lebens und der Verheißung verwandeln können, wie Cenarius es gewollt hätte.", sourceObjective = "Tötet Prinzessin Theradras.", completion = "Danke, {name}. Wie Ihr sehen könnt, hat meine bloße Anwesenheit hier üppiges Leben entspringen lassen, trotz der Anwesenheit meines Gefährten. Ungeachtet des Namens werdet Ihr vielleicht eines Tages wieder nach Desolace reisen und eine blühende Oase frei von jeder Sput der Alten Götter vorfinden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27693] = { id = 27693, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Spiel des Wächters", description = "Ihr seht, wie sich die Statue erst in zwei, dann in vier, dann in acht identische Statuen in quadratischer Anordnung teilt.\n\nIhr hört eine Stimme, jedoch nicht mit Euren Ohren, sondern direkt in Eurem Kopf:\n\n\"Ein wahrer Wächter sieht nicht nach AUSSEN, um nach Anzeichen der Gefahr zu suchen.\n\n Ein wahrer Wächter richtet seinen Blick nach INNEN, immer darauf konzentriert, seine Beute zu schützen.\"\n\nVielleicht ist dies eine Art Rätsel?", sourceObjective = "Beendet das Spiel des Wächters, indem Ihr die Bauern des Wächters in eine nach innen gerichtete Position teleportiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[27694] = { id = 27694, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tränenteich", description = "Die Trolle, die in diesem Tempel lauern, haben meiner Art Schreckliches angetan, {name}. Wir wurden hierher geschickt, um diesen Ort zu schützen, und stattdessen wurden wir benutzt, um die fürchterlichen Mächte darin zu entfesseln.\n\nIch flehe Euch an, um die Hilfe, die nur ein Sterblicher leisten kann. Ihr könnt meine Hand im Tempel sein; würde ich allein eintreten, könnte auch ich gegen meine Brüder gewendet werden.\n\nWir werden einen Pakt schließen. Wenn Ihr mir helfen wollt, sammelt Artefakte der Atal'ai aus den Wassern um den Tempel herum, und bringt sie zu mir.", sourceObjective = "Sammelt 5 Artefakte der Atal'ai aus dem Tränenteich um den Tempel von Atal'Hakkar herum.", progress = "Diese Artefakte zu sammeln wird Eure Vertrauenswürdigkeit unter Beweis stellen. Sobald das geschehen ist, werde ich das Ritual durchführen.", completion = "Die Essenz des grünen Drachenschwarms entströmt diesen Artefakten; die Überbleibsel meiner verderbten Verwandten. Indem ich sie reinige, schließe ich einen Bund zwischen uns.\n\nTretet hervor, {name}, und empfangt den Schwurstein von Yseras Drachenschwarm.", sourceObjectiveStatus = "unverified-source-field" }
quests[27695] = { id = 27695, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Elementiumaxt", description = "Diese Feiglinge des Schattenhammers haben so viele rote Drachen gefangen und getötet, aber einer ist immer noch am Leben. Erinnert Ihr Euch an Lirastrasza? Sie ist in der Nähe angekettet, und wir werden sie befreien.\n\nAber zuerst brauchen wir etwas, das scharf genug ist, um ihre Ketten zu zerschlagen.\n\nAm Altar des Aufstiegs im Süden wacht ein alter Ettin namens Blindauge der Wächter.\n\nIn seinem Besitz befindet sich eine fein gearbeitete Axt aus Elementium. Ich frage mich, ob das wohl Cho'galls \"ultimative\" Waffe ist.", sourceObjective = "Beschafft Euch die Elementiumaxt.", progress = "Habt Ihr die Axt? Sie werden Lirastrasza bald töten.", completion = "Das Ding sieht verdammt scharf aus. Zumindest scharf genug, um seinen Zweck zu erfüllen.\n\nIch für meinen Teil schätze, dass dies nicht die Bewaffnung ist, hinter der Cho'gall her ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[27696] = { id = 27696, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Elementiumaxt", description = "Diese Feiglinge des Schattenhammers haben so viele rote Drachen gefangen und getötet, aber einer ist immer noch am Leben. Erinnert Ihr Euch an Lirastrasza? Sie ist in der Nähe angekettet, und wir werden sie befreien.\n\nAber zuerst brauchen wir etwas, das scharf genug ist, um ihre Ketten zu zerschlagen.\n\nAm Altar des Aufstiegs im Süden wacht ein alter Ettin namens Blindauge der Wächter.\n\nIn seinem Besitz befindet sich eine fein gearbeitete Axt aus Elementium. Ich frage mich, ob das wohl Cho'galls \"ultimative\" Waffe ist.", sourceObjective = "Beschafft Euch die Elementiumaxt.", progress = "Habt Ihr die Axt?", completion = "Das ist eine verdammt scharfe Axt. Sie wird ihren Zweck erfüllen, aber ich für meinen Teil schätze, dass dies nicht die Bewaffnung ist, hinter der Cho'gall her ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[27697] = { id = 27697, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbnis in Maraudon", description = "{name}, ich benötige sofort Eure Unterstützung! Ich bin Zaetar, Sohn des Cenarius, und ich sitze hier aufgrund einer Reihe unglücklicher Ereignisse fest! Bevor man überhaupt daran denken kann, mich zu retten, müsst Ihr mir helfen, die Verderbnis, die von Maraudon Besitz ergriffen hat, auszumerzen.\n\nLord Schlangenzunge ist der Satyr, der über die purpurnen Kristallhöhlen herrscht. Er ist ein heimtückisches Mitglied der brennenden Legion und wird durch seine Anwesenheit Chaos und Tod bringen. Er darf nicht länger leben!", sourceObjective = "Tötet Lord Schlangenzunge.", completion = "Hervorragende Arbeit, {name}! Schlangenzunges Tod ist ein wichtiger Schritt auf dem Weg zu meiner Rettung und letzten Endes auch zur Rettung dieses Landes vor der Verderbnis. Nehmt dies als Zeichen meiner Dankbarkeit und als Anregung, Eure Arbeit hier fortzusetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27698] = { id = 27698, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diener von Theradras", description = "Prinzessin Theradras, meine ehemalige Gefährtin, hat ihre enormen Mächte benutzt, um die Natur von Maraudon selbst zu verderben. In diesem Moment wüten ihre Geschopfe dort, und ich fürchte, dass sie bald in die Welt entkommen werden, um dort die Saat von Tod und Verwüstung zu streuen.\n\n{name}, geht und tötet Noxxion und Schlingwurzler. Sie sind ihre zwei mächtigsten Diener, und ihre Tode würden der kaltherzigen Prinzessin verdientermaßen selbst Leid und Trauer bringen. Vielleicht könnt Ihr mir dann helfen, meinen Geist aus ihrer Umklammerung zu befreien.", sourceObjective = "Tötet Noxxion und Schlingwurzler.", completion = "Ohne ihre mächtigen Diener ist Prinzessin Theradras wesentlich verwundbarer. Macht ihren Untschlupf ausfindig, {name}... es ist an der Zeit, dass wir zuschlagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27699] = { id = 27699, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unhaimlich", description = "Das ist ein ganz schön starker Hai!\n\nIhr beschließt, dass es im besten Sinne aller wäre, wenn Ihr versucht, Budd abzulenken, damit er seine Aufmerksamkeit nie wieder auf Nager und dieses Skelettriff richtet.\n\nVielleicht erweisen die Zähne dieser Bestie sich als fesselnd genug...", sourceObjective = "Sammelt 5 von Nagers Zähnen im Skelettriff.", progress = "Was habt Ihr da, Kumpel?", completion = "Was?!\n\nNager ist nicht tot?!\n\nDas macht meine Hoffnung auf das schnelle Gold wohl genauso schnell wieder zunichte…\n\nDiese riesigen Haizähne sind zwar ganz nett, aber wir dürfen nicht aufhören, bis der Glitzerkram uns gehört!", sourceObjectiveStatus = "unverified-source-field" }
quests[27700] = { id = 27700, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der entfesselte Drache", description = "Lirastrasza ist der letzte und größte der roten Drachen, die der Schattenhammer gefangen hat. Sie stehen kurz davor, sie zu töten, {class}.\n\nIhr müsst die Elementiumaxt nehmen und sie von ihren Ketten befreien.", sourceObjective = "Benutzt die Elementiumaxt, um die gefangene Lirastrasza aus ihren Ketten zu befreien.", completion = "Ist sie nicht wunderschön?\n\nIch bin gespannt, was sie jetzt mit ihrer Freiheit anstellt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27701] = { id = 27701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der entfesselte Drache", description = "Lirastrasza ist der letzte und größte der roten Drachen, die der Schattenhammer gefangen hat. Sie stehen kurz davor, sie zu töten, {class}.\n\nIhr müsst die Elementiumaxt nehmen und sie von ihren Ketten befreien, bevor sie es tun.", sourceObjective = "Benutzt die Elementiumaxt, um die gefangene Lirastrasza aus ihren Ketten zu befreien.", completion = "Ist sie nicht wunderschön? So anmutig.\n\nIch hoffe, sie kann ihren Rachedurst stillen. Und noch viel mehr…", sourceObjectiveStatus = "unverified-source-field" }
quests[27702] = { id = 27702, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnadenstoß", description = "Schaut Euch das an! Lirastrasza vernichtet sie!\n\nIhr müsst jedoch noch ein paar der Drachen, die sie aus der Luft geholt hat, den Rest geben, {name}. Wir wollen schließlich nicht, dass die Heiler des Schattenhammers sie wieder flugtauglich machen.\n\nEs wird Zeit für einen Gnadenstoß.", sourceObjective = "Versetzt 5 Himmelsschrecken der Zwielichtdrachen einen Gnadenstoß.", completion = "Unsere Bemühungen zur Verbesserung der Beziehungen zum roten Drachenschwarm haben sich wirklich ausgezahlt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27703] = { id = 27703, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnadenstoß", description = "Schaut Euch das an! Lirastrasza vernichtet sie!\n\nIhr müsst jedoch noch ein paar der Drachen, die sie aus der Luft geholt hat, den Rest geben, {name}. Wir wollen schließlich nicht, dass diese stinkenden Heiler des Schattenhammers sie wieder flugtauglich machen.\n\nEs wird Zeit für einen Gnadenstoß.", sourceObjective = "Versetzt 5 Himmelsschrecken der Zwielichtdrachen einen Gnadenstoß.", completion = "Welch Glück, dass Ihr und Kriegsfürst Krogg Euch mit den roten Drachen angefreundet habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27704] = { id = 27704, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legenden des Versunkenen Tempels", description = "Ihr müsst zuerst den Tempel betreten, {name}. Ich kann Euch folgen, wenn der Weg sicher ist, aber ich wage es nicht, blindlings hineinzugehen. Würde ich mich gegen mein Volk wenden, wäre ich ein gefährlicher Feind.\n\nIhr könnt die Treppen hinter mir hinuntersteigen. Dann schwimmt durch die überfluteten Tiefen der zerstörten Hallen. Danach folgt dem Tunnel zur Rechten, um zur Halle der Masken zu gelangen.\n\nNehmt Euch vor den Tempelwachen in Acht. Sobald Ihr die Halle der Masken gefunden habt, werde ich mich durch den Schwurstein mit Euch in Verbindung setzen.", sourceObjective = "Begebt Euch durch die Vorräume des Tempels zur Halle der Masken.", sourceObjectiveStatus = "unverified-source-field" }
quests[27705] = { id = 27705, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erster Schritt: Die Priesterin", description = "Meine Brüder werden hier abgeschlachtet. Genau, wie ich mir gedacht hatte.\n\nIch muss Euch nochmals um Hilfe bitten, bevor ich eintrete, {name}. In einem Gang außerhalb dieses Raums führt der Weg nach rechts und links. Rechts geht es zur Kammer des Bluts. Dort führen die Atal'ai ihre finsteren Rituale durch.\n\nSie bereiten sich schon jahrelang auf einen Gegner wie mich vor, aber nicht auf einen wie Euch. Betretet die Kammer des Bluts und tötet Priesterin Udum'bra. Sie ist eine von drei bösartigen Präsenzen hier, die entfernt werden müssen, bevor ich eintreten kann.", sourceObjective = "Besiegt Priesterin Udum'bra in der Kammer des Bluts.", sourceObjectiveStatus = "unverified-source-field" }
quests[27706] = { id = 27706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Zepter von Orsis", description = "Das Schloss der Truhe öffnet sich mit lautem Klicken, als Ihr die beiden Steine in die Plakette einsetzt.\n\nNehmt das Zepter an Euch und bringt es zu General Ammantep.", sourceObjective = "Holt das Zepter von Orsis aus dem heiligen Gefäß.", progress = "Ihr seid zurück, {name}.", completion = "Also... das ist es, was Al'Akir die ganze Zeit wollte.", sourceObjectiveStatus = "unverified-source-field" }
quests[27707] = { id = 27707, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Gefängnis von Neferset", description = "Hieroglyphen, die einen angeketteten Tol'vir zeigen, befinden sich in der südöstlichen Ecke der Karte.\n\nVielleicht wurde Tahet dorthin gebracht, als man ihn gefangen nahm.", sourceObjective = "Geht in das Gefangenenlager von Neferset und findet etwas über den Aufenhaltsort Tahets heraus.", sourceObjectiveStatus = "unverified-source-field" }
quests[27708] = { id = 27708, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zeit des Aufsehers", description = "<Erunaks Bildnis formt sich in Eurem Geist.>\n\nIhr habt gute Arbeit geleistet, {name}, aber es bleibt noch eines zu tun.\n\nBevor wir von hier fortgehen, sollten wir ein wenig Unordnung stiften.\n\nFindet denjenigen, der diese Naga anführt und lasst ihn für seine Untaten bezahlen.", sourceObjective = "Erunak Steinsprecher möchte, dass Ihr Aufseher Azjakir in der Umklammerung tötet.", completion = "Es ist gut, dass ihre Pläne durchkreuzt wurden.\n\nBald muss ich weiterziehen…", sourceObjectiveStatus = "unverified-source-field" }
quests[27709] = { id = 27709, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schildwachenspiel", description = "Als Ihr die Statue an ihren Platz setzt, erscheinen weitere Steinstatuen im Raum. In einem kleinen Gehäuse am anderen Ende des Raums erscheint auch eine rubinrote Statue. Ihr hört eine Stimme:\n\n \"Die Schildwache sieht.\n\n Die Schildwache beschützt.\n\n Der Blick der Schildwache versagt nie.\"\n\nDie rote Statue auf der anderen Seite des Raums erscheint Euch wichtig. Vielleicht solltet Ihr versuchen, die beiden roten Statuen miteinander zu verbinden?", sourceObjective = "Beendet das Spiel der Schildwache, indem Ihr die beiden roten Statuen miteinander verbindet.", sourceObjectiveStatus = "unverified-source-field" }
quests[27711] = { id = 27711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück in die Elementiumtiefen", description = "Der Initiand der Erdenruferin, Goldmine, braucht Euch.\n\nIch glaube, Ihr sollt ihn in dieser Mine unterstützen, was auch immer sich dort befinden mag.", sourceObjective = "Sprecht mit Initiand Goldmine vor den Elementiumtiefen im Schattenhochland.", completion = "{name}, bin ich froh, dass Ihr zurück seid! Ich habe eine spaßige Aufgabe für uns beide!", sourceObjectiveStatus = "unverified-source-field" }
quests[27712] = { id = 27712, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück in die Elementiumtiefen", description = "Die Erdenruferin hat einen Goblininitianden? Und er heißt Goldmine? Jedenfalls braucht er Euch.\n\nIch glaube, Ihr sollt für ihn die Drecksarbeit in dieser Mine erledigen, was auch immer sich dort befinden mag.", sourceObjective = "Sprecht mit Initiand Goldmine vor den Elementiumtiefen im Schattenhochland.", completion = "{name}, bin ich froh, dass Ihr zurück seid! Ich habe eine spaßige Aufgabe für uns beide!", sourceObjectiveStatus = "unverified-source-field" }
quests[27713] = { id = 27713, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Tag, an dem Todesschwinge kam", description = "Todesschwinge hat ein ganz schönes Chaos angerichtet, als er hier durchgekommen ist. Ohne mich wäre er wahrscheinlich noch immer hier und würde all die Einwohner des Ödlands umbringen.\n\nWas, Ihr glaubt mir nicht? Gut, lasst mich Euch die ganze Geschichte erzählen.", sourceObjective = "Hört Euch Theldurins Geschichte an.", completion = "Eine ganz schöne Geschichte, nicht wahr? Jetzt wisst Ihr, warum Todesschwinge seitdem nicht mehr hierher zurückgekehrt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[27714] = { id = 27714, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Tag, an dem Todesschwinge kam: Die wahre Geschichte", description = "Theldurins Geschichte war nicht nur falsch, sie war langweilig, einfallslos und langatmig.\n\nIch sage Euch, was an dem Tag wirklich geschehen ist.", sourceObjective = "Hört Euch Lucien Knobelzangs Version der Geschichte an.", progress = "Ich bin noch nicht mit meiner Geschichte fertig. Setzt Euch wieder hin.", completion = "Ende! Und die Moral von der Geschicht' gibt es nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[27715] = { id = 27715, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Tag, an dem Todesschwinge kam: Was wirklich geschah", description = "Diese Beiden haben keine Ahnung, wie man eine Geschichte erzählt. Theldurins Geschichte war zu kurz und Luciens Geschichte war zu lang, wenn Ihr versteht, was ich meine.\n\nAuch kamen in keiner ihrer Geschichten Action und begeisterte Fans von mir vor.\n\nMacht es Euch bequem, {name}, ich erzähle Euch, was damals wirklich geschehen ist.", sourceObjective = "Hört Euch Marteks Version der Geschichte an.", completion = "Ich fasse es nicht, dass mich diese Typen einfach so unterbrochen haben. Und dabei lief meine Geschichte gerade so gut...\n\nWie dem auch sei, danke, dass Ihr so lange zugehört habt. Es ist schön, jemand Neues zum Geschichten erzählen zu haben. Ich bin mir sicher, dass Lucien und Theldurin das genauso sehen.\n\nHabt Ihr eine Geschichte, die Ihr mit uns teilen wollt?", sourceObjectiveStatus = "unverified-source-field" }
quests[27716] = { id = 27716, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Stück Vergangenheit", description = "<Eine uralte, leicht zerbrochene Steintafel mit einer Unmenge von Inschriften auf allen Seiten. Ihr könnt die Sprache nicht lesen, aber die schiere Menge an Text und der fast ornamental wirkende Charakter des Steins lassen drauf schließen, dass er von großem Wert sein muss.>\n\n<Levia Traumwächter bei den Überlebenden von Nespirah hat genau nach so etwas gesucht.>", sourceObjective = "Bringt die uralte Elfengravur zu Levia Traumwächter. Ihr solltet sie bei den Überlebenden von Nespirah der Allianz finden.", progress = "Ha! Habt Ihr gesehen, wie der Admiral mir böse Blicke zuwirft und mich herablassend behandelt? Ich habe offen gestanden alle Hoffnung verloren, dass er versteht, welch gute Gelegenheit die Ruinen uns bieten, diesem ganzen Schlamassel etwas Positives abzugewinnen.\n\nIch habe gehofft, dass Ihr wieder auftauchen würdet. Ihr scheint der Einzige zu sein, dem ich vertrauen kann. Wartet... was habt Ihr da?", completion = "Ausgezeichnet! Ich werde ein bisschen brauchen, bis ich es übersetzt haben, aber genau das hatte ich zu finden gehofft.\n\nKeine Ahnung, ob wir je von hier entkommen. Aber wenn es hart auf hart kommt, finde ich schon einen Weg, dies hier an die Oberfläche treiben zu lassen, damit es eines Tages gefunden wird.\n\nNochmals danke, {name}. Hier... Vielleicht habe ich etwas, das Ihr gebrauchen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27717] = { id = 27717, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Stück Vergangenheit", description = "<Eine uralte, leicht zerbrochene Steintafel mit einer Unmenge von Inschriften auf allen Seiten. Ihr könnt die Sprache nicht lesen, aber die schiere Menge an Text und der fast ornamental wirkende Charakter des Steins lassen drauf schließen, dass er von großem Wert sein muss.>\n\n<Elendri Goldbraue bei den Überlebenden von Nespirah hat genau nach so etwas gesucht.>", sourceObjective = "Bringt die uralte Elfengravur zu Elendri Goldbraue. Ihr solltet sie bei den Überlebenden von Nespirah der Horde finden.", progress = "Ha! Habt Ihr gesehen, wie der Hauptmann mir böse Blicke zuwirft und mich herablassend behandelt? Ich habe offen gestanden alle Hoffnung verloren, dass er versteht, welch gute Gelegenheit die Ruinen uns bieten, diesem ganzen Schlamassel etwas Positives abzugewinnen.\n\nIch habe gehofft, dass Ihr wieder auftauchen würdet. Ihr scheint der Einzige zu sein, dem ich vertrauen kann. Wartet... was habt Ihr da?", completion = "Ausgezeichnet! Mit den Werkzeugen, die ich Euch gegeben habe, hätte ich nicht mehr erwarten können.\n\nIch sollte die Lücken füllen und den Text schnell in eine schriftliche Form bringen können. Keine Ahnung, ob wir je von hier entkommen. Aber wenn es hart auf hart kommt, finde ich schon einen Weg, dies hier an die Oberfläche treiben zu lassen, damit es eines Tages gefunden wird.\n\nNochmals danke, {name}. Ihr seid nicht übel.", sourceObjectiveStatus = "unverified-source-field" }
quests[27718] = { id = 27718, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Vashj'ir!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Kommandant Thorak in der Messerbucht in Durotar zu melden.\n\nWir brauchen Eure Hilfe im Kampf gegen unseren verhassten Feind, die Allianz, mehr denn je!\n\nReist nach Süden durch das Haupttor von Orgrimmar nach Durotar. Folgt von dort aus dem Pfad nach Osten zur Küste. Dort findet ihr die Messerbucht. Thorak hält sich an seinem Posten in der Nähe der Docks auf.\n\nVorwärts, <Bruder/Schwester>! Das Schicksal ruft!", sourceObjective = "Meldet Euch bei Kommandant Thorak in der Messerbucht in Durotar.", completion = "Lok'tar, Bruder! Ihr kommt genau rechtzeitig.", sourceObjectiveStatus = "unverified-source-field" }
quests[27719] = { id = 27719, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wasser des Lebens", description = "Nehmt mein Wasser des Lebens und gebt es auf den Leichnam des ertrunkenen Zwergs.\n\nAls er lebte, bearbeitete er Metall. Und obwohl sein Leichnam jetzt meinen Loch nährt, kann er Euch dank des Wassers sagen, was Ihr wissen wollt.\n\nNehmt dann Eure Informationen und verschwindet von meinem Besitz.", sourceObjective = "Benutzt das Wasser des Lebens, um dem Leichnam von Schmiedemeister Finlay Informationen zu entlocken.", completion = "Der Schattenhammer? Und diese Informationen habt Ihr also von einem ertrunkenen Zwerg der Wildhämmer?\n\nIhr macht Scherze, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[27720] = { id = 27720, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die wilde Fahrt des Herrn Goldmine", description = "In Ordnung, {name}. Wir müssen zum Erdportal an der anderen Seite der Höhle gelangen.\n\nIch habe ein Gefährt für uns \"gesichert\". Warum laufen, wenn man stilvoll fahren kann? Ich hoffe, Ihr habt nichts gegen Minenwagen.\n\nGebt mir Bescheid, wenn Ihr bereit seid.", sourceObjective = "Fahrt zusammen mit Initiand Goldmine im Minenwagen bis zum Ende der Strecke.", completion = "Oh nein! Meine Waffen und Totems!\n\nSie sind dahin!!!", sourceObjectiveStatus = "unverified-source-field" }
quests[27721] = { id = 27721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Hyjal!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Botschafterin Windweise in Nachthafen auf der Mondlichtung zu melden.\n\nUnsere Brüder im Zirkel des Cenarius haben uns berichtet, dass Todesschwinges Anhänger einen vernichtenden Angriff gegen den Weltenbaum gestartet haben und drohen, ihn zu verbrennen!\n\nSprecht mit Cenarius' Abgesandtem Schwarzhuf, um Zugang zur Mondlichtung zu erlangen. Schwarzhuf hält sich im Taurenviertel im Tal der Weisheit in Orgrimmar auf.\n\nVorwärts, <Bruder/Schwester>! Das Schicksal ruft!", sourceObjective = "Sprecht mit Cenarius' Abgesandtem Schwarzhuf, um auf die Mondlichtung zu reisen.", completion = "Wir wussten, dass die Horde Hilfe schicken würde. Und Ihr kommt keine Sekunde zu früh!", sourceObjectiveStatus = "unverified-source-field" }
quests[27722] = { id = 27722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Tiefenheim!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Scharfseher Krogar am Westlichen Erdschrein in Orgrimmar zu melden.\n\nDer Irdene Ring, der von unserem ehemaligen Kriegshäuptling Thrall angeführt wird, braucht unsere Hilfe! Es wurde uns berichtet, dass die Elementarebene Tiefenheim droht, unsere Welt zu übernehmen!\n\nDer Westliche Erdschrein befindet sich direkt nördlich des Tals der Weisheit.\n\nVorwärts, <Bruder/Schwester>! Das Schicksal ruft!", sourceObjective = "Sprecht mit Scharfseher Krogar am Westlichen Erdschrein in Orgrimmar.", completion = "Unsere Welt ist in Gefahr, {name}! Wir brauchen die Hilfe überragender Helden wie Ihr es seid, um sie zu retten!", sourceObjectiveStatus = "unverified-source-field" }
quests[27724] = { id = 27724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Vashj'ir!", description = "Auf Anweisung seiner königlichen Hoheit König Anduin Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Rekrutierer Burns im Hafen von Sturmwind zu melden.\n\nDie kürzlichen Angriffe der Horde auf unsere Handelsschiffe müssen schnell und gerecht geahndet werden!\n\nDer Hafen von Sturmwind befindet sich im Nordwesten von Sturmwind.\n\nFür den Ruhm und die Ehre der Allianz! Auf in den Kampf, <Bruder/Schwester>!", sourceObjective = "Sprecht mit Rekrutierer Burns im Hafen von Sturmwind in Sturmwind.", completion = "All unsere Kriegsschiffe befinden sich bereits im Kampf gegen die Horde, also werdet Ihr ein Söldnerschiff nehmen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27725] = { id = 27725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagdhütte Quel'Danil", description = "Es mag Euch fern der Heimat erscheinen, {class}, aber ein großer Teil meines Volkes wurde von Botschafter Rualeth hierher geführt. Wir haben uns bei den Hochelfen der Jagdhütte Quel'Danil im Nordwesten niedergelassen, um den Weg des Lichts zu erlernen und die friedliche Schönheit dieses Landes zu genießen.\n\nEin derartiger Frieden könnte sehr kurzlebig sein. Wir haben gesehen, dass die Horde sich weiter nach Westen bewegt. Könntet Ihr nach Quel'Danil reisen und Anachoretin Traska warnen? Ihre Hütte befindet sich etwas nördlich des Hauptgebäudes.", sourceObjective = "Sprecht mit Anachoretin Traska bei der Jagdhütte Quel'Danil.", completion = "Yoro schickt uns eine Warnung vor der Horde? Den Elfen Hochtals graut es schon längere Zeit vor einem Angriff. Um genau zu sein, haben wir...\n\n<Schreie und der Klang berstenden Metalls sind aus dem Süden zu hören.>\n\nBeim Lichte... sie sind hier!", sourceObjectiveStatus = "unverified-source-field" }
quests[27726] = { id = 27726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Hyjal!", description = "Auf Anweisung seiner königlichen Hoheit König Anduin Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Botschafterin Windweise in Nachthafen auf der Mondlichtung zu melden.\n\nUnsere Brüder im Zirkel des Cenarius haben uns berichtet, dass Todesschwinges Anhänger einen vernichtenden Angriff gegen den Weltenbaum gestartet haben und drohen, ihn zu verbrennen!\n\nSprecht mit Cenarius' Abgesandter Jademond in der Burg Sturmwind, um Zugang zur Mondlichtung zu erlangen.\n\nFür den Ruhm und die Ehre der Allianz! Auf in den Kampf, <Bruder/Schwester>!", sourceObjective = "Sprecht mit Cenarius' Abgesandter Jademond, um auf die Mondlichtung zu reisen.", completion = "Wir wussten, dass die Allianz Hilfe schicken würde. Und Ihr kommt keine Sekunde zu früh!", sourceObjectiveStatus = "unverified-source-field" }
quests[27727] = { id = 27727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Tiefenheim!", description = "Auf Anweisung seiner königlichen Hoheit König Anduin Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Naraat dem Erdsprecher am Östlichen Erdschrein in Sturmwind zu melden.\n\nDer Irdene Ring braucht unsere Hilfe! Uns wurde berichtet, dass die Elementarebene Tiefenheim droht, unsere Welt zu übernehmen und alles Leben in Azeroth zu zerstören!\n\nDer Östliche Erdschrein befindet sich direkt nordwestlich der Burg Sturmwind.\n\nFür den Ruhm und die Ehre der Allianz! Auf in den Kampf, <Bruder/Schwester>!", sourceObjective = "Sprecht mit Naraat dem Erdsprecher am Östlichen Erdschrein in Sturmwind.", completion = "Unsere Welt ist in Gefahr, {name}! Wir brauchen die Hilfe überragender Helden wie Ihr es seid, um sie zu retten!", sourceObjectiveStatus = "unverified-source-field" }
quests[27729] = { id = 27729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch einmaal mit Gefühl", description = "Aale gehören zu den widerlichsten Wesen in ganz Azeroth.\n\nSicher, da gibt es diejenigen, denen sie angeblich egal sind. Und dann noch diejenigen, die sogar behaupten, sie zu mögen.\n\nSie lügen.\n\nIn Wahrheit mag nämlich niemand Aale. Nicht einmal Aale mögen Aale.\n\nAzeroth wäre ein besserer Ort, wenn niemand sich ausmalen müsste, wie ein glitschiger Aal sich aus den trüben Tiefen hervor windet und zubeißt.\n\nMitten ins Gesicht.", sourceObjective = "Tötet 8 beliebige Aale im Tang'tharwald.", sourceObjectiveStatus = "unverified-source-field" }
quests[27733] = { id = 27733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das gute alte Hütchenspiel", description = "Seht mal, ich würde ja liebend gern den Befehl geben und meine Männer diese Rebellen in Stücke sprengen lassen, aber das kann ich nicht, weil das gesamte Verlies unter Befehl von Aufseher Thelwasser steht, und er will sie im Moment nur einsperren.\n\nStatt sich Befehlen zu widersetzen, werden wir das Ganze auf andere Art lösen! Wir haben uns mit Mortimer Moloch angefreundet, der rein zufällig der Zwillingsbruder des ruchlosen Rebellenanführers Randolph Moloch ist. Tötet Randolph, und wir tauschen sie aus, sodass Mortimer die Rebellion friedlich beenden kann!", sourceObjective = "Tötet Randolph Moloch.", completion = "Ja, Mortimer hat gerade seinen eigenen Tod vorgetäuscht. Er wird vermutlich den Namen seines Bruders annehmen und seine \"epischen Pläne\" weiterführen. Damit müssen wir fertigwerden, wenn es so weit ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[27737] = { id = 27737, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst das Feuer Euch erretten!", description = "Ich kenne mich gut mit Erster Hilfe und anderen Formen des Heilens aus, und dank meines Lichtbrunnens ist es mir gelungen, vielen unserer Männer ihre Gesundheit zurückzugeben. Doch es ist so kalt und feucht hier unten, dass ich sie verliere, obwohl ich ihre Wunden geheilt habe!\n\nDie Beben haben die Elemente, die in dem Gefängnis hausen, verärgert... als sie aus der Erde emporbrachen, töteten sie die Hälfte der Gefangenen. Wenn Ihr ihren Anführer, Fürst Gluthitze, töten und mir seinen Kern bringen würdet, könnte ich meine Männer aufwärmen!", sourceObjective = "Beschafft Fürst Gluthitzes Feuerkern.", progress = "Habt Ihr den Kern? Unsere Männer sterben hier unten!", completion = "Wunderbar! Dank des Feuers werden unsere Männer diese Prüfung überstehen!\n\nVielen Dank, Held.", sourceObjectiveStatus = "unverified-source-field" }
quests[27738] = { id = 27738, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schuppengrube", description = "Ein Punkt am südlichen Rand der Karte wurde mit Hieroglyphen von gegeneinander kämpfenden Krokodilen markiert.\n\nDas muss der Ort sein, an den Caimas Tahet gebracht hat.\n\nBegebt Euch zur Schuppengrube und findet einen Weg, um den Sohn des Wesirs zu retten.", sourceObjective = "Rettet Tahet aus der Schuppengrube in Uldum.", completion = "Ich danke Euch für das, was Ihr getan habt, {name}. Ihr könnt Euch meiner Stimme sicher sein, wenn der Hohe Rat zusammentritt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27739] = { id = 27739, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der König der Gnolle", description = "{name}, ich muss das Unmögliche von Euch verlangen.\n\nIch habe meine Augenklappe, weil er es wollte. Unzählige Unschuldige sind seinem Zorn zum Opfer gefallen. Nur durch ein Wunder konnten wir ihn hier einsperren.\n\nUnd das war ein schwerer Fehler. Wir haben so lange ausgehalten, wie wir konnten, doch dann kamen sie. Aus den Schatten und der Dunkelheit rissen Gnolle, die Hogger dienten, meine besten Männer in Stücke.\n\nIhr müsst den Gnollkönig besiegen, sonst wird er einen weiteren Angriff befehlen und uns alle in kaltem, blutdürstigen Zorn töten.", sourceObjective = "Besiegt Hogger.", progress = "Habt Ihr Hogger besiegt?", completion = "Eine Tat wie die Eurige habe ich in meiner langen Karriere noch nicht gesehen. Hoggers Tod wird noch auf Jahre hinweg einen Schatten auf die Flusspfotengnolle werfen und ihren Angriffen auf unser Volk hoffentlich ein Ende bereiten.\n\nHeld aller Helden, bitte nehmt dies als Zeichen meiner ewigen Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[27740] = { id = 27740, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baba Torfbräu", description = "Hey, während Ihr draußen wart, hat der Baron vorbeigeschaut! Hat mich so lange getreten, bis Geld herausgefallen ist!\n\nDas macht er aber immer so. Diesmal hat er mir aber noch aufgetragen, Euch etwas mitzuteilen! Er will, dass Ihr nach Süden geht und unserer Kräuterkundigen Baba Torfbräu helft.\n\nSie befindet sich auf der anderen Seite des Gewässers! Aber redet einfach mit meinem Mädchen Daisy draußen und sie wird Euch auf Art des verrückten Larrys dorthin bringen!", sourceObjective = "Redet mit dem verrückten Daisylein, um einen Kanonenkugelritt zu Baba Torfbräu zu unternehmen.", completion = "Ah, es ist so schön, Hilfe frei Haus zu bekommen.\n\nModerne Annehmlichkeiten... davon kann ich nie genug bekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27741] = { id = 27741, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eure Papiere bitte", description = "Da Ihr schon hervorragende Leistungen beim Umgang mit dem Schattenhammer vorzuweisen habt, hat Hauptmann Anton Euch für einen heiklen Auftrag vorgeschlagen.\n\nMeine Leute haben kürzlich eine Gruppe Kultisten dabei erwischt, wie sie in die Stadt schleichen wollten. Der Zustrom aus dem Umland in die Stadt ist zum Erliegen gekommen. Der König hat befohlen, dass alle Reisenden durchsucht werden müssen, bevor sie Sturmwind betreten dürfen. Nehmt diese Abschrift seiner Proklamation, lest sie den vor der Stadt versammelten Mengen vor und helft anschließend den Wachen, diejenigen zu durchsuchen, die Einlass in die Stadt wünschen.", sourceObjective = "Begebt Euch zum Haupttor von Sturmwind, verlest König Wrynns Proklamation und durchsucht 5 Bürger Stumwinds. Behaltet jeden verdächtigen Gegenstand ein.", sourceObjectiveStatus = "unverified-source-field" }
quests[27742] = { id = 27742, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein kleiner Nebenerwerb", description = "Wisst Ihr, es ist unsere moralische Verpflichtung, all das Elementium vor den Schieferspinnen zu retten. Diese widerlichen Biester fressen das Zeug!\n\nWas für eine Verschwendung!\n\nAlso, was meint Ihr? Teilen wir 90:10 für mich?", sourceObjective = "Sammelt 6 Elementiumsplitter.", progress = "Was meint Ihr, wie viel könnt Ihr tragen?", completion = "<Goldmine wirft einen schlitzohrigen Blick auf den Haufen mit Elementiumsplittern.>\n\nHmm, ich glaube nicht, dass sich das Zeug gut verkaufen lässt. Am besten gebe ich Euch jetzt gleich Euren Anteil, damit Ihr Euch nicht übers Ohr gehauen fühlt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27743] = { id = 27743, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo wir schon da sind", description = "Wenn Ihr schon hier seid, könnt Ihr Euch auch gleich um die Eindringlinge des Schattenhammers kümmern. Schließlich gehört dieser Ort uns!\n\nIch würde Euch ja helfen, aber da meine Totems und Waffen kaputt sind, bin ich ziemlich aufgeschmissen.", sourceObjective = "Tötet 12 Kultisten des Schattenhammers, entweder Tiefenaufseher oder Zwielichtminenarbeiter, in den Elementiumtiefen.", completion = "Sie haben es nicht besser verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[27744] = { id = 27744, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runenruinierung", description = "Als Ihr die Zwielichtrune der Erde untersucht, spürt Ihr, wie ihre Macht sich weiter in die Elementiumtiefen hinein erstreckt.\n\nWahrscheinlich ist sie mit den anderen Runen verbunden. Initiand Goldmine ist der Meinung, dass Ihr sie alle zerstören solltet.", sourceObjective = "Zerstört die Zwielichtrune der Erde, die Zwielichtrune des Wassers, die Zwielichtrune der Luft und die Zwielichtrune des Feuers.", completion = "Das wird ihnen zeigen, was passiert, wenn man in unser Gebiet eindringt!\n\nWas ist denn das da drüben?", sourceObjectiveStatus = "unverified-source-field" }
quests[27745] = { id = 27745, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein feuriges Wiedersehen", description = "Das ist Magmazahn, mein Feuerelementar, mit dem ich mich zerstritten habe. {name}, Ihr müsst ihn töten, sonst tötet er mich!\n\nEs war alles ein großes Missverständnis. Woher hätte ich denn ahnen sollen, dass er böse wird, wenn ich mir unten in Tiefenheim sein Herz \"ausleihe\"? Er kann nicht sterben... zumindest nicht dauerhaft!\n\nBestimmt hat er die Portalsteuerung bei sich. Ihr müsst ihm die Steuerung abnehmen und sie im Feuerportal benutzen, um uns zurück zum Eingang zu bringen.", sourceObjective = "Beschafft Euch die Feuerportalsteuerung und benutzt sie am Feuerportal.", completion = "Wir haben überlebt und alle Portale sind abgeschaltet!\n\nIhr glaubt doch nicht, dass Magmazahn mir das nachträgt, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[27746] = { id = 27746, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Königreich aus Dreck", description = "Dieser Krieg hat uns als Volk viel gekostet. Wir haben viel verloren, um unseren angestammten Platz als die rechtmäßigen Herrscher von Lordaeron zu sichern. Und obwohl wir für den Moment die Oberhand haben, tobt die Schlacht in anderen Teilen der Östlichen Königreiche weiter.\n\nIch muss nach Unterstadt zurück, um mich zu erholen. Ich möchte, dass Ihr an meiner Statt in das Vorgebirge des Hügellands reist, {name}. Als <mein verdientester Soldat/meine verdienteste Soldatin> werdet Ihr unsere Streitkräfte in die absolute Vorherrschaft über unsere Feinde im Hügelland führen.\n\nMeldet Euch bei Hochexekutorin Darthalia am Südwachttor im Osten.", sourceObjective = "Meldet Euch bei Hochexekutorin Darthalia am Südwachttor im Vorgebirge des Hügellands.", completion = "Die Kunde von Eurem Sieg im Silberwald ermutigt uns, {name}. Wir sind bereit, unter Eurem Kommando zu kämpfen und die letzten Überreste der Menschheit aus dem Hügelland zu vertreiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[27747] = { id = 27747, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flammenkrieg", description = "Viele Wildhämmer sind bereits aus ihren Heimen geflohen. Jetzt ist es Zeit, sie vollständig von der Karte zu tilgen.\n\nOben auf dem Grat im Norden findet Ihr verlassene Häuser in den Ruinen von Donnermar. Dort haben sie viele Fässer mit starkem Donnermarbier zurückgelassen.\n\nDonnermarbier hat einen Alkoholgehalt von 220 Prozent. Ich habe keine Ahnung, wie das überhaupt geht.\n\nZerschlagt die Fässer und zündet ihren Inhalt an. Brennt sie aus! Lasst den Zwergen nichts, zu dem sie zurückkehren könnten.", sourceObjective = "Zerschmettert 10 Fässer mit Donnermarbier in den Ruinen von Donnermar.", completion = "Ja, ja. Treibt sie mit Feuer hinaus, wie Murmeltiere aus ihren Löchern…\n\nGut gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27748] = { id = 27748, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glück und Ruhm", description = "Wir müssen in Bewegung bleiben, {name}. Es ist nur eine Frage der Zeit, bevor die Truppen die Kurve kriegen.\n\nDie Lade sollte sich direkt hinter diesen Ruinen befinden.\n\nSeid wachsam. Irgendwie habe ich das Gefühl, dass es noch nicht vorbei ist.", sourceObjective = "Tötet den Obsidiankoloss.", completion = "Schön zu sehen, dass Ihr unversehrt seid, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27749] = { id = 27749, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nehmt die Kultisten fest", description = "Gut, dass Ihr diese Notiz zu mir gebracht habt, {name}. Die Proklamation des Königs kam zu spät; ihre Spitzel sind bereits in der Stadt zugange.\n\nDiese Notiz enthält Anweisungen und Treffpunkte für die Kultisten, sagt uns aber nichts darüber, was sie vorhaben. Unsere Feinde sind schlauer geworden. Es wird schwer werden, alle Kultisten in der Stadt aufzuspüren, aber wir müssen so viele dingfest machen, wie wir können. Benutzt diese Fesseln, um jeden Agenten festzunehmen, den Ihr finden könnt, bringt sie anschließend zum Eingang des Verlieses und meldet Euch bei mir, wenn Ihr fertig seid.", sourceObjective = "Benutzt die schweren Handfesseln, um 5 infiltrierende Kultisten festzunehmen und bringt sie dann zu Aufseher Thelwasser im Verlies von Sturmwind. Wenn Ihr Eure Gefangenen dorthin gebracht habt, verhört einen der inhaftierten Kultisten im Verlies.", sourceObjectiveStatus = "unverified-source-field" }
quests[27750] = { id = 27750, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlacht am Buffet", description = "<Griffs Magen knurrt.>\n\nImmer, wenn das Drachenmal in den Krieg zieht, geht keiner mehr jagen.\n\nDas beste Essen schnappen wir den Feind direkt vor dem Mund weg. Auf dem Grat nördlich des Flusses gibt es eine Reihe von zerstörten Häusern der Wildhämmer. Ich wette, sie sind randvoll mit Köstlichkeiten.\n\nBringt mir etwas davon.", sourceObjective = "Sammelt 10 Nahrungsmittelvorräte der Wildhämmer in den Ruinen von Donnermar.", progress = "Hunger.", completion = "<Griff stürzt sich gierig auf den Haufen von Nahrungsmitteln, genug, um ein Dutzend Männer zu ernähren.>\n\nToll! Habt Ihr für Euch selbst auch etwas mitgebracht?", sourceObjectiveStatus = "unverified-source-field" }
quests[27751] = { id = 27751, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vernichtet die Wildhämmer", description = "Seit mein Volk Anspruch auf das Hochland erhoben hat, sind die Wildhammerzwerge unsere erbittertsten Feinde. Wir haben sie in Grim Batol bekämpft, wir haben sie im Sumpfland bekämpft und selbst jetzt tobt ein offener Krieg im Norden, jenseits des Flusses in den Ruinen von Donnermar.\n\nBeweist mir Euren Wert. Sucht und vernichtet die Kriegsgezeichneten der Wildhämmer. Die Besten unter ihnen tragen Insignien. Meine Krieger sammeln sie gleich dutzendweise.\n\nKönnt Ihr das auch?", sourceObjective = "Tötet Kriegsgezeichnete der Wildhämmer, um 8 Insignien der Wildhämmer zu sammeln. Auch einzigartige Gegner in den Ruinen von Donnermar tragen Insignien bei sich.", progress = "Zeigt mir die Insignien, die Ihr gesammelt habt, {class}.", completion = "<Narkrall schließt seine wettergegerbte Faust fest um die Insignien.>\n\nAlso, {class}. An Euch ist mehr dran, als ich erwartet habe.\n\nVielleicht kann Eure Horde es mit meinen besten Kriegern aufnehmen. Finden wir es heraus…", sourceObjectiveStatus = "unverified-source-field" }
quests[27752] = { id = 27752, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kämpfen wie ein Wildhammer", description = "Ich übertreibe nicht, wenn ich sage, dass wir in Donnermar das beste Bier in den Östlichen Königreichen brauen. Es hat 220 Prozent! Ja, Ihr habt ganz richtig gehört!\n\nAls die verschiedenen Familien sich aus dem Süden in die Mitte der Stadt zurückgezogen haben, mussten sie ihr Bier zurücklassen.\n\n<Blundy hält inne, um die Schwere der Situation einsinken zu lassen.>\n\nHOLT ES ZURÜCK! Dieses Zeug macht selbst den trägsten Krieger zu einem wirbelnden Derwisch der tollwütigen Zerstörung. Holt Euch diese Fässer! Sie sind unsere einzige Hoffnung!", sourceObjective = "Sammelt 10 Fässer voll Donnermarbier aus den Ruinen von Donnermar. Vorsicht! Es hat ganz schön Bumms!", progress = "Bringt mir dieses Bier, {name}.\n\nHe, Ihr habt doch nicht daran genippt, oder?", completion = "Oh, perfekt… Ich werde ein paar dieser Fässer zu meinen Jungs an der Front bringen. Dann geht der Tanz erst richtig los! Vielen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27753] = { id = 27753, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Essen zurücklassen", description = "Unsere Vorräte sind knapp bemessen, {name}. Von überall strömen Flüchtlinge nach Donnermar. Das sind ganz schön viele Mäuler, die gestopft werden wollen.\n\nViele Nahrungsmittel wurden zurückgelassen, als die Leute mit ihren Familien in die Sicherheit geflohen sind. Wir brauchen dieses Essen!\n\nDurchsucht die Ruinen von Donnermar südlich, östlich und südwestlich von hier nach ihren Nahrungsmittellagern.\n\nSeid vorsichtig, {class}! Um die Ruinen herum wird heftig gekämpft.", sourceObjective = "Sammelt 10 Nahrungsmittelvorräte der Wildhämmer in den Ruinen von Donnermar.", progress = "Habt Ihr was zu Beißen?", completion = "Ah, gut - und kaum eine Made oder Käfer zu finden!\n\nDas wird den Leuten, die hierher geflohen sind, das Leben retten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27754] = { id = 27754, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abreibung für das Drachenmal", description = "Das Drachenmal!\n\n<Colin spuckt aus.>\n\nMonster! Alles Monster! Seit dem letzten Krieg bekämpfen wir uns auf jedem gottverdammten Hügel und in jedem Tal. Und jetzt schließen sie sich der Horde an?\n\nWenn Ihr uns Wildhämmer dazu bringen wollt, uns mit Euch unter dem Allianzbanner zusammenzutun, dann solltet Ihr Euch am besten im Kampf gegen das Drachenmal beweisen. Stürzt Euch in die Schlacht, die in den Ruinen von Donnermar im Süden und Südwesten tobt. Tötet die Marodeure des Drachenmalklans und sammelt die Insignien ihrer besten Krieger. Dann reden wir weiter.", sourceObjective = "Tötet Marodeure des Drachenmals und sammelt 8 Insignien des Drachenmals. Auch einzigartige Gegner in den Ruinen von Donnermar tragen Insignien bei sich.", progress = "Wie läuft der Kampf, {class}?", completion = "Schau sich das einer an! Da habt Ihr aber eine beeindruckende Trophäensammlung.\n\nIch werde den anderen davon berichten. Wenn ein einzelner {class} der Allianz das erreichen kann, kaum vorzustellen, was der Rest von Euch zu leisten vermag!", sourceObjectiveStatus = "unverified-source-field" }
quests[27755] = { id = 27755, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fluch der Gräber", description = "Die Neferset sind nicht die einzige Bedrohung unserer geheiligten Gräber.\n\nEine Expedition der Gnome stolperte vor einigen Wochen in unsere Lande.\n\nSie haben nicht auf unsere Warnungen gehört und sich zu tief in ein verfluchtes Gewölbe hineingegraben.\n\nJetzt liegt auf der gesamten Expedition ein furchtbarer Fluch, der ihnen den Verstand geraubt und ihre Gedanken übernommen hat.\n\nNun suchen sie Zugang zu den tiefsten Gewölben Uldums und bilden eine große Bedrohung. \n\nGeht zu der Sonnensteinterrasse und erlöst ihre getriebenen Seelen von ihrem Elend.", sourceObjective = "Tötet 6 wahnsinnige Gräber und Robogenieur Mischgeweb.", completion = "Es war nicht möglich, sie zu retten, {name}. Der uralte Fluch, der sie befallen hat, kann nicht von ihnen genommen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27756] = { id = 27756, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Vorarbeiter", description = "Wenn wir herausfinden wollen, was hier vor sich geht, müssen wir uns wohl durch die gesamten Todesminen schlagen! Glubtok der Vorarbeiter wird der erste ernsthafte Gegner sein, auf den Ihr trefft, ein mächtiger Ogermagier. Seid vorsichtig, er verfügt über die rohe Kraft seiner Spezies, kombiniert mit seinen verruchten Zauberkünsten!\n\nNehmt diesen Kommunikator, damit ich mit Euch in Verbindung bleiben kann, während wir mit den Untersuchungen voranschreiten. Seid vorsichtig da unten.", sourceObjective = "Tötet Glubtok.", progress = "Ja?", completion = "<Bzzzzzzzzzzzzt.>\n\nGut gemacht! Saubere Arbeit. Dringt nun weiter vor und seht, was Ihr sonst noch aufspüren könnt! Mit Euch auf unserer Seite knacken wir diesen Fall wie eine Walnuss. Ich weiß es genau.", sourceObjectiveStatus = "unverified-source-field" }
quests[27757] = { id = 27757, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die dunkelsten Abgründe", description = "Ich habe im ganzen Sumpf gesehen, wie seltsam sich die Meereskreaturen verhalten. Die Murlocs, ja, aber vorher auch die Gilblins und die Makrura... ich habe neulich sogar einige Naga an den Strand wandern sehen.\n\nIrgendetwas ruft sie hierher, und peitscht sie zur Raserei auf. Viele der Kreaturen wurden in die Stagalsumpfhöhle im Westen gelockt. Da unten ist irgendetwas, und wenn es noch stärker wird, werden wir alle auch anfangen, hineinzuwandern...\n\nIhr solltet es aufhalten, was immer es auch ist. Bevor es zu spät ist.", sourceObjective = "Tötet Hr'nglth den Verirrten.", completion = "Oje. Es klingt als wärt Ihr einem ziemlich finsteren Wesen über den Weg gelaufen. Ich frage mich nur, was einer von denen so weit hier draußen wollte...", sourceObjectiveStatus = "unverified-source-field" }
quests[27758] = { id = 27758, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zimmermann", description = "<Bzzzzzzzzzzzzt.>\n\nHallo? Könnt Ihr mich hören? Ausgezeichnet!\n\nEs scheint, als wäre Helix dabei, einen riesigen Mast zu bauen. Ihr glaubt doch nicht, dass er versucht, den Moloch der Defias fertigzustellen, oder?\n\nDas solltet Ihr lieber untersuchen, {name}. Und scheut Euch nicht, Euch die Hände schmutzig zu machen! Ihr habt die Erlaubnis, bei Bedarf tödliche Gewalt anzuwenden. Und offen gestanden wird das wahrscheinlich auch nötig sein.", sourceObjective = "Besiegt Helix Ritzelbrecher.", completion = "<Bzzzzzzzzzzzzt.>\n\nHe, hier ist Horatio. Das war aber spannend! Ich verfolge Eure Fortschritte auf der Spionatron X3-Funktion auf meinem Sturmwind-Kommunikator.\n\nSie verstecken ihr Werk aber hinter ganz schön vielen verstärkten Türen. Rückt weiter vor und schaut, was Ihr als Nächstes finden könnt. Ich wette, es wird ein ganz großer Hinweis sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[27760] = { id = 27760, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Künstliche Intelligenz", description = "<Eine weibliche Stimme spricht aus dem tragbaren Terminal zu Euch.>\n\nNotfallcode: 55-729\n\nFunktionen des oberen Zerebralkortex der Expeditionsmitglieder sind gestört.\n\nBitte beim nächsten Terminal im Südosten der Sonnensteinterrasse für weitere Analysen melden.", sourceObjective = "Sprecht mit dem A.I.D.A.-Terminal am Feldmesserposten in Uldum.", progress = "<Der Terminal surrt, als seine Mechanismen sich in Gang setzen.>", completion = "Scanne Objekt... \n\nZerebralkortexdiagnostik zeigt keine Anzeichen des \"Grabfluch\"-Phänomens.\n\nDiagnostik enthüllt diverse Schädeltraumata. Dem Nutzer wird empfohlen, in Zukunft in der Nähe stumpfer Gegenstände größere Vorsicht walten zu lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27761] = { id = 27761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine bombige Ablenkung", description = "Der Fluch hat die höheren Gehirnfunktionen der Expeditionsmitglieder übernommen. Doch meine Berechnungen zeigen, dass ihr unterdrücktes, jugendliches Unterbewusstsein durch realistische Bilder stimuliert werden kann.\n\nBenutzt diesen Holoprojektor, um sie abzulenken.\n\nSie sind gerade dabei, Sprengsätze in dem Grab im Osten anzubringen, weil sie versuchen wollen, Zugang zu den Geheimgängen Uldums zu erlangen.\n\nSie suchen gefährliche Neuerschaffungstechnologie unter Uldum und müssen aufgehalten werden.", sourceObjective = "Entschärft den ersten, zweiten und dritten Sprengsatz und deaktiviert 4 instabile Bombenbots am Grab des Sonnenkönigs.", completion = "Gut gemacht, {name}. Die Expedition hat sich bereits selbst dem Untergang geweiht.\n\nEs gibt keinen Grund, den Rest der Welt auch noch in Gefahr zu bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27762] = { id = 27762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf nach Luntenbrand!", description = "He, {race}, hört mal her. Ich habe einen Auftrag, den Ihr Euch sicher nicht entgehen lassen wollt.\n\nWir wurden aus Luntenbrand, einer neuen Goblinstadt tief im Ödland, hier hoch geschickt. Da unten gibt es jede Menge Geld zu verdienen! Außerdem treiben sich dort nicht annähernd so viele Zombies oder verklemmte Paladine herum.\n\nWeit und breit nur ungezähmte Wildnis da unten und wir suchen nach jemandem, der uns dabei hilft, das zu ändern. Wenn Ihr so weit seid... wir warten auf Euch.", sourceObjective = "Fliegt auf der Unkaputtbaren ins Ödland und meldet Euch dort bei Eddie Flofizzle.", completion = "Hübsche Landung!", sourceObjectiveStatus = "unverified-source-field" }
quests[27763] = { id = 27763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ins Zentrum von Luntenbrand", description = "Das hier, {race}, ist das Paradies. Ich wollte schon immer in einer netten, ruhigen Stadt am Meer leben, damit ich mich ganz ohne Ablenkungen auf meine Explosionen konzentrieren kann.\n\nRuhe ist jedoch nicht jedermanns Sache. Besonders, wenn man eher der abenteuerlustige Heldentyp ist, so wie Ihr.\n\nWir haben am anderen Ende der Stadt einen Teleporter installiert, der Euch auf die Klippen bringt. Von dort aus könnt Ihr den kurzen Ritt Richtung Westen ins Zentrum von Luntenbrand wagen, mitten im Ödland.\n\nDort sollte es mehr für Euch zu tun geben. Sagt einfach, dass Flo Euch schickt.", sourceObjective = "Benutzt den Teleporter an der Rückseite von Luntenbrand-am-Meer, um auf den Berg zu gelangen, und meldet Euch dann bei Dolph Blastus in Luntenbrand im Ödland.", completion = "Willkommen in Luntenbrand!", sourceObjectiveStatus = "unverified-source-field" }
quests[27764] = { id = 27764, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine seltsame Bitte", description = "Kommen wir zu etwas anderem. Ich habe ein Paket, das geliefert werden muss.\n\nVor nicht allzulanger Zeit kam eine junge Dame in unsere Stadt, die komprimiertes Sprengpulver, eine gehärtete Mithrilbombenhülle und eine Schutzbrille wollte. Natürlich konnten wir ihr eine Menge Sprengpulver und Bombenhüllen verkaufen, aber die Schutzbrille war etwas schwieriger zu beschaffen.\n\nUm es kurz zu machen: Ich habe die Schutzbrille, aber sie ist schon zu ihren Studien in der Lethlorklamm zurückgekehrt. Bringt ihr sie für mich zu ihr?", sourceObjective = "Bringt Dolphs Paket zu Rhea in der Lethlorklamm im Ödland.", progress = "Ahh... Ihr habt mich gefunden. Gut.", completion = "Ich danke Euch, {race}. Die Schutzbrille könnt Ihr behalten, da sie ja bereits ihren Zweck erfüllt hat: sie hat Euch zu mir gebracht.", sourceObjectiveStatus = "unverified-source-field" }
quests[27765] = { id = 27765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erste Probe: Wilde Eier", description = "Ich experimentiere mit Schwarzdrachen. Genauer gesagt interessiere ich mich für ihre Fortpflanzung.\n\nFür meine aktuellen Experimente benötige ich viele Schwarzdracheneier, weshalb ich hier in der Lethlorklamm bin. Ich würde die Eier ja selbst sammeln, aber ich glaube, es wäre zu Eurem Nutzen, wenn Ihr mir dabei helfen würdet.\n\nIhr könnt sie am Rand der Schlucht finden. Hütet Euch vor den Wächtern, die oben kreisen - sie freuen sich nicht über Eierdiebe.", sourceObjective = "Besorgt 6 Eier von wilden Schwarzdrachen.", progress = "Habt Ihr die Eier dabei?", completion = "Danke, dass Ihr sie so schnell gesammelt habt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27766] = { id = 27766, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zweite Probe: Welpen", description = "Ihr müsst mir noch einen Gefallen tun. Ihr müsst mir die Körper der Schwarzdrachenwelplinge bringen, die in der Nähe herumfliegen. Tötet sie und bringt mir ihre Leichen.", sourceObjective = "Besorgt 10 Kadaver von brühenden Welpen.", progress = "Seid Ihr meiner Bitte nachgekommen?", completion = "Diese grausige Aufgabe war notwendig, {name}.\n\nAlles wird sich Euch bald offenbaren. Fürs Erste nur so viel:\n\nIch bin kein gewöhnlicher Goblin.\n\nIch diene einer Herrin von unvorstellbarer Macht und ihre Beweggründe sind nicht so finster, wie sie erscheinen mögen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27767] = { id = 27767, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wieder in geheimer Mission unterwegs", description = "Die Kultisten scheinen sich ihres Sieges sicher zu sein, selbst da wir immer mehr von ihnen festnehmen. Wir müssen mehr über das Ritual in Erfahrung bringen, von dem der Kultist während des Verhörs sprach.\n\nDiese Rituale scheinen das Kernstück des Angriffsplans der Kultisten zu sein. Ich gebe Euch eine der Roben, die wir den verhafteten Kultisten abgenommen haben. Zieht sie an und begebt Euch zurück zum Außenposten der Kultisten im Obsthain am Spiegelsee im Wald von Elwynn und versucht die Kultisten dazu zu bringen, Euch in den Plan einzuweihen.", sourceObjective = "Legt Eure Rekrutenrobe an, geht zum Obsthain am Spiegelsee und erhaltet das Buch der Zauberformeln von Aufseherin Sylandra. Lest aus dem Buch der Zauberformeln vor, während Ihr am Kultistenaltar steht, um das Ritual zu üben.", sourceObjectiveStatus = "unverified-source-field" }
quests[27768] = { id = 27768, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zweiter Schritt: Der Blutvergießer", description = "Die Trolle hier setzen den Fall meiner Brüder in den Alptraum ewig fort. Sie infizieren und korrumpieren grüne Drachen mit dem Blut ihres verruchten Gottes, und ernten dann das Böse, das in ihnen gediehen ist. Sie werden wie Vieh gezüchtet...\n\nDiese ekelerregenden Untaten dürfen nicht fortgesetzt werden. Kehrt zum Ausgang der Halle der Masken zurück und nehmt den anderen Korridor in Richtung des Schlachthofs. Gomora der Blutvergießer erntet dort Leichen für diese abscheulichen Rituale. Entledigt ihn seines unverdienten Lebens!", sourceObjective = "Tötet Gomora den Blutvergießer im Schlachthof.", sourceObjectiveStatus = "unverified-source-field" }
quests[27769] = { id = 27769, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rhea enthüllt", description = "Wie schon angedeutet bin ich kein gewöhnlicher Goblin. Vielleicht habt Ihr meine wahre Identität bereits erraten.\n\nLasst mich Euch meine wahre Form zeigen. Da Ihr Euch als vertrauenswürdig erwiesen habt, werde ich die Details meines Planes mit Euch teilen.", sourceObjective = "Erfahrt Rheas wahre Identität.", progress = "Ihr seid aber ungeduldig, {name}.", completion = "Mein wahrer Name ist Rheastrasza und ich bin eine Abgesandte von Alexstrasza, dem Aspekt des roten Drachenschwarms.\n\nDa Todesschwinge derzeit mit anderen Dingen beschäftigt ist, werden wir einen Weg finden, um den schwarzen Drachenschwarm zu erlösen.\n\nUnd Ihr werdet uns dabei helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27770] = { id = 27770, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Schleier lüften", description = "Der schwarze Drachenschwarm war einst nobel. Sie waren die Bewacher der Erde und schützten die Lande. Welch Ironie, dass ausgerechnet sie zur schlimmsten Bedrohung wurden, die das Land je erlebt hat.\n\nIch glaube aber, dass es noch einen Funken Hoffnung gibt - und meine Herrin sieht das ebenso. Der schwarze Drachenschwarm wird auch nach Todesschwinges Verrat weiter existieren und wieder als nobler Bewacher der Erde zum Himmel aufsteigen.\n\nIch möchte Euch etwas zeigen. Schließt Eure Augen und ich werde Euch den letzten Teil meiner Studien enthüllen.", sourceObjective = "Werdet Zeuge des letzten Teils von Rheas Studien.", progress = "Ihr seid äußerst ungeduldig, {name}.", completion = "Wir werden noch einen Funken Gutes in diesen Drachen finden, {name}. Entweder in den wilden Eiern, die Ihr gefunden habt, in den Körpern der Welplinge, die Ihr getötet habt, oder in den Eiern, die Nyxondra gelegt hat, als wir sie dazu ermutigten... Wir werden einen unverdorbenen schwarzen Drachen finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27771] = { id = 27771, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dritte Probe: Implantierte Eier", description = "Nyxondra wird gegen ihren Willen festgehalten. Sie wird mitten in den Brutstätten vor ihrem eigenen Schwarm versteckt. Sie legt zwar Eier, aber man nimmt sie ihr weg, bevor sie sie ausbrüten kann.\n\nGrausam? Vielleicht... Aber nicht annähernd so grausam wie das, was ihr Drachenschwarm meiner Herrin angetan hat.\n\nBeweist mir, dass ich Euch vertrauen kann, {name}. Bringt Nyxondras Eier zu mir. Ihr müsst Nyxondra schlagen, bis sie sich fügt, bevor Ihr die Eier nehmen könnt.", sourceObjective = "Beschafft 3 von Nyxondras Eiern.", progress = "Vergesst nicht, {name}... Dies geschieht zum Wohl des schwarzen Drachenschwarms. Wir sind hier, um ihn zu erlösen, nicht, um ihn zu verletzen. Dies ist nur ein Schritt auf dem Weg zu seiner Gesundung.", completion = "Ihr habt alles, was ich Euch aufgetragen habe, ohne zu fragen erledigt. Unsere Arbeit hier in der Lethlorklamm ist getan.\n\nJetzt ist es an der Zeit, dass ich Euch in alles einweihe.", sourceObjectiveStatus = "unverified-source-field" }
quests[27772] = { id = 27772, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der ehrwürdige Doktor Blam", description = "Ich habe eine ganz bewusste Entscheidung getroffen, als ich mich Euch zu erkennen gab, {name}. Ich brauche Euer Vertrauen, aber ich kann nicht länger hier in der Lethlorklamm bleiben, da meine Verkleidung ganz klar aufgeflogen ist.\n\nIhr jedoch könntet unentdeckt entwischen. Hier, nehmt die Ergebnisse unserer Forschungen und bringt sie nach Westen. Auf der Agmondkuppe werdet Ihr einen Gnom finden, der weiß, was mit diesen Proben zu tun ist.\n\nBeeilt Euch, {name}! Ihr dürft hier nicht herumtrödeln!", sourceObjective = "Bringt die Proben der schwarzen Drachen zu Dr. Hieronymus Blam auf der Agmondkuppe im Ödland.", progress = "Dr. H. Blam, zu Euren Diensten. Wie kann ich Euch heute behilflich sein?", completion = "Ooh! Wissenschaftszeug! Dann lasst uns mal sehen, was Ihr da habt...\n\nWilde Eier? Bäh. Nutzlos. Damit kann doch niemand etwas anfangen.\n\nOoooh, was ist das? Eine Art... vorkonstruiertes Ei? Das sieht vielversprechend aus, aber ich will lieber nicht wissen, was Rhea tun musste, um es zu bekommen.\n\nHmm... ja, ein paar wirklich nette Leichen. In der Tat, sehr nett.\n\nIn Ordnung, ich werde sehen, was ich tun kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[27773] = { id = 27773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dritter Schritt: Prophet", description = "Alles, was jetzt noch zwischen mir und dem Tempel steht, ist Prophet Jammal'an selbst. Er ist der Anführer der Atal'aitrolle hier, ein bösartiger Manipulator.\n\nWisset, dass Ihr nicht bloß auf einen verrückten Troll treffen werdet, {name}, sondern auf ein Instrument von Kräften, die Eure finstersten Vorstellungen übertreffen. Doch Ihr kämpft nicht allein... Meine Stärke und der Wille des grünen Drachenschwarms werden Euch begleiten.\n\nBegebt Euch zum Höhlenbau des Rufenden, links durch die Halle des Rituals, und von da in die Halle der Knochen. An ihrem unteren Ende werdet Ihr Jammal'an finden.", sourceObjective = "Bezwingt Jammal'an den Propheten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27774] = { id = 27774, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einfach zu beeinflussen", description = "Die größte Bedrohung für Luntenbrand ist zweifellos die Ogerkolonie im Nordwesten.\n\nDie meisten unserer Ogernachbarn waren Kriegertypen, aber es sieht aus, als würden mehr und mehr von ihnen Magie ausüben. Ich werde keine Ogermagier vor meiner Haustür zulassen.\n\nGeht und macht ein paar dieser Staubspeieroger unschädlich. Hoffentlich lassen sie sich das eine Lehre sein und legen sich nicht mehr mit der Macht von Luntenbrand an.", sourceObjective = "Tötet 9 Staubspeieroger in Camp Kosh.", completion = "Ich frage mich, wo all diese Ogermagier herkommen. Wahrhaftig erstaunliche Zeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27775] = { id = 27775, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn's mal wieder schwerer wird, improvisiere!", description = "Ich schaffe es einfach nicht, meine Erfindung in Gang zu bringen. Gah!\n\nDas ist es! Ich habe eine Entscheidung getroffen. Ich werde improvisieren und Magie verwenden.\n\nWas meiner Erfindung wirklich fehlt ist ein solider Kolben, der dünn genug ist, um durch ein schmales Kupferrohr zu passen. Dabei muss er auch stark genug sein, um regelmäßigen Stößen widerstehen zu können. Die magischen Ruten, die die Ogermagier nördlich von hier bei sich tragen, sind genau das Richtige.\n\nSoweit ich weiß, tragen nur die Instrukteure Ruten, die stark genug sind.", sourceObjective = "Beschafft eine Instrukteursrute von den Instrukteuren der Ogermagier in Camp Kosh.", progress = "Ich lasse mich nur ungern dazu herab, Magie in meinen Erfindungen einzusetzen, aber in diesem Fall handelt es sich praktisch um einen Notfall.", completion = "Passt perfekt! Mein Ziegenschläger ist endlich vollendet!", sourceObjectiveStatus = "unverified-source-field" }
quests[27776] = { id = 27776, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit für Ziegen, Baby", description = "Falls es Euch entgangen sein sollte, wir haben hier in Luntenbrand ein kleines Ziegenproblem. Sie fressen alles und scheinen eine Vorliebe für die Häufchen aus Zahnrädern und Getrieben, die wir überall herumliegen lassen, zu haben.\n\nDas wird allmählich wirklich lästig!\n\nIhr findet die meisten Ziegenböcke am Rande der Stadt in der Nähe der Klippen. Benutzt dieses Gerät, um ihnen einen kleinen \"Schubs\" zu geben.", sourceObjective = "Benutzt Garyannes Ziegenboxer an 12 Ziegenböcken in Luntenbrand.", completion = "Gut gemacht! Zweifellos werden die Ziegen zurückkommen, aber sie werden es sich zweimal überlegen, ehe sie noch einmal an meinen Zahnrädern knabbern!", sourceObjectiveStatus = "unverified-source-field" }
quests[27777] = { id = 27777, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kernzugriffcodes", description = "Die Zahl der Expeditionsteilnehmer ist sehr groß, Nutzer {name}.\n\nSich mit normalen Mitteln um sie zu kümmern würde geschätzte 2.700.136,5 Stunden dauern.\n\nWir können uns einer mächtigen Energiequelle bedienen, die sich in dem Raupenfahrzeug der Expedition befindet.\n\nDazu müssen wir allerdings die Zugangscodes für den Fusionskern finden.\n\nRobogenieur Pfuschelflux hat diese Codes und befindet sich im Sternbeobachtungsturm im Südosten.\n\nIch habe einen Scrambler mit Störfrequenzen gefüttert. Benutzt ihn, um Pfuschelflux' Schutzmechanismen vorübergehend außer Kraft zu setzen.", sourceObjective = "Beschafft die Kernzugriffscodes von Pfuschelflux dem Wahnsinnigen.", progress = "Hattet Ihr Erfolg, {name}? Ich hatte Eure Überlebenschance mit 68,5 % berechnet.", completion = "Ausgezeichnete Arbeit, Nutzer {name}. Jetzt müssen wir uns Zugang zum Fusionskern verschaffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27778] = { id = 27778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Wibson hacken", description = "Es ist wahr. Neue Expeditionsmannschaften sind auf dem Seeweg eingetroffen.\n\nMeine Scanner haben entdeckt, dass sie bereits von dem Fluchphänomen befallen sind.\n\nIhr müsst Euch beeilen und sofort an Bord der M.A.C. Dyver gehen. Die Zugangscodes werden uns die Kontrolle über die Funktionen des Fusionskerns geben, doch wir müssen noch einen Sicherheitslevel umgehen.\n\nNutzer {name}, ich muss Euch bitten, Euch in einen sehr ausgefeilten Großrechner bekannt als der \"Wibson\" zu hacken.\n\nKeine Sorge, ich werde Euch weitere Instruktionen zukommen lassen.", sourceObjective = "Hackt Euch in den Wibsongroßrechner an Bord der M.A.C. Dyver.", completion = "Ich habe alles unter Kontrolle, Nutzer {name}. Aber ich kann die Kerntemperatur nicht auf unbestimmte Zeit stabil halten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27779] = { id = 27779, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auslöschung der Gnome", description = "Ich habe mein Programm in den Fusionskern geladen und habe jetzt die volle Kontrolle darüber.\n\nIch habe eine kleine Luftblase darin geschaffen, um zu verhindern, dass Nutzer {name} pulverisiert wird.\n\nIch werde eine Steuerung für all meine Bewegungsfunktionen generieren, damit ich meine Schaltkreise der Stabilisierung des Kerns widmen kann.\n\nGeht den Hügel hinunter und neutralisiert so viele Expeditionsmitglieder wie möglich.\n\nMeine Analyse hat ergeben, dass Ihr möglicherweise... \"Schuld\" empfinden könntet bei solch einer großen Anzahl Todesfälle.\n\nNutzer {name}, Ihr müsst Euch darüber klar sein, dass es keine Hoffnung für die Expeditionsmitglieder gibt.", sourceObjective = "Löscht 512 wahnsinnige Gnome aus.", completion = "Es ist vollbracht, Nutzer {name}. Ich danke Euch für Eure Hilfe bei dieser bedauernswerten Aufgabe.", sourceObjectiveStatus = "unverified-source-field" }
quests[27780] = { id = 27780, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lippenbekenntnisse...", description = "Nun, da Ihr mit dem Ritual vertraut seid, ist es an der Zeit, es in der Stadt durchzuführen. Dutzende unserer Brüder haben die Stadt bereits infiltriert und Stellung an den Ritualpositionen bezogen.\n\nIch möchte, dass Ihr die Ritualpositionen im Zwergendistrikt, im Park und am Kathedralenplatz Sturmwinds aufsucht. Die einzelnen Gruppen werden dort schon die wesentlichen Vorbereitungen getroffen haben und Ihr müsst lediglich den letzten Teil der Zauberformel aus dem Buch vorlesen.\n\nSehr bald, {name}, wird Sturmwind von Wind und Wasser verschlungen werden.", sourceObjective = "Stört die Kultistenrituale im Zwergendistrikt, dem Park und dem Kathedralenplatz indem Ihr die falschen Passagen aus dem Buch der Zauberformeln vorlest.", sourceObjectiveStatus = "unverified-source-field" }
quests[27781] = { id = 27781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Maschinerie", description = "<Bzzzzzzzzzzzzt.>\n\n<Bzzzzzzzzzzzzt.>\n\nHa-hallo? {name}, seid Ihr da? Seid Ihr noch am Leben? Hallo?\n\nOh, gut, Ihr seid noch da! Was im Namen Lordareons bauen die da? Es ist eine Art mechanisches Monstrum! Ihr müsst sie daran hindern, dieses... dieses... Ding fertigzustellen! \n\nVergesst alle Regeln, tut einfach nur, was Ihr tun müsst, um sie aufzuhalten!", sourceObjective = "Zerstört den Feindschnitter 5000.", completion = "<Bzzzzzzzzzzzzt.>\n\nIhr nähert Euch dem Herzen ihres Einflussbereichs. Wahrscheinlich wird das Allerheiligste der gesamten Defiasoperation von einer extrem verstärkten Tür geschützt. Schaut, ob Ihr etwas finden könnt, um sie aufzubrechen!\n\nIch schlage eine unauffällige Methode vor.", sourceObjectiveStatus = "unverified-source-field" }
quests[27782] = { id = 27782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mathias braucht Euch", description = "Wir hatten viel Spaß miteinander. Es tut mir sehr leid, dass Ihr gehen müsst. Aber Mathias sagte, dass er Euch braucht.\n\nEr sagte auch, es sei dringend!\n\nAlso, wollt Ihr nach dem, was ihr zu tun habt, vielleicht etwas trinken gehen, <Kumpel/meine Dame>?", sourceObjective = "Sprecht mit Meister Mathias Shaw bei der Schattenzitadelle im Schattenhochland.", completion = "Ihr seid zurück! Wir wissen, wo Cho'gall seine ultimative Waffe versteckt!", sourceObjectiveStatus = "unverified-source-field" }
quests[27783] = { id = 27783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garona braucht Euch", description = "Wir hatten viel Spaß miteinander. Es tut mir sehr leid, dass Ihr gehen müsst. Aber Garona sagte, dass sie Euch braucht.\n\nSie sagte auch, es sei dringend!\n\nAlso, wollt Ihr nach dem, was ihr zu tun habt, vielleicht etwas trinken gehen, <Kumpel/meine Dame>?", sourceObjective = "Sprecht mit Garona der Halborcin bei der Schattenzitadelle im Schattenhochland.", completion = "Ihr seid zurück! Wurde ja auch Zeit. Wir wissen, wo Cho'gall seine ultimative Waffe versteckt!", sourceObjectiveStatus = "unverified-source-field" }
quests[27784] = { id = 27784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schattenhammer", description = "Während Ihr in der Mine wart, konnte ich herausfinden, wo der Schattenhammer aufbewahrt wird. Er wurde am Zwielichtaltar im Süden geschmiedet.\n\nNoch wichtiger, die Kultisten haben einen schweren Fehler begangen: Cho'gall selbst überwacht seine Fertigstellung.\n\nViele Agenten des SI:7 sind gestorben, um uns diese Informationen zu bringen.", sourceObjective = "Gelangt zum Schattenhammer.", completion = "Der Schattenhammer schwebt in der Mitte des Altars, ungeschützt…", sourceObjectiveStatus = "unverified-source-field" }
quests[27785] = { id = 27785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Admiral", description = "<Bzzzzzzzzzt.>\n\nIch fasse es nicht... Sie sind beinahe mit dem Wiederaufbau fertig! Wir haben nicht viel Zeit, {name}.\n\nAdmiral Knurrreißer, Vanessas rechte Hand, muss sich an Bord befinden. Wir werden nie an sie herankommen, solange er am Leben ist. Ihr werdet die noch unvollendete Moloch besteigen, Knurrreißer aufspüren und töten müssen, sodass wir in Vanessas private Kajüte auf dem Oberdeck gelangen können.\n\nSeid vorsichtig, der Admiral steht unter dem Worgenfluch und würde Euch nur zu gern mit seinen Klauen zerreißen!", sourceObjective = "Tötet Admiral Knurrreißer.", completion = "<Bzzzzzzzzzzzzt.>\n\nEure Abenteuer haben Euch einigen Ruhm in Geheimdienstkreisen eingebracht, {name}. Viele hochrangige Mitglieder vom SI:7 haben Eure Infiltration der Todesminen mit ihren eigenen Sturmwind-Kommunikatoren aufmerksam verfolgt.\n\nMathias Shaw will höchstpersönlich mit Euch sprechen! Ich werde Euch sofort durchstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27786] = { id = 27786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schattenhammer", description = "Während Ihr in der Mine wart, konnte ich herausfinden, wo der Schattenhammer aufbewahrt wird. Er wurde am Schattenaltar der Stürme im Süden geschmiedet.\n\nNoch wichtiger, die Kultisten haben einen schweren Fehler begangen: Cho'gall selbst überwacht seine Fertigstellung.\n\n<Garona beginnt, ihre Klingen zu schärfen.>\n\nViele Kor'kron sind gestorben, um uns diese Informationen zu bringen.", sourceObjective = "Gelangt zum Schattenhammer.", completion = "Der Schattenhammer schwebt in der Mitte des Altars, ungeschützt…", sourceObjectiveStatus = "unverified-source-field" }
quests[27787] = { id = 27787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schädelberster der Berg", description = "Es war eine Falle! Cho'gall hat Euch mit dem Hammer angelockt, damit sein Gronn Euch den Rest geben kann.\n\nÜberlebt und tötet Schädelberster den Berg!", sourceObjective = "Überlebt und tötet dann Schädelberster den Berg.", completion = "Ihr habt es geschafft, Junge! Ihr habt den verdammten Gronn besiegt und Cho'gall in seine Bastion des Zwielichts zurückgeschickt.\n\nKeine Sorge. Mit Eurer Hilfe und der Eurer Freunde werden wir dort hineinkommen und Cho'gall ein für alle Mal den Garaus machen!", sourceObjectiveStatus = "unverified-source-field" }
quests[27788] = { id = 27788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schädelberster der Berg", description = "Es war eine Falle! Cho'gall hat Euch mit dem Hammer angelockt, damit sein Gronn Euch den Rest geben kann.\n\nÜberlebt und tötet Schädelberster den Berg!", sourceObjective = "Überlebt und tötet dann Schädelberster den Berg.", completion = "Ihr habt es geschafft, {name}! Ihr habt den verdammten Gronn besiegt und Cho'gall in seine Bastion des Zwielichts zurückgeschickt.\n\nKeine Sorge. Mit Eurer Hilfe und der Eurer Freunde werden wir dort hineinkommen und Cho'gall ein für alle Mal den Garaus machen!", sourceObjectiveStatus = "unverified-source-field" }
quests[27789] = { id = 27789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immer Ärger mit den Troggs", description = "Ich brauche ein wenig Zeit, um die Proben zu analysieren. Außerdem täte mir eine Pause von der Troggerschießerei ganz gut. Steigt in eines meiner Geschütze und erledigt so viele Troggs, wie Ihr nur könnt. Ich bleibe hier und führe meine Untersuchungen durch.\n\nDie Geschütze haben zwei Fähigkeiten: Einen normalen Schuss und eine elektrische Überladung, für den Fall, dass Euch zu viele Feinde zu nahe kommen. He he. Viel Glück.\n\nOh, und haltet nach den großen, langsamen Troggs Ausschau. Die sollten sich besser nicht in Eurer Nähe aufhalten.", sourceObjective = "Steigt in einen Kabummturm und überlebt vier Angriffswellen der Troggs.", progress = "Noch nicht ganz fertig. Brauche etwas mehr Zeit.", completion = "Die Ergebnisse sind da. Ich habe Spuren der Verderbtheit in allen drei Proben gefunden. Rhea wird ganz schön enttäuscht sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[27790] = { id = 27790, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nummer Eins der Defias", description = "Hallo, {name}. Ich habe viel von Euch gehört. Hört gut zu, denn Ihr werdet nur eine Chance bekommen.\n\nDie neue Nummer Eins der Defias muss in der Hütte sein und von dort die Strippen ziehen. Ich will, dass Ihr da reingeht und sie unschädlich macht, für die unzähligen Unschuldigen, die die von ihrem Vater gegründete Organisation getötet und terrorisiert hat.\n\nIch kann kaum glauben, dass sie Euch so nahe an sich heranlässt, ohne zu fliehen und auf eine bessere Gelegenheit zu warten, aber es sieht aus, als hätten wir Glück.", sourceObjective = "Erschlagt die Nummer Eins der Defias.", progress = "Ja?", completion = "Eure Anstrengungen hier könnten heute womöglich ganz Sturmwind gerettet haben, {name}. Vanessa ist zwar noch immer dort draußen, aber sie ist eine unerhebliche Gefahr, nun da wir den Moloch in unsere wachsame Obhut nehmen. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[27791] = { id = 27791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Staubwindausgrabung", description = "Ich habe eine Idee, die reine Spekulation ist. Zum Glück sind reine Spekulationen eine meiner Spezialitäten.\n\nNördlich von hier hat die Forscherliga neue Ruinen der Titanen unter dem Sand gefunden. Wenn es jemanden gibt, der älter und weiser ist, als die Drachen, sind es die Titanen. Ich habe sogar Gerüchte gehört, dass die Titanen die Drachen ERSCHAFFEN haben.\n\nSprecht mit Oberausgrabungsleiter Durdin im Lager nördlich von hier. Er wird weitaus mehr über die Titanen wissen als ich.\n\nWas habe ich Euch gesagt? Reine Spekulation.", sourceObjective = "Sprecht mit Oberausgrabungsleiter Durdin in der Staubwindausgrabung im Ödland.", completion = "Titanen? Ihr wollt etwas über Titanen wissen?\n\nDa seid Ihr genau an der richtigen Adresse, mein Lieber. Wir stehen vor einer großen Entdeckung.", sourceObjectiveStatus = "unverified-source-field" }
quests[27792] = { id = 27792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In der Liebe und im Krieg ist alles erlaubt. Und in der Archäologie auch.", description = "Moment mal, Eins nach dem Anderen. Ich werde mich hier nicht einfach hinsetzen und Euch alles erzählen, was wir in diesen Ruinen herausgefunden haben. Es gibt Probleme, um die wir uns kümmern müssen!\n\nAm wichtigsten sind diese Akademievandalen, die auf der anderen Seite des Grabs sind. Sie machen sich mit unserer ganzen Beute aus dem Staub! Wissen die denn nicht, dass Graben Zwergensache ist?\n\nJagt ein paar von deren 'Ausgräbern' - eher Banditen, wenn Ihr mich fragt - und bringt mir einige wertvolle Artefakte zurück.\n\nDANN unterhalten wir uns über Titanen.", sourceObjective = "Erlangt einen zerbrochenen Kelch, eine staubige Vase, eine irdene Hieroglyphe und ein Troggwerkzeug.", progress = "Eure Taschen sehen aber schwer aus. Beladen mit geplünderten Artefakten, hoffe ich?", completion = "Kelch... wertlos.\n\nVase... gefälscht.\n\nHieroglyphe... interessant, aber nicht weiter außergewöhnlich.\n\nWas haben wir denn da? Ich habe noch nie Kunsthandwerk der Troggs von diesem Kaliber gesehen! Da seid ihr aber auf etwas wirklich Seltenes gestoßen, {name}.\n\nNa gut, wie Ihr möchtet. Sprechen wir also über die Titanen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27793] = { id = 27793, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uralte Beschützer", description = "Ihr habt in der zentralen Kammer des Grabes recht viel Rumpeln gehört. Diese zwei großen Statuen sahen schrecklich verdächtig aus.", sourceObjective = "Untersucht den Wächter und die Schildwache.", sourceObjectiveStatus = "unverified-source-field" }
quests[27794] = { id = 27794, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zu Blam", description = "Innerhalb der Kiste findet Ihr einen kleinen, runden Gegenstand, der auf einem Kissen liegt.\n\nWenn es hier unten ein Titanenartefakt geben sollte, dann muss es das sein. Ihr beschließt, ihn zu Dr. Blam zurückzubringen.", sourceObjective = "Bringt das Auge der Behüter zu Dr. Hieronymus Blam bei der Agmondkuppe im Ödland.", progress = "Und? Hat sich unser Schuss ins Blaue ausgezahlt?", completion = "Bloß ein winzig kleines Gerät?\n\nIch habe diese Titanen noch nie verstanden.\n\nNun gut! Wollen wir doch mal sehen, was dieser Piepser kann!", sourceObjectiveStatus = "unverified-source-field" }
quests[27795] = { id = 27795, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flut der Dunkelheit", description = "Die Schlacht verläuft genau so, wie ich es wollte. Jetzt, da ihre Krieger erschöpft sind, habe ich die Reiterei hinein geschickt.\n\nWomit ich jedoch nicht gerechnet hatte, waren Oger. Unsere Ritter stehen den Schlägern zwar in nichts nach, dennoch werden sie Hilfe brauchen.\n\nIhr müsst sofort wieder auf das Feld, {name}. Nur wenige können einen Oger zu Fuß zur Strecke bringen, aber ich glaube, dass ich mich auf Euch verlassen kann. Enttäuscht mich nicht.", sourceObjective = "Tötet 6 Oger von Steinard.", completion = "Sich einem Oger direkt in den Weg zu stellen ist beeindruckend, {name}. Ich bin froh, dass ich Soldaten wie Euch da draußen habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[27796] = { id = 27796, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Bauer des Wächters", description = "Als diese Reliquientrottel hier auftauchten, gerieten wir in Panik und begannen, einfach wahllos zu plündern.\n\nViel zweifelhafte Archäologie spielte sich an diesem Tag ab.\n\nGlücklicherweise stieß Olga zufällig auf diese kleine Jadestatue. Wir dachten, es sei eine Art Schlüssel, konnten aber nichts finden, das sie hätte öffnen können. Vielleicht habt Ihr mehr Glück damit.", sourceObjective = "Findet im Grab der Wächter im Ödland Verwendung für den Bauer des Wächters.\n\nBereitgestellter Gegenstand:", completion = "<Die Statue rastet in ihren Platz auf der großen Steinplatte ein.>", sourceObjectiveStatus = "unverified-source-field" }
quests[27797] = { id = 27797, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Bauer der Schildwache", description = "Beinahe wurde uns diese Statue von einem der Reliquienhandlanger des Blutwächters gestohlen. Wir konnten ihn auf frischer Tat ertappen und bekamen die Statue zurück, aber es hat sich nicht wirklich gelohnt.\n\nEs scheint, als wäre sie eine Art Schlüssel, aber ich kann in diesen Ruinen nirgendwo das Schloss dazu finden. Möchtet Ihr es versuchen?", sourceObjective = "Findet im Grab der Wächter im Ödland Verwendung für den Bauer der Schildwache.\n\nBereitgestellter Gegenstand:", completion = "<Die Statue gleitet an ihren Platz auf der kalten Marmorplatte.>", sourceObjectiveStatus = "unverified-source-field" }
quests[27798] = { id = 27798, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wasser des Lebens", description = "Nehmt mein Wasser des Lebens und gebt es auf den Leichnam des ertrunkenen Zwergs.\n\nAls er lebte, bearbeitete er Metall. Und obwohl sein Leichnam jetzt meinen Loch nährt, kann er Euch dank des Wassers sagen, was Ihr wissen wollt.\n\nNehmt dann Eure Informationen und verschwindet aus meinem Reich.", sourceObjective = "Benutzt das Wasser des Lebens, um dem Leichnam von Schmiedemeister Finlay Informationen zu entlocken.", completion = "Der Schattenhammer? Und diese Informationen habt Ihr also von einem ertrunkenen Zwerg?\n\nIhr macht Scherze, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[27799] = { id = 27799, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lippenbekenntnisse...", description = "Nun, da Ihr mit dem Ritual vertraut seid, ist es an der Zeit, es in der Stadt durchzuführen. Dutzende unserer Brüder haben die Stadt bereits infiltriert und Stellung an den Ritualpositionen bezogen.\n\nIch möchte, dass Ihr die Ritualpositionen auf der oberen Ebene der Gasse, im Tal der Ehre in der Nähe der Halle der Kriegerhelden sowie am Westtor von Orgrimmar aufsucht. Die einzelnen Gruppen werden dort schon die wesentlichen Vorbereitungen getroffen haben und Ihr müsst lediglich den letzten Teil der Zauberformel aus dem Buch vorlesen.\n\nSehr bald wird die Stadt in Flammen aufgehen.", sourceObjective = "Stört die Kultistenrituale in der Gasse, im Tal der Ehre und in der Nähe des Westtors der Stadt indem Ihr die falschen Passagen aus dem Buch der Zauberformeln vorlest.", sourceObjectiveStatus = "unverified-source-field" }
quests[27800] = { id = 27800, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wieder in geheimer Mission unterwegs", description = "Die Kultisten schienen sich ihres Sieges sicher, obwohl wir viele von ihnen gefangen genommen hatten. Wir müssen mehr über das Ritual herausfinden, das der von Euch befragte Kultist erwähnt hat.\n\nDiese Rituale müssen das Herzstück der von ihnen geplanten Angriffe auf Orgrimmar sein.\n\nBenutzt die Robe von einem der festgenommenen Kultisten - die brauchen sie ohnehin nicht mehr. Zieht die Kleidung an, geht zurück zu dem Kultisten, der am Scheckeneberhof in Durotar positioniert ist und versucht, mehr über die Rituale und deren Bedeutung in den Plänen der Kultisten in Erfahrung zu bringen.", sourceObjective = "Zieht Eure Rekrutenrobe an, begebt Euch zum Scheckeneberhof und erhaltet das Buch der Zauberformeln von Aufseherin Jintak. Lest in der Nähe des Kultistenaltars im Buch der Zauberformeln, um das Ritual zu üben.", sourceObjectiveStatus = "unverified-source-field" }
quests[27801] = { id = 27801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eure Papiere bitte", description = "Meine Leute haben kürzlich eine Gruppe Kultisten dabei erwischt, wie sie in die Stadt schleichen wollten. Der Zustrom aus dem Umland in die Stadt ist zum Erliegen gekommen. Der Kriegshäuptling hat befohlen, dass alle Reisenden durchsucht werden müssen, bevor sie Orgrimmar betreten dürfen. Nehmt diese Abschrift seiner Proklamation, lest sie den vor der Stadt versammelten Mengen vor und helft anschließend den Wachen, diejenigen zu durchsuchen, die Einlass in die Stadt wünschen.", sourceObjective = "Begebt Euch zum Haupttor von Orgrimmar, verlest die Proklamation des Kriegshäuptlings und durchsucht 5 Bürger Orgrimmars. Behaltet verdächtige Gegenstände ein.", sourceObjectiveStatus = "unverified-source-field" }
quests[27802] = { id = 27802, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nehmt die Kultisten fest", description = "Die Notiz, die Ihr gefunden habt, kann nur eins bedeuten. Die Proklamation des Kriegshäuptlings kam zu spät; ihre Spitzel sind bereits in der Stadt zugange.\n\nDiese Notiz enthält Anweisungen und Treffpunkte für die Kultisten, sagt uns aber nichts darüber, was sie vorhaben. Unsere Feinde sind schlauer geworden. Es wird schwer werden, alle Kultisten in der Stadt aufzuspüren, aber wir müssen so viele dingfest machen, wie wir können. Benutzt diese Fesseln, um jeden Agenten festzunehmen, den Ihr finden könnt, und bringt sie anschließend zu Aufseher Gartok Zornfaust am Ring der Ehre im Tal der Ehre.", sourceObjective = "Benutzt die schweren Handfesseln, um 5 infiltrierende Kultisten festzunehmen und bringt sie dann zu Aufseher Gartok Zornfaust am Ring der Ehre in Orgrimmars Tal der Ehre. Wenn Ihr Eure Gefangenen dorthin gebracht habt, verhört einen der inhaftierten Kultisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27803] = { id = 27803, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine willkommene Entlastung", description = "Meine Jungs stellen Verteidigungslinien zu allen Seiten der Stadt und halten die Elementare zurück, die von allen Seiten aus dem aufgerissenen Boden herbeiströmen. Es sind gute Jungs und sie schlagen sich wacker, aber auch der hartnäckigste Zwerg wird einmal müde.\n\nSie haben sich in Schichten eingeteilt: eine Stunde Rast für jede Stunde an der Front. Das ist das Beste, was ich ihnen mit so wenig Leuten bieten kann.\n\nWenn Ihr helfen wollt, dann sucht Euch eine Seite aus und übernehmt eine Schicht. Verschafft meinen Jungs eine willkommene Verschnaufpause. Meldet Euch zurück, sobald Ihr eine ansehnliche Zahl Elementare getötet habt.", sourceObjective = "Tötet 8 unterworfene Feuerteufel.", completion = "Gute Arbeit, Junge. Es ist schön, ein zusätzliches Paar geschickter Hände zur Verfügung zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[27804] = { id = 27804, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für immer unser Zuhause", description = "Wir wurden schon weiter zurückgedrängt, als ich befürchtet hatte, aber ich habe nicht vor, unsere Häuser diesen Bastarden zu überlassen. Sie können sie vielleicht niederbrennen, plündern und auf ihre Überreste spucken, aber wir werden nicht aufgeben und sie zurückfordern.\n\nNatürlich hätte ich es lieber, wenn sie sie nicht niederbrennen. Ich habe die Jungs angewiesen, Eimer am Brunnen zu füllen und damit zu versuchen, das Feuer einzudämmen. Wenn Ihr ihnen aushelft, können sie Euch vielleicht Eimer zuwerfen, sodass Ihr nicht selbst laufen müsst.", sourceObjective = "Löscht 50 Feuer in Feuerbarts Patrouille.", completion = "Vielen Dank für Eure Hilfe. Jede noch so kleine Tat kann viel bewirken.\n\nWir werden weiter Wasser bringen, bis wir den Schattenhammer zurückgedrängt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[27805] = { id = 27805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Quäntchen Trost", description = "Ihr seid also das neue Gesicht, das Keegan aushelfen soll? Freut mich, Euch kennenzulernen. Vielleicht könnt Ihr den geplagten Wildhämmern, die hier Zuflucht gefunden haben, ein oder zwei Gefallen tun.\n\nWir mussten uns in größter Hast in diesem Gebäude verschanzen, sodass wir viele unserer Wertsachen in unseren zerstörten Häusern in der Nähe zurückließen. Würdet Ihr sie uns zurückbringen, wenn Ihr da draußen seid? Ihr würdet ein paar sehr bedrängten Seelen eine große Freude bereiten.", sourceObjective = "Findet Mearas Trockenrosen, Parlans Elfenbeinhammer und Aprikas Puppe.", progress = "Konntet Ihr ihre Wertsachen finden? Ich weiß, es scheint so banal, aber in Zeiten wie diesen können auch Kleinigkeiten so viel bewirken.", completion = "Ihr seid sehr großzügig. Vielen Dank.\n\nUnsere Welt versinkt dieser Tage in Dunkelheit. Wir sind sehr dankbar, dass Ihr uns ein kleines Licht gebracht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27806] = { id = 27806, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrenvolle Last", description = "Iain, mein Stellvertreter, hat den Leichnam eines unserer gefallenen Helden in die Kathedrale im Westen gebracht. Er ist dafür verantwortlich, aus den verstreuten Truppen ein neues Greifenreitergeschwader aufzustellen. Ich möchte, dass Ihr ihm helft.\n\nIch sollte Euch klar machen, wie eilig diese Aufgabe ist. Wir werden hier nicht bis in alle Ewigkeit standhalten können. Der Schattenhammer oder das Drachenmal werden uns früher oder später überwältigen. Ein aktives Greifenreitergeschwader ist vielleicht unsere einzige Chance, diesen Kampf zu überleben.", sourceObjective = "Sprecht mit Iain Feuerbart auf Feuerbarts Friedhof.", completion = "Grüße, {race}. Kommt Ihr in Keegans Auftrag?", sourceObjectiveStatus = "unverified-source-field" }
quests[27807] = { id = 27807, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klan Mullan", description = "Wenn wir wieder ein vollständiges Greifengeschwader zusammenbekommen wollen, müssen wir uns beeilen, die Überlebenden zusammenzutrommeln, bevor sie fortgehen oder aufgelesen werden. Ich habe einige Gruppen Reiter im Auge, die zusammengeblieben sind. Ich werde bald aufbrechen, um die Reiter von Donnermar und Moora zu suchen.\n\nAls ich die Mullans das letzte Mal sah, gingen sie nach Westen hinauf in den Schmelztiegel des Gemetzels. Geht und schaut, ob Ihr Duglas Mullan davon überzeugen könnt, sich Keegan anzuschließen - er sollte ihm einen Gefallen oder drei schulden.", sourceObjective = "Sprecht mit Duglas Mullan am Schmelztiegel des Gemetzels.", completion = "Iain hat Euch geschickt?\n\nIhr seht mir nicht wie ein Feuerbart aus. Warum sollte ich mir anhören, was Ihr zu sagen habt?", sourceObjectiveStatus = "unverified-source-field" }
quests[27808] = { id = 27808, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stur wie ein Doyle", description = "Die Reiter von Doyle wurden zuletzt gesehen, als sie auf die Bäume im Süden an der Grenze zum Obsidianwald zurannten. Sie sind ein sturer Haufen und es wird einiger Überredungskunst bedürfen, bevor sie sich uns anschließen.\n\nAm besten erzählt Ihr Keeland Doyle, dass Cailin Langhans bei uns in der Stadt Schutz gesucht hat. Keeland hat eine gewaltige Schwäche für sie und das könnte reichen, ihn davon zu überzeugen, all seine Jungs mitzubringen.", sourceObjective = "Sprecht mit Keeland Doyle im Hochlandwald.", completion = "Anscheinend haben die Doyles am meisten unter den Angriffen der Zwielichtdrachen gelitten.\n\nEs ist offensichtlich, dass sie bis zum Ende gekämpft haben: Alle Fußspuren der Reiter befinden sich in umittelbarer Nähe ihrer Greife. Es ist unwahrscheinlich, dass es Überlebende gegeben hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[27809] = { id = 27809, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuerbart brüllt", description = "Ihr müsst für mich noch zu Mackay und seinen Leuten gehen. Sie sind auf der anderen Seite des Verschlingenden Risses im Kriegslager Gorshak.\n\nNiemand vom Drachenmalklan hat den ersten Ansturm überlebt und Mackay will nun alles, was er kann aus ihrem Lager plündern, um unseren Kampf zu versorgen. Es sollte nicht schwer sein, sie zu überzeugen, aber wahrscheinlich wollen sie Hilfe, um da oben alles zu Ende zu bringen, bevor sie sich auf den Weg zu Keegan machen.\n\nTretet sie gewaltig von dem alten Iain in den Hintern, wenn es sein muss.", sourceObjective = "Sprecht mit Mackay Feuerbart am Kriegslager Gorshak.", completion = "Ist es schon so weit, ja? Dann helft uns, hier fertig zu werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27810] = { id = 27810, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfgeist", description = "Keegan will, dass die Mullans an ihrer Seite fliegen, hm? Wenn es einen Zwerg gibt, für den ich fliegen würde, dann für ihn. Allerdings weiß ich nicht, warum er 'nen Außenstehenden schickt, um mich anzuwerben. Aus meiner Sicht ist das nich' wirklich höflich.\n\nIch schätze mal, dass Ihr keine 20 Sekunden gegen einen meiner Jungs durchhaltet - weder in der Bar noch auf dem Schlachtfeld. Beweist mir das Gegenteil. Besiegt einen von ihnen im Kampf und dann denke ich drüber nach, ob ich mit dem alten Keegan fliege.", sourceObjective = "Fordert einen der Greifenreiter der Mullans heraus und besiegt ihn.", progress = "Nee, ich werd' nicht gegen Euch kämpfen. Geht da rein und fordert einen meiner Jungs heraus, wenn Ihr den Mumm dazu habt.", completion = "Genau so! Gar nicht mal schlecht. Ihr habt ja tatsächlich etwas Kampfkraft in Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[27811] = { id = 27811, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Geruch der Schlacht", description = "Lasst Euch nichts von Duglas vormachen, den Mullans juckt es in den Fingern, wieder zu fliegen - und wenn wir das für jemanden tun, dann für Feuerbart.\n\nWir haben unsere Greifen im Hochlandwald im Süden gelassen, damit sie dort jagen können und ein wenig Abstand von den Kampfgeräuschen bekommen. Sie hatten sich ein wenig Erholung verdient.\n\nWenn Ihr uns bald wieder in der Luft sehen wollt, seid Ihr gut beraten uns zu helfen diese Greifen wieder hereinzuholen.\n\nNehmt dieses Stück verkohlte Hochlandbirke. Wir benutzen sie während der Ausbildung - sobald sie sie riechen, kommen sie wieder zurück zu uns.", sourceObjective = "Findet 8 Greifen der Mullans und bringt sie zurück zu ihren Greifenreitern.", completion = "Gut gemacht. Ich habe immer das Gefühl, dass ein Teil von mir fehlt, wenn mein Greif nicht in der Nähe ist. Ich kann ja nicht für Duglas und den Rest seines Klans sprechen, aber ich werde bei Feuerbarts Ruf bereit sein, loszureiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27812] = { id = 27812, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Loyalität des Klan Mullan", description = "Ihr habt Euren Standpunkt klargemacht. Keegan kann auf uns zählen. Wir treffen uns mit ihnen in der Stadt, sobald die Jungs alle versammelt sind.\n\nDafür, dass Ihr kein Wildhammer seid, seid Ihr ganz schön zäh. Offenbar gibt's da, wo Ihr herkommt, gute Weidegründe.\n\nAber ich hab' Euch noch nich' trinken sehen. Das ist der wahre Test.", sourceObjective = "Kehrt mit den Neuigkeiten über den Klan Mullan zu Iain Feuerbart auf Feuerbarts Friedhof zurück.", completion = "Ihr habt die Mullans. Gute Neuigkeiten! Die sind im Kampf mehr wert, als ihr Gewicht in Gold - und die sind nich' grad dürr.", sourceObjectiveStatus = "unverified-source-field" }
quests[27813] = { id = 27813, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod würdig des Drachenmals", description = "Der Schattenhammer hat die Stadt ausgeplündert und die meisten der Angehörigen des Drachenmalklans, die darin lebten, getötet. Einige haben allerdings überlebt und die sind nich' grade erbaut darüber, dass wir uns Freiheiten mit ihren Vorräten herausnehmen.\n\nNicht, dass das von Bedeutung wäre.\n\nNaja, ich bin nich' grad erbaut darüber, dass sie meine Jungs angreifen. Tötet sie, jagt sie weg - is' mir egal, werdet sie nur irgendwie los.", sourceObjective = "Besiegt 6 Nachzügler des Drachenmals.", completion = "So ist es schon besser. Lasst uns die letzten Vorräte einsammeln und dann ab zu Keegan.", sourceObjectiveStatus = "unverified-source-field" }
quests[27814] = { id = 27814, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles, was wir kriegen können", description = "Zurückbleiben und mehr Waffen schmieden? Pff! Ein Schmiedehammer hat sich nie vor einer Schlacht gedrückt! Wer braucht schon eine sichere Umgebung, um Waffen zu schmieden? Außerdem gibt es da draußen tonnenweise Rohstoffe. Die Waffen des Drachenmals sind wertlos, aber man kann sie als Grundlage für echte Waffen nutzen. Bringt mir acht Waffen des Drachenmals, damit ich mit meiner Tochter echte Waffen aus ihnen schmieden kann.", sourceObjective = "Bringt 8 Waffen des Drachenmals zu Brom Schmiedehammer beim Kriegslager Gorshak.", progress = "Wie viele Waffen habt Ihr bisher?", completion = "Gut gemacht, Alter. Vielen Dank; ein bisschen Gold für Eure Mühen gibt es auch.", sourceObjectiveStatus = "unverified-source-field" }
quests[27815] = { id = 27815, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etwas für die Jungs", description = "Ihr habt das Lager gesäubert und den Laufburschen für Schmiedehammer gespielt? Nicht schlecht, wenn man bedenkt, dass Ihr nur <'n kleiner/'ne kleine:c> {class} seid. Bringt die hier zu Iain auf Feuerbarts Friedhof. Er sollte Euch für die gute Arbeit belohnen.", sourceObjective = "Bringt Schmiedehammers Waffen zu Iain Feuerbart auf Feuerbarts Friedhof.", progress = "Was haben wir denn hier?", completion = "Ha! Offenbar war ihr Beutezug richtig erfolgreich. Ich muss dem alten Schmiedehammer wohl eine Runde ausgeben, wenn wir mit dem Durcheinander hier fertig sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[27816] = { id = 27816, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Persönliche Bitte", description = "Schade um die Doyles. Es grenzt allerdings schon an ein Wunder, wie viele von uns es herausgeschafft haben - insofern bin ich nicht sonderlich überrascht.\n\nDiese Rüpel in Donnermar sind Feiglinge. Sogar nachdem sie wussten, dass die Bitte von Keegan kam, wollten sie keinen Fuß aus ihrer Stadt setzen. Ich hab' allerdings die Moores an Bord geholt, also haben wir drei Klans.\n\nKeegan wollte nach Eurer Rückkehr mit Euch persönlich sprechen. Geht und sucht ihn in der Stadt auf.", sourceObjective = "Sprecht mit Keegan Feuerbart an Feuerbarts Patrouille.", completion = "Offensichtlich hattet Ihr Glück mit dem Zurückbringen der Reiter. Auch der Zeitpunkt war passend - wir haben gerade die Elementare zurückgeschlagen, also sollten wir genug Bewegungsfreiheit haben, um sofort einen Angriff zu führen.\n\nDanke, {name}. Ihr seid ein guter {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27817] = { id = 27817, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Hammer fallenlassen", description = "Dank Euch und Iain haben wir genug Reiter zusammen, um den Kampf wieder gegen den Schattenhammer führen zu können.\n\nWir sind darin ausgebildet, während des Flugs zu kämpfen, aber ein zweiter Reiter, der sich um die Sturmhammer kümmert, ist noch wirkungsvoller. Ich dachte, dass Euch diese Ehre gefallen könnte.\n\nSucht Euch einen Greifen aus und schließt Euch dem Kampf an. Ihr solltet Euch allerdings beeilen - wir wollen vor Ablauf einer Stunde alles, was dem Schattenhammer angehört, von den schwebenden Felsen beseitigen.", sourceObjective = "Tötet 12 Zwielichtsturmbändiger und Servias Windterror. Benutzt dazu einen der Greifen von Feuerbarts Patrouille.", completion = "Genau so macht man das, mein Freund!\n\nJetzt, da wir wieder ein echtes Greifengeschwader haben, können wir den Kampf auf den Rest des Schattenhammers ausweiten. Ihr seid jederzeit willkommen, mit uns zu fliegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27818] = { id = 27818, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glitschige Zeichen", description = "Ich habe mich hier schon niedergelassen, bevor Kraulsumpf gegründet wurde, um meine Tränke zu brauen und etwas Frieden zu finden. Ich kenne diesen Sumpf wie meine Westentasche.\n\nDie Fauna hat sich hier in letzter Zeit verändert. Diese geflügelten Schlangen, die Ihr vielleicht im Stagalsumpf gesehen habt, sind Windnattern, und die hat es hier schon seit Urzeiten nicht mehr gegeben.\n\nSie geben allerdings hervorragende Zutaten ab, wenn es die sind, für die ich sie halte. Seid so gut und bringt mir ein paar ihrer Herzen, okay?", sourceObjective = "Sammelt 5 intakte Stagalsumpfnatternherzen.", progress = "Seid Euch nicht so zimperlich.", completion = "Na werfen wir doch mal einen Blick drauf...\n\nMmm, oje. Ich hatte befürchtet, dass es sich darum handelt. Sie sind zwar noch brauchbar, aber es ist kein schöner Gedanke, solche Biester in der Nachbarschaft zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[27819] = { id = 27819, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "TEST - RVM" }
quests[27821] = { id = 27821, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orcs und Menschen", description = "Während der Krieg die ganze Welt überzieht, ist das Letzte, was wir brauchen, eine Hordensiedlung gleich nebenan. Das Rotkammgebirge, der Dämmerwald, sogar Elwynn selbst: alle sind nur einen Tagesmarsch von hier entfernt.\n\nWir haben den ersten Angriff gestartet, und ich habe nicht vor, der Horde eine Atempause zu lassen. Betrachtet Euch als im Einsatz. Schnappt Euch eine Waffe, stoßt zum Rest der Truppen draußen im Blutsumpf, und fangt an, Orcs zu töten.\n\nMeldet Euch bei mir zurück, nachdem Ihr etwas Schaden angerichtet habt. Ich will Euch lebend zurück... und das ist ein Befehl. Weggetreten!", sourceObjective = "Tötet 8 Krieger von Steinard.", completion = "Mehr Schmutzflecken als Blutflecken... das sehe ich gern. Sieht so aus, als hättet Ihr das Zeug für den Krieg, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27822] = { id = 27822, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trampel", description = "Ich will, dass der Sieg vollkommen abgesichert wird. Es reicht nicht, genügend Material zu haben, wir müssen sicherstellen, dass der Feind nichts hat.\n\nSteinards Streitkräfte verlassen sich auf das Holz, das aus den umliegenden Wäldern gesammelt wird. Die Orcpeons, die das Holz fällen, mögen keine Krieger sein, aber sie kennen nur Hass auf die Menschen.\n\nZeigt keine Gnade. Ich will, dass diese Peons getötet werden und dass der Holznachschub nach Steinard vollkommen abgeschnitten wird.", sourceObjective = "Tötet 5 Steinardpeons.", completion = "Während Eurer Abwesenheit gab es Schläge gegen unsere eigenen Holznachschublinien. Dadurch sollten wir in etwa die gleichen Mengen gesammelt haben.\n\nGute Arbeit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27823] = { id = 27823, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auch ein Zwerg hat Bedürfnisse", description = "Versteht mich nicht falsch, ich weiß eine gute Ausgrabung genauso zu schätzen, wie jeder andere Zwerg. Es ist nur so… Nun, wir graben und graben und bekommen kaum einen Schluck zu trinken. Manchmal denke ich, ich sollte meine Schaufel einfach an den Nagel hängen und zurück nach Eisenschmiede gehen.\n\nAber nicht heute. Ein bisschen Grabungsstimmung steckt noch in mir.\n\nDiese Dunkeleisenzwerge an Hammerzehs Grabungsstätte, direkt nördlich von hier, stellen ein starkes und feines Bier her, mitten in der Wüste. Meint Ihr, Ihr könntet mir ein wenig davon besorgen?", sourceObjective = "Besorgt 15 Krüge Schattenbräu.", progress = "<Sigrun leckt sich erwartungsvoll die Lippen.>", completion = "<Sigrun kippt sofort einen staubigen Krug Schattenbräu.>\n\nHui, das Zeug ist stark! Ich wusste, dass sie Bier haben, aber ich hätte nie gedacht, dass sie Schattenbräu haben! Das ist mein allerliebstes Schattenbier!", sourceObjectiveStatus = "unverified-source-field" }
quests[27824] = { id = 27824, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das gute Zeug", description = "Ich habe einen kleinen Vorschlag für Euch, wenn Ihr interessiert seid.\n\nDiese Dunkeleisen waren hier, bevor Durdin und seine Leute angekommen sind. Das bedeutet, dass die Dunkeleisen die ersten waren, die hineingekommen sind, als sich diese Titanenruinen geöffnet haben, und sie haben sicher das ganze gute Zeug mitgehen lassen. Ich bin sicher, dass sie diese Schätze immer noch in der Festung Angor nordwestlich von hier eingeschlossen haben.\n\nIhr habt Eure Fähigkeit, Zwergen eins auf den Deckel zu geben, mehr als bewiesen. Geht in diese Festung und prügelt Euch zu den Titanenschätzen durch.\n\nIch würde ja mitkommen, aber ich bin betrunken.", sourceObjective = "Sucht im untersten Stockwerk der Festung Angor nach Schätzen.", progress = "So früh schon zurück?", completion = "Na das nenne ich doch einen Schatz! Ich habe mir schon langsam Sorgen gemacht, dass das hier gar keine Titanenruinen sind!\n\nDas werde ich Durdin zeigen. Nochmals danke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27825] = { id = 27825, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überleben der Dicksten", description = "Unsere Vorräte gehen zur Neige, <Fremder/Fremde>. Solange die schwarzen Drachen unsere Jagdgründe mit Zerstörung überziehen, haben wir keine Chance, an Nahrung zu gelangen.\n\nDie Oger im Südwesten jedoch haben genau, was wir brauchen. In ihrer Grotte solltet Ihr ausreichend Nahrung und Handwerkswaren finden.\n\nSie könnten sich aber mit Euch darum schlagen wollen. Seid also vorsichtig.", sourceObjective = "Erlangt 6 Fleischstücke der Staubspeier und 10 Lagen Seide der Staubspeier.", progress = "Willkommen zurück.", completion = "Ich nehme an, die Oger waren für Euch keine zu große Hürde. Hier - ein paar Münzen für Eure Mühen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27826] = { id = 27826, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Drachenschlund", description = "<Dr. Blam starrt das Ei in ehrfürchtiger Stille an, blinzelt ein paar Mal und schaut dann zu Euch hoch.>\n\nH... Habt Ihr das gesehen? Unfassbar! Meine Titanendingsidee hat funktioniert! Mit Eurer Hilfe, natürlich.\n\nNun, ich möchte das hier zu Rhea zurückbringen. Sie befindet sich nicht länger an der Lethlorklamm. Sie hat es mit Bravour geschafft, ihre Tarnung auffliegen zu lassen, als sie sich vor all diesen Welpen in ihre wirkliche Form verwandelte. Sie ist jetzt im Westen und hält sich in einem Allianzcamp mit Namen Drachenschlund auf.\n\nSie wird dort auf Euch warten. Und auf das Ei.", sourceObjective = "Bringt das geläuterte Schwarzdrachenei zu Rhea in Drachenschlund im Ödland zurück.", progress = "Ihr habt eine ziemlich wertvolle Ladung bei Euch, {name}.", completion = "Ich werde Euch das Ei jetzt abnehmen. Wir müssen das Ei ausbrüten... und schnell verstecken. Es gibt eine Menge wütender Drachen, die hiernach suchen.\n\nÜbrigens - schön, Euch wieder zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27827] = { id = 27827, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Flinke, der Starke und der Schreckliche", description = "In meiner Eile, aus der Lethlorklamm zu entkommen, habe ich ein paar Dinge vergessen: Nyxondra. Sie ist frei und hat beim schwarzen Drachenschwarm Alarm geschlagen. Der halbe Schwarm ist hier im westlichen Ödland auf der Suche nach diesem Ei.\n\nIch werde das Ei verstecken. Ihr kümmert Euch um diese lästigen Drachen. Ihr werdet Hilfe bekommen.\n\nRedet mit Eric, drüben auf der anderen Seite des Lagers. Er und seine Brüder werden Euch begleiten.", sourceObjective = "Sprecht mit Eric \"Dem Flinken\" beim Drachenschlund im Ödland.", completion = "Seid Ihr der {race}, auf den wir gewartet haben? Es wurde auch Zeit, dass Ihr kommt. Meine Beine könnten ein bisschen Bewegung vertragen.\n\nNa los, Jungs! Lasst uns ein paar schwarze Drachen jagen!", sourceObjectiveStatus = "unverified-source-field" }
quests[27828] = { id = 27828, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eric, der nützliche Zwerg", description = "Bevor wir allzu übermütig werden, was das Drachentöten angeht, möchte ich Euch ein bisschen über die Art, wie ich kämpfe, erzählen.\n\nMan nennt mich \"der Flinke\" und zwar aus folgendem Grund: Ich renne geradewegs auf Eure Feinde los - natürlich mit dem Helm vorneweg - und betäube sie für ein paar Sekunden. Außerdem werde ich einige Tränke bei mir tragen, falls es einmal eng werden sollte.\n\nWarum üben wir nicht, gemeinsam zu kämpfen? Geht hinaus aufs Feld und stellt meine Fähigkeiten auf die Probe.", sourceObjective = "Benutzt 'Erics Sturmangriff' und 'Erics Taschentrank'.", progress = "Wir sind noch nicht fertig, {name}.", completion = "Ich bin nicht das, was man gemeinhin \"sehr stark\" oder \"kampfgestählt\" nennt, aber ich bekomme das auch so hin.\n\nIch freue mich darauf, mit Euch gemeinsam zu kämpfen. Ein schicker {class} wie Ihr hat noch nie an meiner Seite gekämpft.", sourceObjectiveStatus = "unverified-source-field" }
quests[27829] = { id = 27829, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zorn eines Drachenschwarms", description = "Hallo, {name}. Mir scheint, Ihr vier hattet genug Zeit, Euch anzufreunden.\n\nIch habe eine erste Aufgabe für Euch. Kalaran, ein uralter schwarzer Drache mit beträchtlicher Macht, hat sich der Jagd auf das von uns beschützte Ei angeschlossen. Wir müssen ihn aufhalten, bevor er ihm zu nahe kommt.\n\nIhr findet ihn und seine Diener im Staubbecken, nordöstlich vom Drachenschlund. Sucht und besiegt ihn. Wahrscheinlich werdet Ihr die Hilfe Eurer neuen Zwergenverbündeten brauchen.", sourceObjective = "Tötet Kalaran den Vernichter und 4 Soldaten des dunklen Schwarms.", sourceObjectiveStatus = "unverified-source-field" }
quests[27830] = { id = 27830, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Jagd geht weiter", description = "Der schwarze Drachenschwarm meint es ernst. Wie es scheint hat er einen Großteil von Neu-Kargath, der Siedlung der Horde nordwestlich des Drachenschlunds, an sich gerissen. Ihre Truppen stehen unter dem Befehl von General Jirakka und seinem Champion Moldarr. Sie müssen aufgehalten werden.\n\nWir Drachen mischen uns nicht in die kindischen Streitereien zwischen Horde und Allianz ein, aber mir ist bewusst, welches Risiko Ihr eingeht, wenn Ihr Neu-Kargath betretet. Bitte, Helden... Seid vorsichtig.", sourceObjective = "Besiegt General Jirakka, Moldarr und 6 Mitglieder der Drachenbrut des dunklen Schwarms.", sourceObjectiveStatus = "unverified-source-field" }
quests[27831] = { id = 27831, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Leid und der Zorn", description = "Am meisten bereue ich, wie wir... nein, wie ich Nyxondra behandelt habe. Ich habe sie gezwungen, Eier zu legen, und dann mit ihnen experimentiert. Immer und immer und immer wieder.\n\nObwohl ich selbst Mutter bin, kann ich mir ihr Leid kaum vorstellen.\n\nNein... Ich darf nicht schwach werden. Unsere Arbeit dient immerhin dem Wohl der zukünftigen Generationen der schwarzen Drachen. Ihr Opfer war notwendig.\n\nNun umkreist sie die Ruinen von Kargath, nordwestlich von Neu-Kargath, wahnsinnig vor Zorn. Bitte, Helden... erlöst sie von ihrem Elend.", sourceObjective = "Erschlagt Nyxondra und 12 von Nyxondras Brutlingen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27832] = { id = 27832, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Versteckte Gelege", description = "Jetzt, da die meisten schwarzen Drachen aus dem Ödland abgezogen sind, können wir das Ei wieder sicher transportieren. Ihr findet mich auf einer kleinen Hochebene nördlich von Neu-Kargath.\n\nSucht mich dort auf.", sourceObjective = "Sprecht mit Rhea im Versteckten Gelege im Ödland.", completion = "Das Ei muss immer in Bewegung bleiben. Wir sind hier nicht mehr sicher.\n\nSogar in seinem Wahnsinn kennt Todesschwinge alle versteckten Orte dieser Welt. Das Ei kann nicht an einem Ort bleiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[27833] = { id = 27833, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tonnenschwere Starrköpfe", description = "Ich würde sagen, wir haben ein Drachenproblem. Aber es sieht aus, als wären sie eher an Neu-Kargath interessiert als an unserem kleinen Lager. Trotzdem habe ich unsere besten Männer darauf angesetzt, die Drachen zurückzuhalten.\n\nEin Problem, das jedoch ungelöst bleibt, ist das Ogerlager im Südwesten. Eine kleine Armee von Kämpfern scheint vor ihrem Unterschlupf aufgetaucht zu sein.\n\nWir können nicht einfach herumsitzen und darauf warten, dass sie uns über die Flanke angreifen. Dünnt ihre Reihen aus, bevor sie es mit unseren tun.", sourceObjective = "Tötet 12 Kämpfer der Staubspeier. Ihr könnt Raufer oder Schamanen der Staubspeier töten.", completion = "Ich danke Euch, {race}. Allerdings befürchte ich, dass ich Euch außer einer aufrichtigen Runde Applaus nicht viel geben kann.\n\n\n\nOh, das hier habe ich doch. Hier, nehmt Euch, was Ihr wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27834] = { id = 27834, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baelog, die Glaskanone", description = "Bevor ich anfange, Pfeile auf diese Drachen regnen zu lassen, stelle ich mich erstmal vor.\n\nIch bin Baelog, der Mann fürs Grobe in dieser Gruppe. Mein Schwert beißt wie ein Krokilisk und meine Pfeile singen wie Banshees. Dafür erschöpfe ich aber schnell und kann auch nicht so viel einstecken wie meine Brüder.\n\nEin Wort von Euch genügt, und ich kann einen gezielten Pfeil mitten ins Herz des Ziels schicken. Ich kann auch meine Brüder anfeuern und sie sich in einen Kampfrausch steigern lassen.\n\nWarum ziehen wir nicht zusammen in die Schlacht?", sourceObjective = "Benutzt 'Baelogs Valhallaschuss' und 'Baelogs Kriegsschrei'.", completion = "Ich glaube, Ihr seid so weit, {name}. Ihr habt den Dreh raus.", sourceObjectiveStatus = "unverified-source-field" }
quests[27835] = { id = 27835, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Olaf, der dicke Brocken", description = "Es ist Euch vielleicht nicht aufgefallen, aber für einen Zwerg bin ich recht groß.\n\nIch stelle sicher, dass meine beiden Brüder hier nicht in zu große Schwierigkeiten geraten. Sie sind klein und haben nicht so einen großen Schild wie ich. Ich bin groß und kann ein paar Schläge von Monstern gut wegstecken! Außerdem kann ich es meistens schaffen, dass sie nur meinen Schild treffen!\n\nIch kann auch Euch beschützen. Kommt, gehen wir ein bisschen trainieren. Ich sorge dafür, dass die Gegner mich angreifen, nicht Euch.", sourceObjective = "Benutzt 'Olafs Schildwall' und 'Olafs mächtigen Ruf'.", completion = "Seht Ihr? Kein Grund zur Sorge, wenn Olaf da ist. Sagt mir nur Bescheid und ich beschütze Euch vor den Monstern.", sourceObjectiveStatus = "unverified-source-field" }
quests[27836] = { id = 27836, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ausbreitung eindämmen", description = "Es wird nicht reichen, die widerlichen Kreaturen, die den Fluss verseuchen, zu töten, {name}.\n\nEine neue Generation dieser Monstrositäten droht bereits in unseren heiligen Wassern ausgebrütet zu werden.\n\nSucht ihre unreinen Eier und zerstört sie.", sourceObjective = "Zerstört 6 Gleitereier.", completion = "Ich danke Euch, {name}. Dies wird unsere prophetischen Visionen so viel klarer werden lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27837] = { id = 27837, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungebetene Besucher im Wasser", description = "Kurz, nachdem Uldums Schutzbarriere fiel, wurde der Vir'naal von einer furchtbaren Verderbnis befallen.\n\nOb diese mit böser Absicht oder versehentlich hierher gebracht wurde, spielt keine große Rolle.\n\nDas Ergebnis ist das gleiche. Je trüber der Fluss wird, umso mehr trübt sich auch unsere Fähigkeit, vorauszusehen, was die Zukunft uns bringt.\n\nSchaut hinaus, {class}. Diesen widerwärtigen Kreaturen war es nie bestimmt, in den makellosen Wassern unseres Flusses zu leben. \n\nTötet sie, damit der Fluss uns wieder Visionen ermöglicht.", sourceObjective = "Tötet 8 Stillwassergleiter.", completion = "Ja, {name}. Ich spüre bereits, wie die Beeinträchtigung des Flusses schwindet.\n\nDennoch spüre ich, dass die Quelle dieser Verderbnis weiterhin lauert.", sourceObjectiveStatus = "unverified-source-field" }
quests[27838] = { id = 27838, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wurzel des Übels", description = "Ihr mögt Euch den Symptomen unseres Problems angenommen haben, {name}. Aber ich habe diese widerwärtigen Biester beobachtet und sie legen ihre Eier nicht hier.\n\nDie Strömung trägt ihre Eier zum Damm, aber was immer sie legt, befindet sich am Oberlauf des Flusses.\n\nGeht nach Nordosten zur Hauptquelle des Flusses und beseitigt die Wurzel des Übels.", sourceObjective = "Geht zur nordöstlichen Quelle des Vir'naal und tötet Schuppenmutter Hevna.", completion = "Ja. Die Wasser werden klarer.\n\nIch bin sicher, dass wir eine Vision haben werden, bevor der Hohe Rat zusammentrifft.\n\nSeid gewarnt, {race}. Meine Stimme wird sich nach dem richten, was ich sehe.\n\nIhr habt uns sicherlich heute hier sehr geholfen, aber wenn die Vision mir rät, mich gegen den Krieg auszusprechen, dann werde ich meine Stimme auch so abgeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[27839] = { id = 27839, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uralte Waffen", description = "Obwohl wir uns noch nicht offiziell im Krieg befinden, zögern die Neferset nicht, alle, die unbefugt ihr Gebiet betreten, ins Gefängnis zu werfen oder zu töten.\n\nKönig Phaoris weigert sich, darauf zu antworten, auch wenn sie unser Land dazu benutzen, gestohlene Relikte aus den Grabstätten unserer Ahnen herauszuschmuggeln.\n\nMeine Späher berichten mir, dass die Neferset in Kürze südlich von hier eine größere Ladung geplünderter Waffen in Bewegung setzen wollen.\n\nIch habe die Arbeiter, die Ihr angeworben habt, angewiesen, Euch zu helfen. Ruft sie mit diesem Horn, wenn Ihr die Schmuggler findet und holt die Waffen.", sourceObjective = "Besorgt die uralten Waffen der Tol'vir.", progress = "Ihr seid zurückgekehrt, {name}. Wie ist die Operation verlaufen?", completion = "Das kommt gerade recht. Ich werde diese Waffen an meine besten Leute und die Arbeiter, die Ihr angeworben habt, verteilen.\n\nIch habe das Gefühl, sie werden ebenso viel Mut beweisen, wie meine bestens ausgebildeten Hauptleute.", sourceObjectiveStatus = "unverified-source-field" }
quests[27840] = { id = 27840, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Draenethystkristalle", description = "Die Verlorenen, die in der Zuflucht der Verirrten leben, sehen aus wie wir, aber sie sind Monster, die durch die Strapazen unserer Reise nach Azeroth den Verstand verloren haben. Einst waren sie unsere Brüder, aber jetzt leben sie in der Zuflucht der Verirrten im Westen. Dort fangen oder töten sie jeden, der ihnen nahe kommt.\n\nAußerdem haben sie uns etwas Heiliges gestohlen - Draenethystkristalle.\n\nWir haben nicht genug Leute, um die Zuflucht der Verirrten zu betreten und uns das gestohlene Draenethyst aus ihren Hütten und von ihren Lagerfeuern zurückzuholen. Doch ohne diese Kristalle... könnte es sein, dass auch wir uns verirren.", sourceObjective = "Sammelt 5 Draenethystkristalle in der Zuflucht der Verirrten auf.", progress = "Habt Ihr die Kristalle?", completion = "Danke, {name}. Wir stehen in Eurer Schuld.", sourceObjectiveStatus = "unverified-source-field" }
quests[27841] = { id = 27841, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die dankbaren Toten", description = "Es tut so gut, wieder bei Freunden und Familie zu sein, auch wenn ich es vielleicht etwas übertrieben habe... Ich habe schon alles gegessen, was sie für mich zubereitet haben!\n\nKann ich Euch um noch ein wenig mehr von dieser köstlichen Totenspeise bitten? Ich wäre Euch sehr dankbar...\n\nIch glaube, Chapman dort drüben verkauft das Rezept.", sourceObjective = "Besorgt Euch ein wenig Totenspeise und gebt sie dem heiteren Goblingeist auf dem Friedhof von Orgrimmar.\n\nBenutzt eine orangefarbene Ringelblume, um den ansonsten unsichtbaren Geist zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27842] = { id = 27842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erst der Anfang", description = "Ich ich sehne mich nach den Zeiten, als Legionen mächtiger Oger von der Horde in die Schlacht geführt wurden und die lächerliche Allianz sich vor Angst in die Hosen gemacht hat. Vielleicht kehren diese Tage ja wieder, bevor die Ahnen mich zu sich rufen.\n\nDerzeit jedoch ist dies noch nicht der Fall. Ein Ogermagier, Glubtok, hat sich mit der verabscheuungswürdigen Bruderschaft der Defias eingelassen und spielt für sie den Vorarbeiter für ihre Bergbauoperationen. Dieser erbärmliche Narr! Beendet sein Leben für mich und zum Ruhme der Horde!", sourceObjective = "Tötet Glubtok.", completion = "Lasst Euch nicht aus der Ruhe bringen, {name}. Ich bin ganz in der Nähe und warte in den Schatten. Ihr habt Eure Sache gut gemacht.\n\nIhr müsst Eure Mission hier fortsetzen - Ich bin zu wertvoll, um mein Leben gegen Kleinkriminelle wie diese aufs Spiel zu setzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27843] = { id = 27843, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstärkung abgelehnt", description = "Einfach nur Oger zu töten wird nicht ausreichen. Die Oger selbst werden viel zu schnell aufs Schlachtfeld gerufen.\n\nIch möchte, dass Ihr weit hinter die feindlichen Linien geht und ihre Beschwörer ausschaltet. Diese Orcs verwenden Hexenmeister, um Verstärkung zu rufen.\n\nHackt diese Hexenmeister in Stücke, und die Portale sollten in greifbarer Nähe sein. Es gibt nicht zu viele von ihnen... Ein schneller, präziser Schlag sollte den Feind schwächen.", sourceObjective = "Tötet 3 Hexenmeister von Steinard.", completion = "Erneut gute Arbeit. Noch ein paar solcher Vorstöße und die Schlacht wird uns gehören.", sourceObjectiveStatus = "unverified-source-field" }
quests[27844] = { id = 27844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verräter!!!", description = "Die Goblins, die mit den Defias zusammenarbeiten, sind offiziell Verräter am Bilgewasserkartell, der Zerschmetterten Hand und der Horde selbst!\n\nIch wurde noch nicht bei der Zerschmetterten Hand initiiert, also gilt meine Treue vor allem meinem Volk. Helix Ritzelbrecher hat offensichtlich keine Zeit für solche Bündnisse und baut gerade einen Mast für die Moloch der Defias. Würdet Ihr Helix im Namen von Fräulein Fiasko und mir \"beseitigen\"?", sourceObjective = "Besiegt Helix Ritzelbrecher.", completion = "Meine Auftraggeber haben für Verräter nichts übrig.\n\nIm Gegensatz dazu sind sie für ihre ausgesprochene Freundlichkeit unseren treu Ergebenen gegenüber bekannt. Ihr verdient es, belohnt zu werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[27845] = { id = 27845, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Markiert die Gefallenen", description = "Wir haben mehr Leben genommen, als wir verloren haben, aber wir haben immer noch zu viele verloren. Zu viele Tapfere haben da draußen ihr Leben für die Allianz gegeben. Ich will, dass sie die verdienten Ehren erhalten, egal, wie wild diese Schlacht auch wird.\n\nNehmt diese Flaggen mit Euch und platziert je eine auf jedem gefallenen Soldaten, den Ihr seht. Die Schutzzauber, die ihnen anhaften, werden nicht vor mutwilliger Entweihung schützen, aber sie sind besser als nichts. Ich werde so auch besser aus der Entfernung einschätzen können, wie viele wir verloren haben.", sourceObjective = "Benutzt die Banner der Gefallenen, um 7 gefallene Fußsoldaten der Sumpftidenwacht zu markieren.", completion = "Danke, {name}. Diese Soldaten verdienen Besseres, als mit dem Gesicht im Dreck liegengelassen zu werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27846] = { id = 27846, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die dankbaren Toten", description = "Es tut so gut, wieder bei Freunden und Familie zu sein, auch wenn ich es vielleicht etwas übertrieben habe... Ich habe schon alles gegessen, was sie für mich zubereitet haben!\n\nKann ich Euch um noch ein wenig mehr von dieser köstlichen Totenspeise bitten? Ich wäre Euch sehr dankbar...\n\nIch glaube, Chapman dort drüben verkauft das Rezept.", sourceObjective = "Besorgt Euch ein wenig Totenspeise und gebt sie dem heiteren Worgengeist auf dem Friedhof von Darnassus.\n\nBenutzt eine orangefarbene Ringelblume, um den ansonsten unsichtbaren Geist zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27847] = { id = 27847, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch nicht ganz fertig", description = "Diese Prototypen werden die Kriegsführung der Horde revolutionieren, wenn ich sie erstmal perfektioniert habe! Das Problem ist nur, dass ihre Energievorräte nicht für große Chassis ausreichen, oder um komplizierte Kampfmanöver durchzuführen, obwohl beides sehr wünschenswert wäre.\n\nDie Defias haben - mithilfe einiger Goblinverräter wie Helix - beinahe den Feindschnitter 5000 fertiggestellt, einen riesigen Golem, der sogar funktionieren wird!\n\nDas darf auf keinen Fall publik werden, oder ich verliere Kunden!", sourceObjective = "Zerstört den Feindschnitter 5000.", completion = "Großartig! Nun muss ich nur noch mein Werk vollenden und meine Chaosernter werden... Chaos... auf jedem Schlachtfeld der Horde säen!\n\nUnd es wird keine Emporkömmlinge der Defias geben, die meine Profite stehlen!", sourceObjectiveStatus = "unverified-source-field" }
quests[27848] = { id = 27848, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gute Absichten... Schlechte Durchführung", description = "Die Defias planen, die Moloch fertigzustellen und damit Sturmwind in Schutt und Asche zu legen. Es ist eine ehrenvolle Aufgabe und eine, die jeder wahre Orckrieger ohne zu zögern annehmen würde!\n\nVanessas Fehler ist die Ausführung ihres Plans. Das Schiff ist mangelhaft konstruiert, die Crew ohne Erfahrung und, was am schlimmsten ist, da ist dieser Worgen unter ihnen!\n\nSein Name ist Admiral Knurrreißer und er muss ohne jede Gnade im Namen des Kriegshäuptlings erschlagen werden. Lok'tar ogar!", sourceObjective = "Tötet Admiral Knurrreißer.", progress = "Ja?", completion = "Es ist wirklich eine Schande, dass er sowohl ein Mensch als auch ein Worgen war. Wäre er ein stolzer Orckrieger gewesen, hätte mein Herz höher geschlagen, Seite an Seite mit solch einem wilden Streiter in die Schlacht zu stürmen.\n\nWir können ein andermal von unerfüllten Wünschen sprechen. Es ist an der Zeit, dem Feind zu entringen, was uns gehört.", sourceObjectiveStatus = "unverified-source-field" }
quests[27849] = { id = 27849, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf Steinard", description = "Das ist es, {name}. Wir haben es endlich nach Steinard geschafft.\n\nIch sollte zwar niemanden daran erinnern müssen, tue es aber trotzdem: Wir sind keine Orcs, und wir werden auch wegen Rachegelüsten und Boshaftigkeit nicht zu welchen werden. Steinard wird nicht dem Erdboden gleichgemacht werden, damit wir auf seiner Asche tanzen.\n\nNein, ich will, dass das hier auf anständige Art gemacht wird. Ein chirugischer Eingriff. Haltet Euren Kopf aufrecht und erschlagt jeden Orc, der eine Waffe auf Euch richtet.", sourceObjective = "Erschlagt 6 Verteidiger von Steinard.", completion = "Ihr habt Euren Befehlen ausgezeichnet Folge geleistet, {name}. Im Namen der Krone belobige ich Euch für Euren Mut auf dem Schlachtfeld.", sourceObjectiveStatus = "unverified-source-field" }
quests[27850] = { id = 27850, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nummer Eins der Defias", description = "Die Zerschmetterte Hand hat sich jahrelang im Hintergrund gehalten.\n\nDas hat nun ein Ende! Ihr werdet das Instrument unserer Wiedergeburt sein, {name}. Erschlagt die Nummer Eins der Defias und erbeutet ihr Schiff zum Ruhme der Horde! Wir werden sie wie ein richtiges Orckriegsschiff ausstatten und Sturmwind endlich in Schutt und Asche legen!\n\nJeder Überlebende wird die Kunde unserer unaufhaltsamen Macht in ganz Azeroth verbreiten und alle werden vor uns erzittern!\n\nGeht jetzt. Van Cleefs Tod wird Eure bisher größte Tat darstellen, Held!", sourceObjective = "Tötet die Nummer Eins der Defias.", completion = "FEIGLING!!! Vanessa van Cleef ist ein dreckiger Feigling von einem Menschen! Wie kann sie es wagen, einem Kampf mit der Horde zu entfliehen und ihre unwürdigen Lakaien zurückzulassen?\n\n<Kagtha beruhigt sich wieder.>\n\nUnwichtig. Ihr Schiff ist Belohnung genug. Die Einwohner Sturmwinds werden aus erster Hand erfahren, wie sich unsere Ehrfurcht gebietende Macht anfühlt, wenn wir sie mit einem Schiff angreifen, das zum Teil vom selben Architekten gebaut worden ist, der auch ihre Stadt erbaut hat!", sourceObjectiveStatus = "unverified-source-field" }
quests[27851] = { id = 27851, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachschubunterbrechung", description = "Wir werden Steinard zwar nicht dem Erdboden gleichmachen, aber ich will kein zweites Mal dort hineingehen müssen.\n\nSammelt alle Vorräte, die Ihr seht, wenn Ihr in der Stadt seid. Ohne Nahrung werden ihnen nach einem Tag keine Kämpfer mehr bleiben.\n\nEs sollten in der ganzen Stadt Kisten herumstehen.", sourceObjective = "Erbeutet 5 Kisten mit Vorräten von Steinard.", progress = "Wie ist die Lage?", completion = "Gute Arbeit, {name}. Dank dieser Kisten ist es nur eine Frage der Zeit, bis die Orcs zum Portal fliehen oder darum betteln, sich ergeben zu dürfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27852] = { id = 27852, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orcs und Menschen", description = "Der Krieg tobt im Sumpf, {name}. Niederträchtige Menschen haben sich nördlich der Stadt niedergelassen und eine Armee an unsere Türschwelle gebracht.\n\nIn diesem Sumpf gibt es für sie nichts zu holen. Der einzige Grund, weswegen sie hier sind, ist, uns unprovoziert anzugreifen!\n\nWir sind unterbemannt und brauchen jeden fähigen Orc, um zu kämpfen. Geht und erschlagt so viele Menschen, wie Ihr nur könnt!", sourceObjective = "Tötet 10 Fußsoldaten der Sumpftidenwacht.", completion = "Wir werden bis auf den letzten Orc kämpfen, {name}. Ich hoffe, Ihr könnt Euch lange genug am Leben erhalten, um diese Eindringlinge gründlich zu vernichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27853] = { id = 27853, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trampel", description = "Die Allianz ist uns zahlenmäßig überlegen. In ihrer Angst entsenden sie eine Armee, um eine einzelne Siedlung zu zerstören. Aber wir werden nicht aufgeben!\n\nWenn sie keine Resourcen haben, werden ihre Soldaten im Nachteil sein. Menschliche Bauern sind damit beschäftigt, in den Wäldern außerhalb der Sumpftidenwacht Holz zu sammeln, um ihre einstürzenden Wälle wieder aufzubauen.\n\nVersagt ihnen das Holz - und ihr Leben.", sourceObjective = "Tötet 5 Bauern der Sumpftidenwacht.", completion = "Kein wahres Mitglied der Horde sollte Gefallen daran finden, solch verängstigte Schwächlinge zu töten... dem Sieg fehlt zum Nervenkitzel dann die Herausforderung.\n\nDoch Eure schmutzige Arbeit hat dazu beigetragen, dass wir die Allianz abwehren und unser Zuhause hier schützen konnten. Seid stolz auf Eure Arbeit für die Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[27854] = { id = 27854, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flut der Dunkelheit", description = "Wir mussten schwere Verluste einstecken, {name}. Die Feste Schreckensfels hat Oger aus den Verwüsteten Landen als Verstärkung geschickt, aber ihre Zahl ist begrenzt. Die Allianz setzt ihnen genau in diesem Moment zu.\n\nDie Allianz versucht, mit Rittern gegen unsere Oger vorzugehen. Diese Strategie hat ihnen schon im Zweiten Krieg gute Dienste geleistet. Wir müssen unsere stärksten Krieger einsetzen, wenn wir die Schlacht für uns entscheiden wollen!\n\nKehrt zum Blutsumpf zurück, {name}, und bringt diese Ritter zu Fall!", sourceObjective = "Tötet 6 Ritter der Sumpftidenwacht.", completion = "Ihr seid ein wahrer Champion, {name}, dass Ihr auf dem Schlachtfeld so vielen das Leben genommen habt. Ich hoffe, dass es ausreicht, um Steinard zu retten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27855] = { id = 27855, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstärkung abgelehnt", description = "Die Allianz hat ihre Magier mitgebracht, um weitere Verstärkung von hinter ihrer Festung direkt auf das Schlachtfeld zu bringen. Das muss unterbunden werden!\n\nEs sind ihrer nur wenige, aber ein einziges Portal kann schon den Ausgang der Schlacht verändern. Greift ihre Magier an und zerstört diese Portale!", sourceObjective = "Tötet 3 Magier der Sumpftidenwacht.", completion = "Ohne eine Verbindung zur Außenwelt muss sich die Allianz auf das verlassen, was sie in die Sümpfe mitgebracht hat. Wollen wir doch mal sehen, wie sie mit unserer vertrauten Umwelt fertigwerden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27856] = { id = 27856, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Markiert die Gefallenen", description = "Viele Krieger haben den Tod gefunden, um uns den Sieg zu bringen, {name}. Das ist das Schicksal eines wahren Orcs.\n\nIch habe gesehen, wie die Allianz die Leichen unserer Gefallenen plündert und sich wie Hamster an unseren Sachen festklammert. Sie werden nicht unsere gefallenen Helden auf diesem Schlachtfeld entehren.\n\nNehmt diese Banner mit Euch in den Blutsumpf. Platziert sie auf die Leichen unserer gefallenen Krieger. Ich werde Euch beobachten, damit ich sehe, wie viele gefallen sind und um ihr Opfer zu ehren. Hoffen wir, dass die Geister uns helfen, unseren Respekt zu erweisen.", sourceObjective = "Benutzt das Banner der Gefallenen, um 7 gefallene Krieger von Steinard zu markieren.", completion = "Mit Eurem Mut ehrt Ihr sowohl die Toten als auch die Lebenden, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27857] = { id = 27857, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir werden angegriffen!", description = "Die Allianz hat unsere Mauern erreicht!\n\n{name}, Euer Handeln hat ihren Vorstoß verlangsamt, doch sind sie uns zahlenmäßig immer noch weit überlegen. Dies wird unser letztes Gefecht sein. Sieg oder Tod...\n\nIch wünsche Euch einen ehrenhaften Kampf, {name}. In diesem Augenblick toben die Kämpfe bereits innerhalb unserer Mauern. Treibt diese Bestien aus Steinard. Für die Horde!", sourceObjective = "Tötet 12 Eindringlinge der Sumpftidenwacht.", progress = "Es bleibt keine Zeit! Geht! Kämpft!", completion = "Die Allianz wurde vertrieben. Steinard ist dank Eures Mutes wieder sicher! Lok'tar Ogar!", sourceObjectiveStatus = "unverified-source-field" }
quests[27858] = { id = 27858, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rheastraszas Geschenk", description = "Wartet hier. Ich werde das Ei holen.", sourceObjective = "Wartet, während Rhea das Ei aus dem Versteckten Gelege holt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27859] = { id = 27859, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ei lebt weiter", sourceObjective = "Wartet, während Rhea das Ei aus dem Versteckten Gelege holt.", completion = "Ihr wart nicht der einzige Sterbliche, dem sich Rheastrasza anvertraut hat. Auch ich habe das Vertrauen des Drachen gewonnen.\n\nIch habe bereits das echte, gereinigte Ei an einen sichereren Ort weitab vom Ödland geschafft. Es wird weiter wachsen, ohne dass Todesschwinge seinen Aufenthaltsort kennt.\n\nDie Macht des roten Drachenschwarms wird nur von seiner Güte übertroffen. Rheastraszas letzter Wunsch war es, dass ich Euch dies gebe.", sourceObjectiveStatus = "unverified-source-field" }
quests[27860] = { id = 27860, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verirrten", description = "Als das Dunkle Portal sich vor vielen Jahren schloss, überkam viele von uns, die in dieses Land gekommen sind, Reue und Angst. In ihrer Verzweiflung verfluchten sie den Namen des Lichts und verfielen in Gewalttätigkeit und Hass.\n\nDiese gefallenen Seelen sind jetzt als die Verirrten bekannt. Sie sind kaum mehr als geistlose Monster, die alles anfallen, was sich ihnen nähert. Ihre Verderbtheit wächst mit jedem Tag. Und in ihrem Kampf ums Überleben haben sie jetzt begonnen, Leute aus dem Sicheren Hafen zu entführen.\n\nIhnen kann nicht mehr geholfen werden, {name}. Ihr Leiden muss ein Ende finden. Werdet Ihr sie aus ihrer Not befreien?", sourceObjective = "Tötet 12 Verirrte in der Zuflucht der Verirrten.", completion = "Meine Bitte an Euch bereitet meinem Herzen immer noch Qual, obwohl ich weiß, dass es keinen anderen Weg gibt. Ihr habt uns, die wir immer noch an unserem Verstand festhalten, vor einer schlimmen Bedrohung gerettet.", sourceObjectiveStatus = "unverified-source-field" }
quests[27861] = { id = 27861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schmelztiegel des Gemetzels: Haudrauf der Blutaugen!", description = "Ich hab mich schon gewundert, wann Ihr endlich hier aufkreuzt, {name}! Mit einem ehemaligen Champion aus dem Ring des Blutes wird es hier richtig was zu sehen geben! Wir werden reich sein, <Kumpel/Süße>! REICH!\n\nWie dem auch sei, hier ist eine alte Kampfgrube des Drachenmals. Wir mussten für unsere Bedürfnisse nicht viel daran ändern. Ich habe meine Fühler ein bisschen ausgestreckt, um die besten Schläger Azeroths für das Gemetzel zu finden. Es ist an der Zeit, Gold zu verdienen!\n\nIhr wisst ja, wie es abläuft, {name}. Wenn Ihr so weit seid, sagt Bescheid, und wir fangen mit der Vorstellung an!", sourceObjective = "Betretet die Arena im Schmelztiegel des Gemetzels und besiegt Strunz'blunz!", sourceObjectiveStatus = "unverified-source-field" }
quests[27862] = { id = 27862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schmelztiegel des Gemetzels: Haudrauf der Blutaugen!", description = "Na wenn das nicht unser ehemaliger Champion der Agonie ist! {name}, jetzt, da Ihr da seid, sehe ich eine Zukunft voller Gold! Wir werden im Gold baden, <Kumpel/Süße>! BADEN!\n\nWie dem auch sei, hier ist eine alte Kampfgrube des Drachenmals. Wir mussten für unsere Bedürfnisse nicht viel daran ändern. Ich habe meine Fühler ein bisschen ausgestreckt, um die besten Schläger Azeroths für das Gemetzel zu finden. Es ist an der Zeit, Gold zu verdienen!\n\nIhr wisst ja, wie es abläuft, {name}. Wenn Ihr so weit seid, sagt Bescheid, und wir fangen mit der Vorstellung an!", sourceObjective = "Betretet die Arena im Schmelztiegel des Gemetzels und besiegt Strunz'blunz!", sourceObjectiveStatus = "unverified-source-field" }
quests[27863] = { id = 27863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schmelztiegel des Gemetzels: Haudrauf der Blutaugen!", description = "Eins sag ich Euch, man kann hier natürlich nicht mit den Wogenden Ebenen von Nagrand oder der Arena in Zul'Drak vergleichen, aber hey, ich bin da, wo das Gold ist! Willkommen im Schattenhochland!\n\nIhr seid neu hier, also lasst mich Euch ein paar Sachen erklären. Ich bin der Kampfveranstalter und der angriffslustige Troll hier ist Wodin, mein Leibwächter. Ihr seid meine Unterhaltung. Wenn Ihr kämpfen wollt, sagt Bescheid, und ich finde den passenden Gegner für Euch.\n\nWenn Ihr mit Freunden hier seid, können wir auch gleich anfangen! Was meint Ihr?", sourceObjective = "Betretet die Arena im Schmelztiegel des Gemetzels und besiegt Strunz'blunz!", sourceObjectiveStatus = "unverified-source-field" }
quests[27864] = { id = 27864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schmelztiegel des Gemetzels: Todbringer des Drachenmals!", description = "Das wird Euch gefallen! Der Drachenmalklan hat gehört, dass Ihr die Arena betreten wollt und man ist wild entschlossen zu verhindern, dass Ihr sie wieder verlasst.\n\nJetzt ist es Zeit für ein bisschen Action, {race} gegen Orc! Sagt mir Bescheid, wenn Ihr dazu bereit seid!", sourceObjective = "Betretet die Arena am Schmelztiegel des Gemetzels und besiegt Torg Drachenschinder!", sourceObjectiveStatus = "unverified-source-field" }
quests[27865] = { id = 27865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schmelztiegel des Gemetzels: Der unberechenbare Wildhammer!", description = "Das wird Euch gefallen! Der Wildhammerklan habt gehört, dass Ihr die Arena betreten wollt und man ist wild entschlossen zu verhindern, dass Ihr sie wieder verlasst.\n\nJetzt ist es Zeit für ein bisschen Action, {race} gegen Zwerg! Sagt mir Bescheid, wenn Ihr dazu bereit seid!", sourceObjective = "Betretet die Arena am Schmelztiegel des Gemetzels und besiegt Sully Kniescheibler!", sourceObjectiveStatus = "unverified-source-field" }
quests[27866] = { id = 27866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schmelztiegel des Gemetzels: Calders Geschöpf!", description = "Grauenvoll und blutig - die nächste Paarung wird die Menge auf jeden Fall zum Stöhnen bringen. Calder Grau hat die Körperteile seiner besiegten Herausforderer aufgesammelt und daraus den perfekten Champion gebaut.\n\nDieses Ding ist die ultimative Zusammensetzung zusammengeschusterter zombifizierter Zweikämpfer. Eine mörderische Mixtur matschiger Monstrositäten. Seid Ihr bereit für das Chaos?! Ich bin es! Sagt mir Bescheid, wenn Ihr bereit seid, damit wir anfangen können!", sourceObjective = "Betretet die Arena am Schmelztiegel des Gemetzels und besiegt die Kadavercollage!", sourceObjectiveStatus = "unverified-source-field" }
quests[27867] = { id = 27867, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schmelztiegel des Gemetzels: Der Graf des Ausweidens!", description = "Mit dem hier werdet Ihr alle Hände voll zu tun haben, Kumpel. Wir haben hier einen erfahrenen Ehrenmann und Krieger! Er stammt aus Gilneas und will beweisen, dass er der beste Krieger diesseits von Azeroth ist.\n\nAlso schnürt Euch Eure Stiefel und gürtet die Hose, denn hier drin wird's jetzt richtig zur Sache geh'n. Sagt Bescheid, wenn Ihr was auf die Ohren bekommen wollt.", sourceObjective = "Betretet die Arena am Schmelztiegel des Gemetzels und besiegt Lord Geoffery Tulvan!", completion = "Das habt Ihr wirklich gut hinbekommen. Ich dachte, Ihr hättet es hinter Euch, als er sich in einen Wolf verwandelte und anfing, die Arena in Stücke zu reißen. Aber allmählich sollte ich wohl wissen, dass Ihr nicht so einfach kleinzukriegen seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[27868] = { id = 27868, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schmelztiegel des Gemetzels: Der Schattenterror!", description = "Wir haben jemanden hier, den Ihr mit Sicherheit nur allzu gern hassen werdet. Zunächst war ich nicht sicher, ob wir ihn in die Grube lassen sollten, aber ein Kampf ist ein Kampf! Und wer bin ich schon, dass ich sicheres Geld ablehne?!\n\nDieser Kerl kommt aus der Schattenzitadelle und ist bewaffnet mit einem heißen Schlag. Ihr solltet Euch lieber schnell bewegen und immer auf der Hut sein! Sagt Bescheid, wenn Ihr für ein wenig Action bereit seid.", sourceObjective = "Betretet die Arena am Schmelztiegel des Gemetzels und besiegt Glutnarbe den Verschlinger!", sourceObjectiveStatus = "unverified-source-field" }
quests[27869] = { id = 27869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Drache und der Tempel", description = "Diese Schlangen müssen aus dem Tempel von Atal'Hakkar kommen. Ich hatte bereits einen Hinweis...\n\nVor ein paar Tagen hatte ich einen Besucher, der meinte, ich solle die Augen nach dergleichen aufhalten. Ein Elf mit Namen Itharius. Ich glaube nicht, dass er wusste, dass ich sein Äußeres durchschauen konnte... Er war ein grüner Drache in Verkleidung. Wollte bestimmt seinen gefallenen Brüdern helfen.\n\nEr ist sicher hinter irgendwas her. Itharius ist zum Tempel selbst aufgebrochen. Vielleicht sucht Ihr dort besser nach ihm. Irgendetwas Übles geht hier vor.", sourceObjective = "Redet mit Lord Itharius oben auf den äußeren Stufen des Tempels von Atal'Hakkar.", completion = "Das Goblinmädchen schickt Euch? Sie hat ein gutes Auge, die Kleine.\n\nSie spricht die Wahrheit. Ich bin hier, um die Flut der Verderbnis, die von diesem Tempel ausströmt, aufzuhalten. Wenn Ihr Euer Volk vor einem üblen Schicksal bewahren wollt, {name}, dann bitte ich um Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[27870] = { id = 27870, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zur Sumpftidenwacht", description = "Egal, ob Ihr mir im Tempel helft oder nicht, Euer Volk muss erfahren, was hier vor sich geht.\n\nNördlich des Tempels haben ein paar Menschen Eurer Allianz der Sterblichen einen Posten errichtet, den sie die Sumpftidenwacht nennen. Sie führen überall im Sumpf Krieg gegen die Horde, und ich fürchte, dass dieser Konflikt sich noch weiter ausbreitet.\n\nEs ist nicht meine Aufgabe, mich in die Angelegenheiten der Sterblichen einzumischen, {name}. Ich bitte Euch einfach nur, Euer Volk davor zu warnen, was im Tempel lauert.", sourceObjective = "Sprecht mit Joanna Blauherz bei der Sumpftidenwacht.", completion = "Ärger im Tempel... Ich wünschte, wir hätten genügend Streitkräfte, um uns darum zu kümmern. Der Krieg mit Steinard ist bereits im vollen Gange. Wir brauchen jeden Mann, den wir kriegen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[27871] = { id = 27871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Steinard", description = "Egal, ob Ihr mir im Tempel helft oder nicht, Euer Volk muss erfahren, was hier vor sich geht.\n\nSüdwestlich des Tempels liegt die Hordenstadt Steinard. Die Orcs dort führen mit den neu in den Sümpfen angekommenen Menschen Krieg, und ich fürchte, dass dieser Konflikt sich noch weiter ausbreitet.\n\nEs ist nicht meine Aufgabe, mich in die Angelegenheiten der Sterblichen einzumischen, {name}. Ich bitte Euch einfach nur, Euer Volk davor zu warnen, was im Tempel lauert.", sourceObjective = "Sprecht mit Zentralenkommandant Ruag in Steinard in den Sümpfen des Elends.", completion = "Wir haben keine Zeit, um Orcs in den Tempel zu schicken, {name}. Die Menschen kommen in großen Scharen. Wir müssen Steinard verteidigen!", sourceObjectiveStatus = "unverified-source-field" }
quests[27872] = { id = 27872, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tortolla Hub Complete" }
quests[27873] = { id = 27873, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aviana Hub Complete" }
quests[27874] = { id = 27874, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Avianas Vermächtnis", description = "Eure Erfahrung wird woanders gebraucht, {name}.\n\nDirekt südwestlich des Weltenbaums findet Ihr den Schrein von Aviana, Heimat der Druiden der Kralle. Aviana, die oberste Mutter aller geflügelten Kreaturen, hat ihr Leben vor zehntausend Jahren für diese Welt hergegeben.\n\nIch spüre, dass ihr Schrein in Gefahr ist, genau wie die Druiden, die ihn bewachen. Sucht Choluna, einen der weisesten der geflügelten Druiden, tief innerhalb des Schreins auf.", sourceObjective = "Findet Choluna im Schrein von Aviana auf dem Hyjal.", completion = "Ysera selbst schickt Euch zu mir? Oh! Welch eine Ehre, mit einem Abgesandten der Aspekte zu sprechen.\n\nEs stimmt, dass unser Schrein in Gefahr ist. Die Harpyien, denen unsere Äste Schutz boten, haben sich gegen uns gewandt.\n\nDoch bitte stürzt Euch nicht in die Schlacht, bis Ihr nicht bereit seid. Unser Schrein ist nicht wie ein gewöhnliches Schlachtfeld. Benutzt seine Ruhe und Macht, um Eure Mitte zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27875] = { id = 27875, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gebetsblume", description = "Ich habe jahrelang daran gearbeitet, die Krankheit der Zerschlagenen heilen zu können. Die verruchten Energien, die sie verdorben haben, haben mehr getan, als nur ihre Körper zu verunstalten... Sie haben ihnen das Licht geraubt. Sie können seine Wärme nicht spüren.\n\nIch kann Magtoor nicht der Dunkelheit überlassen, {name}. Bevor es mit ihm schlimmer wurde, habe ich die Gebetsblume untersucht, die im Wabersumpf gedeiht. Selbst im dunkelsten Schatten wächst sie dort. Ich flehe Euch an, bringt mir einige davon, um des armen Magtoors Willen.", sourceObjective = "Sammelt 10 Zweige der Gebetsblume im Wabersumpf.", progress = "Habt Ihr die Gebetsblume dabei?", completion = "Die Zerschlagenen haben seit ihrer Ankunft in diesem Sumpf Gebetsblumen als Heilmittel verwendet. Wenn sie körperliche Schmerzen lindern, können sie vielleicht auch für mächtigere Heilungen verwendet werden...", sourceObjectiveStatus = "unverified-source-field" }
quests[27876] = { id = 27876, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geheimnisse des Sumpfes", description = "Der Wabersumpf verdankt seinen Namen einem einzigartigen Phänomen. Durch irgendeine Kraft angetrieben, sammelt sich der extrem feine Schlick und bewegt sich von allein vorwärts, als wäre er lebendig.\n\nZuerst war ich beunruhigt, dass dies eine verderbliche Kraft sei, aber meine Studien ergaben das Gegenteil: Welche Energie auch immer diesem Boden Leben einhaucht, sie ist positiver Natur. Vielleicht könnten auch die Zerschlagenen auf diese Art zu ihrem früheren Selbst wiedererweckt werden.\n\nDer Schlick mag es vielleicht nicht, eingesammelt zu werden, {name}, aber bitte tut es trotzdem.", sourceObjective = "Sammelt 10 Exemplare kräftigen Schlick von Wabersumpfklumpen.", progress = "Konntet Ihr die Proben besorgen?", completion = "Wir werden es reinigen müssen, aber dann wird es sich als äußerst hilfreich erweisen. Danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[27877] = { id = 27877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schwachkopfliga", description = "Ich brauche Eure Hilfe bei einem kleinen Projekt, an dem ich arbeite, {name}. Es fällt in einen Bereich, den ich gerne als \"defensive Archäologie\" bezeichne.\n\nIch möchte nichtmagische Gegenstände an verdächtigen Orten vergraben, damit diese Idioten der Allianz glauben, sie hätten etwas Wertvolles gefunden.\n\nHmm... An Hammerzehs Ausgrabungsstätte und der Festung Angor im Norden treiben sich die Dunkeleisenzwerge herum. Bringt mir ihre Köpfe. Ja, Ihr habt richtig verstanden, ihre Köpfe.\n\nSobald wir ihnen das Fleisch abgezogen haben, können wir die Schädel nutzen, um die Arbeiten der Zwerge zu stören.", sourceObjective = "Besorgt 15 Dunkeleisenköpfe.", progress = "<Lidia schaut Euch erwartungsvoll an.>", completion = "Ausgezeichnet! Wir werden sie sofort vergraben. Diese Dummköpfe der Forscherliga werden niemals darauf kommen, dass wir das waren!", sourceObjectiveStatus = "unverified-source-field" }
quests[27878] = { id = 27878, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewaltsame Aneignung", description = "Ich habe Euch einen kleinen Vorschlag zu machen, wenn Ihr interessiert seid.\n\nDie Dunkeleisenzwerge waren schon lange vor uns hier. Das heißt, dass die Zwerge als Erste dort waren, als die Titanenruinen zum Vorschein kamen, und sich die wertvollsten Gegenstände unter den Nagel gerissen haben. Ich wette, diese Schätze sind noch immer in der Festung Angor, nordwestlich von hier, unter Verschluss.\n\nWenn Ihr einen solchen Schatz haben wollt... stehlt ihn einfach.", sourceObjective = "Sucht im untersten Geschoss der Festung Angor nach Schätzen.", progress = "So früh schon zurück?", completion = "Ich wusste es! Der Oberste Prüfer wird das mit Freuden sehen.\n\nGute Arbeit, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27879] = { id = 27879, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überleben der Dicksten", description = "Uns gehen die Vorräte zur Neige, <Fremder/Fremde>. Solange die schwarzen Drachen unsere Jagdgründe mit Zerstörung überziehen, haben wir keine Chance, an Nahrung zu gelangen.\n\nDie Oger im Süden jedoch haben genau, was wir brauchen. In ihrer Grotte solltet Ihr ausreichend Nahrung und Handwerkswaren finden.\n\nSie könnten sich aber mit Euch darum schlagen wollen. Seid also vorsichtig.", sourceObjective = "Erlangt 6 Fleischstücke der Staubspeier und 10 Lagen Seide der Staubspeier.", progress = "Willkommen zurück.", completion = "Ich nehme an, die Oger waren für Euch keine zu große Hürde. Hier - ein paar Münzen für Eure Mühen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27880] = { id = 27880, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tonnenschwere Starrköpfe", description = "Meine Grunzer haben dieses Drachenproblem im Griff. Im Übrigen kann ich nicht zulassen, dass ein Grünschnabel wie Ihr, {class}, dort hineinrennt und unsere Schlachtpläne ruiniert.\n\nIhr wollt Arbeit? Na schön, ich gebe Euch Arbeit, Untersucht das Ogerlager im Südwesten. Nach dem, was ich höre, scheint eine kleine Armee Kämpfer vor ihrem Unterschlupf aufgetaucht zu sein.\n\nWir können nicht herumsitzen und warten, bis sie uns in die Flanke fallen, <Soldat/Soldatin>... zumal wir bereits von schwarzen Drachen in Kämpfe verwickelt werden. Dünnt ihre Ränge aus, bevor sie es mit den unseren tun.", sourceObjective = "Tötet 12 Kämpfer der Staubspeier. Ihr könnt sowohl Raufer als auch Schamanen der Staubspeier töten.", completion = "Ihr habt den Hauch eines Helden in Euch, {race}.\n\nJetzt verschwindet von meinem Schlachtfeld.", sourceObjectiveStatus = "unverified-source-field" }
quests[27881] = { id = 27881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutwächterposten", description = "Ich habe eine Idee, die reine Spekulation ist. Zum Glück sind reine Spekulationen eine meiner Spezialitäten.\n\nNördlich von hier hat die Archäologische Akademie neue Ruinen der Titanen unter dem Sand gefunden. Wenn es jemanden gibt, der älter und weiser ist als die Drachen, sind es die Titanen. Ich habe sogar Gerüchte gehört, dass die Titanen die Drachen ERSCHAFFEN haben.\n\nSprecht mit dem Obersten Prüfer Tae'thelan Blutwächter in seinem Lager nordöstlich von hier. Er wird weitaus mehr über die Titanen wissen als ich.\n\nWas habe ich Euch gesagt? Reine Spekulation.", sourceObjective = "Sprecht mit dem Obersten Prüfer Tae'thelan Blutwächter am Blutwächterposten im Ödland.", completion = "Titanen? Ihr seid hier, um mit mir über die Titanen zu reden?\n\nDa seid Ihr am richtigen Ort, denn wir stehen kurz vor einer großen Entdeckung. Doch zuerst werdet Ihr Euch Euren Platz hier verdienen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27882] = { id = 27882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es geht nicht um Geschichte, sondern um Macht", description = "Die Forscherliga mag ja einiges über den Vorgang des Grabens wissen. Was ihnen allerdings fehlt, ist ein Gefühl dafür, wie man die Artefakte BENUTZT, die sie ausgraben. Sie stellen ihre Schätze in statische Museen, statt diese mächtigen Dinge gemäß ihrer wahren Bestimmung zu verwenden.\n\nDie Zwerge sind Narren. Zum Glück sterben sie sehr schnell.\n\nIhr findet sie nördlich von hier, wie sie in die Wände der Schlucht hineingraben. Reißt ihnen alles, was Ihr könnt, aus ihren Händen mit den Stummelfingern und bringt es mir.", sourceObjective = "Beschafft einen zerbrochenen Kelch, eine staubige Vase, eine irdene Hieroglyphe und ein Troggwerkzeug.", progress = "Ihr seid mit den befreiten Artefakten zurückgekehrt, nehme ich an?", completion = "Kelch... wertlos.\n\nVase... gefälscht.\n\nHieroglyphe... interessant, aber ziemlich weit verbreitet.\n\nWas ist das? Ich habe noch nie Trogghandwerkskunst von diesem Ausmaß gesehen! Da seid Ihr tatsächlich etwas äußerst Seltenem begegnet, {name}.\n\nWir dürfen keineswegs die Troggs einfach übersehen. Sie mögen von schlichtem Gemüt sein, aber sie wissen Dinge über die tiefen, versteckten Orte dieser Welt.\n\nIhr habt Eure Arbeit recht ordentlich gemacht. Reden wir über Titanen, ja?", sourceObjectiveStatus = "unverified-source-field" }
quests[27883] = { id = 27883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Bauer des Wächters", description = "Einer der wenigen Gegenstände von Wert, die wir aus diesen Ruinen mitgenommen haben, ist diese kleine Jadestatue.\n\nWir glauben, es ist eine Art Schlüssel, aber wir konnten nicht feststellen, was sie öffnet. Daher ist sie nutzlos für mich.\n\nVielleicht werdet Ihr mehr Glück damit haben.", sourceObjective = "Findet im Grab der Wächter im Ödland Verwendung für den Bauer des Wächters.\n\nBereitgestellter Gegenstand:", completion = "<Die Statue rastet in ihren Platz auf der großen Steinplatte ein.>", sourceObjectiveStatus = "unverified-source-field" }
quests[27884] = { id = 27884, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Bauer der Schildwache", description = "Wir haben diese kleine rote Statue bei der Leiche eines dieser Forscherliga-Archäologen gefunden. Leider waren es nicht wir, die sie umgebracht haben. Die örtliche Wildnis hatte das bereits übernommen.\n\nDie Statue ist schön gearbeitet, hat aber anscheinend ihre magische Kraft verloren. Ihr könnt mit ihr machen, was immer Ihr für richtig haltet.", sourceObjective = "Findet eine Verwendung für den Bauern der Schildwache innerhalb des Tempels des Grabes der Behüter im Ödland.", completion = "<Die Statue gleitet über den kalten Marmorboden und rastet ein.>", sourceObjectiveStatus = "unverified-source-field" }
quests[27885] = { id = 27885, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Spiel des Wächters", description = "Ihr seht, wie sich die Statue erst in zwei, dann in vier, dann in acht identische Statuen in quadratischer Anordnung teilt.\n\nIhr hört eine Stimme, jedoch nicht mit Euren Ohren, sondern direkt in Eurem Kopf:\n\n\"Ein wahrer Wächter sieht nicht nach AUSSEN, um nach Anzeichen der Gefahr zu suchen.\n\n Ein wahrer Wächter richtet seinen Blick nach INNEN, immer darauf konzentriert, seine Beute zu schützen.\"\n\nVielleicht ist dies eine Art Rätsel?", sourceObjective = "Beendet das Spiel des Wächters, indem Ihr die Bauern des Wächters in eine nach innen gerichtete Position teleportiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[27886] = { id = 27886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schildwachenspiel", description = "Als Ihr die Statue an ihren Platz stellt, erscheinen weitere steinerne Statuen in dem Raum. Es taucht auch eine rubinfarbene Statue auf, in einer kleinen Nische am hinteren Ende des Raums. Ihr hört eine Stimme:\n\n \"Die Schildwache sieht.\n Die Schildwache beschützt.\n Der Blick der Schildwache ist niemals abgelenkt.\"\n\nDiese rote Statue am anderen Ende des Raums sieht wichtig aus. Vielleicht solltet Ihr versuchen, die beiden roten Statuen zu verbinden?", sourceObjective = "Schließt das Spiel der Schildwache ab, indem Ihr die beiden roten Statuen verbindet.", sourceObjectiveStatus = "unverified-source-field" }
quests[27887] = { id = 27887, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uralte Beschützer", description = "Man hört ganz schön viel Gerumpel aus der zentralen Kammer des Grabes. Diese zwei großen Statuen sahen ganz schön verdächtig aus.", sourceObjective = "Untersucht den Wächter und die Schildwache.", sourceObjectiveStatus = "unverified-source-field" }
quests[27888] = { id = 27888, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zu Blam", description = "Innerhalb der Kiste findet Ihr einen kleinen, runden Gegenstand, der auf einem Kissen liegt.\n\nWenn es hier unten ein Titanenartefakt geben sollte, dann muss es das sein. Ihr beschließt, ihn zu Dr. Blam zurückzubringen.", sourceObjective = "Bringt das Auge der Behüter zu Dr. Hieronymus Blam bei der Agmondkuppe im Ödland.", progress = "Und? Hat sich unser Schuss ins Blaue ausgezahlt?", completion = "Bloß ein winzig kleines Gerät?\n\nIch habe diese Titanen noch nie verstanden.\n\nNun gut! Wollen wir doch mal sehen, was dieser Piepser kann!", sourceObjectiveStatus = "unverified-source-field" }
quests[27889] = { id = 27889, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neu-Kargath", description = "<Dr. Blam sieht sich das Ei schweigend an, zwinkert ein paar Mal und schaut Euch dann an.>\n\nHabt... Habt Ihr das gesehen? Unglaublich! Meine Idee mit dem Titanending hat funktioniert! Mit Eurer Hilfe, natürlich.\n\nWir sollten das hier zu Rhea bringen. Sie ist nicht mehr in der Lethlorklamm... Ihre Tarnung ist wohl aufgeflogen, als sie vor all diesen Welpen ihre wahre Form angenommen hat. Jetzt ist sie in einer großen Hordenniederlassung im Westen mit Namen \"Neu-Kargath\".\n\nSie wird auf Euch warten. Und auf das Ei.", sourceObjective = "Bringt das geläuterte Schwarzdrachenei zu Rhea in Neu-Kargath im Ödland.", progress = "Da habt Ihr aber eine ganz schön wertvolle Ladung dabei, {name}.", completion = "Ich nehme Euch das Ei nun ab. Wir müssen es schleunigst bebrüten... und verstecken. Eine Menge wütender Drachen suchen danach.\n\nEs ist übrigens schön, Euch wiederzusehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27890] = { id = 27890, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die harten Hunde", description = "In meiner Hast bei der Flucht aus der Lethlorklamm habe ich vergessen, mich um eine letzte Sache zu kümmern: Nyxondra. Sie ist frei und hat Alarm beim schwarzen Drachenschwarm ausgelöst. Der halbe Schwarm ist hier im westlichen Ödland und sucht nach dem Ei.\n\nIch kümmere mich darum, das Ei zu verstecken. Ihr kümmert Euch um einige der vorwitzigeren Drachen. Und Ihr werdet Hilfe dabei haben. Ich habe ein paar Söldner angeheuert, Ihr werdete sie in diesem Gasthaus finden.", sourceObjective = "Sprecht mit Amakkar in Neu-Kargath im Ödland.", completion = "Ihr seid der {race}, auf den wir gewartet haben? Wurde auch Zeit, dass Ihr hier seid. Ich warte schon darauf, mir die Beine zu vertreten.\n\nAbmarsch, Jungs! Gehen wir ein paar schwarze Drachen töten!", sourceObjectiveStatus = "unverified-source-field" }
quests[27891] = { id = 27891, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amakkar, der Alleskönner", description = "Bevor wir mit der Drachenjagd beginnen, lasst mich Euch ein bisschen erklären, wie ich kämpfe.\n\nIch bin nicht so stark oder robust wie diese zwei, aber ich hab ein paar Tricks im Ärmel. Auf Euren Befehl hin betäube ich Eure Feinde, um sie festzunageln. Ich habe auch immer ein paar Tränke auf Lager.\n\nWarum trainieren wir nicht ein bisschen zusammen? Auf in die Wildnis, dann werdet Ihr sehen, was es heißt, mit einem echten Orc zusammen zu kämpfen.", sourceObjective = "Benutzt 'Amakkars Nierenhieb' und 'Amakkars Taschentrank'.", completion = "Ich freue mich darauf, an Eurer Seite zu kämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27892] = { id = 27892, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jurrix der Vollstrecker", description = "Oh, Ihr wollt Euch unterhalten? Also schön.\n\nIch bin Jurrix, der einzige Söldner hier, der noch ein paar Gehirnzellen hat. Und der einzige, dessen Angriffe wirklich etwas bewirken. Diese lebenden Schilde um mich herum behalte ich nur, damit ich nicht getötet werde.\n\nHört zu, Ihr seid <der Chef/die Chefin> dieser Operation. Ihr müsst nur ein Wort sagen und ich werde einen Feuerball durch das Herz Eures Ziels jagen. Wenn das alles zu schnell geht, kann ich sogar die Zeit ein wenig verschieben, damit Ihr noch ein paar zusätzliche Angriffe unterbringen könnt.\n\nWarum versuchen wir nicht, gemeinsam zu kämpfen?", sourceObjective = "Benutzt 'Jurrix' Feuerstoß' und 'Jurrix' Zeitverschiebung'.", progress = "Wir sind noch nicht ganz bereit. Ein wenig mehr Übung und dann können wir uns dem Drachentöten widmen.", completion = "Ich glaube, Ihr seid bereit, {name}. Allmählich bekommt Ihr es in den Griff.", sourceObjectiveStatus = "unverified-source-field" }
quests[27893] = { id = 27893, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gargal, das Ungetüm", description = "Es ist Euch vielleicht nicht aufgefallen, aber für einen Orc bin ich recht groß.\n\nIch stelle sicher, dass meine beiden Kumpel hier nicht in zu große Schwierigkeiten geraten. Sie sind klein und haben nicht so einen großen Schild wie ich. Ich bin groß und kann ein paar Schläge von Monstern gut wegstecken! Außerdem kann ich es meistens schaffen, dass sie nur meinen Schild treffen!\n\nIch kann auch Euch beschützen. Kommt, gehen wir ein bisschen trainieren. Ich sorge dafür, dass die Gegner mich angreifen, nicht Euch.", sourceObjective = "Benutzt 'Gargals Schildwall' und 'Gargals mächtiger Ruf'.", progress = "Sorgt Euch nicht, kleiner {race}. Ich beschütze Euch.", completion = "Seht Ihr? Kein Grund zur Sorge, wenn Gargal da ist. Sagt mir nur Bescheid und ich beschütze Euch vor den Monstern.", sourceObjectiveStatus = "unverified-source-field" }
quests[27894] = { id = 27894, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zorn eines Drachenschwarms", description = "Hallo, {name}. Mir scheint, Ihr vier hattet genug Zeit, Euch anzufreunden.\n\nIch habe eine erste Aufgabe für Euch. Kalaran, ein uralter schwarzer Drache mit beträchtlicher Macht, hat sich der Jagd auf das von uns beschützte Ei angeschlossen. Wir müssen ihn aufhalten, bevor er ihm zu nahe kommt.\n\nIhr findet ihn und seine Diener im Staubbecken, östlich von Neu-Kargath. Sucht und besiegt ihn. Wahrscheinlich werdet Ihr die Hilfe Eurer neuen Söldnerverbündeten brauchen.", sourceObjective = "Tötet Kalaran den Vernichter und 4 Soldaten des dunklen Schwarms.", sourceObjectiveStatus = "unverified-source-field" }
quests[27895] = { id = 27895, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Jagd geht weiter", description = "Der schwarze Drachenschwarm meint es ernst. Wie Ihr wahrscheinlich bemerkt habt, hat er einen Großteil von Neu-Kargath an sich gerissen. Diese Truppen stehen unter dem Befehl von General Jirakka und seinem Champion Moldarr. Sie müssen aufgehalten werden.", sourceObjective = "Besiegt General Jirakka, Moldarr und 6 Mitglieder der Drachenbrut des dunklen Schwarms.", sourceObjectiveStatus = "unverified-source-field" }
quests[27896] = { id = 27896, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Leid und der Zorn", description = "Am meisten bereue ich, wie wir... nein, wie ich Nyxondra behandelt habe. Ich habe sie gezwungen, Eier zu legen, und dann mit ihnen experimentiert. Immer und immer und immer wieder.\n\nObwohl ich selbst Mutter bin, kann ich mir ihr Leid kaum vorstellen.\n\nNein... Ich darf nicht schwach werden. Unsere Arbeit dient immerhin dem Wohl der zukünftigen Generationen der schwarzen Drachen. Ihr Opfer war notwendig.\n\nNun umkreist sie die Ruinen von Kargath, nordwestlich von Neu-Kargath, wahnsinnig vor Zorn. Bitte, Helden... erlöst sie von ihrem Elend.", sourceObjective = "Erschlagt Nyxondra und 12 von Nyxondras Brutlingen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27897] = { id = 27897, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Versteckte Gelege", description = "Jetzt, da die meisten schwarzen Drachen aus dem Ödland abgezogen sind, können wir das Ei wieder sicher transportieren. Ihr werdet mich auf einer kleinen Hochebene nördlich von Neu-Kargath finden.\n\nSucht mich dort auf.", sourceObjective = "Sprecht mit Rhea im Versteckten Gelege im Ödland.", completion = "Das Ei muss immer in Bewegung bleiben. Wir sind hier nicht mehr sicher.\n\nSogar in seinem Wahnsinn kennt Todesschwinge alle versteckten Orte dieser Welt. Das Ei kann nicht an einem Ort bleiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[27898] = { id = 27898, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rheastraszas Geschenk", description = "Wartet hier. Ich werde das Ei holen.", sourceObjective = "Wartet, während Rhea das Ei aus dem Versteckten Gelege holt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27899] = { id = 27899, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Leuchten in seinen Augen", description = "Wenn Ihr nach Harrison sucht, den habt Ihr gerade verpasst.\n\nEr hat die ganze Zeit über seine neueste Entdeckung geredet und wie alles jetzt anfängt, einen Sinn zu ergeben.\n\nWie auch immer... Sein Gerede hat für mich keinen Sinn ergeben.\n\nIch habe versucht, ihn zum Hierbleiben zu bewegen und sich mit mir an ein paar Sonnenuntergängen in der Wüste zu erfreuen, aber wenn er dieses Leuchten in den Augen hat, kann man mit ihm nicht reden.\n\nKönntet Ihr einmal nach ihm sehen?\n\nEr ging nach Süden zu dem großen Monolith.", sourceObjective = "Sprecht mit Harrison Jones am Obelisk der Sonne.", completion = "Wie es scheint, bin ich nicht der einzige, der sich für diese Obelisken interessiert...", sourceObjectiveStatus = "unverified-source-field" }
quests[27900] = { id = 27900, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit dem Kerl werde ich fertig", description = "Gutes Timing, {name}.\n\nAnscheinend bin ich nicht der Einzige, der sich für diese Obelisken interessiert und diese Jungs haben kein Interesse an einem Erfahrungsaustausch.\n\nIch glaube, mit dem Kerl hier werde ich fertig.\n\nVielleicht könntet Ihr Euch um ein paar seiner Freunde kümmern, bevor sie auch hierher kommen?", sourceObjective = "Tötet 10 Lufteinheiten von Schnottz.", completion = "Welch eine Erleichterung. Danke {name}.\n\nWie sich herausstellt, habe ich hier alle Hände voll zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[27901] = { id = 27901, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie wissen nicht, was sie hier haben", description = "Hört zu, {name}. Ich habe nicht viel Zeit zum Reden.\n\nDiese Kerle graben hier Relikte aus und greifen sich die Teile uralter Technologie, die wir brauchen!\n\nIhr müsst ihre Kisten nach Teilen eines uralten Aktivierungsgerätes durchsuchen. Die Offiziere müssten die Codes haben, die Ihr zum Öffnen der Kisten benötigt.\n\nBeeilt Euch.\n\nWir dürfen nicht zulassen, dass sie das Zeug in ihre Flugzeuge laden!", sourceObjective = "Baut das Aktivierungsgerät der Titanen zusammen.", progress = "Habt Ihr das Aktivierungsgerät der Titanen, {name}?", completion = "Das ist es!\n\nGut gemacht, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[27902] = { id = 27902, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Reinquell", description = "Magtoor hat mir von dem Schamanismus berichtet, den die Zerschlagenen betreiben. Der große Nobundo sagte einst, dass der Pfad der Elemente in gewisser Weise nur ein weiterer Weg zum Licht sein könnte.\n\nIch kann nur hoffen, dass daran etwas Wahres ist. Die Elementare, die sich in der Nähe der Reinquellhöhle im Süden aufhalten, sind eine Quelle wahrlich makellosen Wassers. Sie können chaotisch und brutal sein, aber das von ihnen erbeutete reine Wasser ist die perfekte Leitung für den Segen des Lichts.\n\nBitte bringt mir dieses Wasser, {name}.", sourceObjective = "Sammelt 6 Reinquellpartikel von Reinquellelementaren.", progress = "Haben die Elemente ihre Quelle aufgegeben?", completion = "Solch eine Klarheit... Hoffen wir, dass dies dem armen Magtoor hilft.", sourceObjectiveStatus = "unverified-source-field" }
quests[27903] = { id = 27903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zündung", description = "Dieser Kerl lässt sich nicht unterkriegen!\n\nIhr macht Eure Sache gut, <mein Junge/meine Liebe>. Jetzt bleibt nur noch eins zu tun.\n\nMeine Forschungen haben ergeben, dass dort unten eine Titanenstatue sein müsste. Benutzt das Gerät, um sie zu aktivieren und nehmt sie dann auseinander.\n\nWenn meine Theorie richtig ist, verbirgt sich in der Statue der Schlüssel, um diesen Obelisken wieder zu aktivieren.", sourceObjective = "Besorgt die Linse der Sonne.", progress = "Zeit, herauszufinden, ob dieser alte Mechanismus noch funktioniert...", completion = "Laut Harrisons Notizen, sollte der Obelisk reaktiviert werden, wenn man die Linse auf dieses Podest legt.\n\nWas genau das bedeutet, werden wir dann sehen...", sourceObjectiveStatus = "unverified-source-field" }
quests[27904] = { id = 27904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nebelatem", description = "Die Grelle sind Waldgeister, die sich östlich von hier im Nebligen Tal aufhalten. Sie sehen zwar aus wie Wichtel, aber bei denen, die ich untersucht habe, konnte ich keine dämonischen Spuren feststellen. Soweit ich das sagen kann, sind sie unverderbt.\n\nDiejenigen, die im Tal leben, sind eins mit dem Wind. Sie beschwören Böen, wenn ihnen danach ist. Diese reine Luft kann ich vielleicht in meinem Heilmittel für den armen Magtoor verwenden.\n\nBitte, {name}, sammelt rauchgraue Kristalle für mich. Man findet sie in den Körpern der Grelle. Ich muss jedes mögliche Heilmittel ausprobieren.", sourceObjective = "Beschafft 5 rauchgraue Kristalle von Nebelgrellen.", progress = "Habt Ihr die Kristalle?", completion = "Hoffentlich werde ich mit ihnen eine Heilung finden, {name}. Danke, dass Ihr sie mir gebracht habt.", sourceObjectiveStatus = "unverified-source-field" }
